(373505,41501,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La piétonne ... sur les bandes blanches quand la caméra s''est élevée au-dessus du carrefour.'::text,'marchait'::text,'a marché'::text,'a marché'::text,'La piétonne marchait sur les bandes blanches quand la caméra s''est élevée au-dessus du carrefour.'::text),
(373508,41501,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kamera kavşağın üzerine yükseldiğinde yaya beyaz şeritlerin üzerinden ...'::text,'yürüyordu'::text,'yürüdü'::text,'yürüdü'::text,'Kamera kavşağın üzerine yükseldiğinde yaya beyaz şeritlerin üzerinden yürüyordu.'::text),
(373509,41501,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gyalogos éppen ... a fehér csíkokon, amikor a kamera a kereszteződés fölé emelkedett.'::text,'sétált'::text,'átsétált'::text,'átsétált'::text,'A gyalogos éppen sétált a fehér csíkokon, amikor a kamera a kereszteződés fölé emelkedett.'::text),
(373521,41503,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein einsamer Fußgänger ... gerade die Kreuzung, als plötzlich Hunderte weitere hereinströmten. Totales Chaos!'::text,'überquerte'::text,'überquerte'::text,'hat überquert'::text,'Ein einsamer Fußgänger überquerte gerade die Kreuzung, als plötzlich Hunderte weitere hereinströmten. Totales Chaos!'::text),
(373525,41503,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Самотній пішохід ... перехрестя, коли раптом ринули ще сотні. Повний хаос!'::text,'переходив'::text,'перейшов'::text,'перейшов'::text,'Самотній пішохід переходив перехрестя, коли раптом ринули ще сотні. Повний хаос!'::text),
(373524,41503,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un peatón solitario ... el cruce cuando de repente llegaron cientos más en tropel. ¡Caos total!'::text,'estaba cruzando'::text,'cruzó'::text,'ha cruzado'::text,'Un peatón solitario estaba cruzando el cruce cuando de repente llegaron cientos más en tropel. ¡Caos total!'::text),
(373523,41503,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un piéton solitaire ... le carrefour quand des centaines d''autres ont soudain déferlé. Chaos total !'::text,'traversait'::text,'a traversé'::text,'a traversé'::text,'Un piéton solitaire traversait le carrefour quand des centaines d''autres ont soudain déferlé. Chaos total !'::text),
(373526,41503,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalnız bir yaya kavşaktan ... ki birden yüzlercesi daha akın etti. Tam bir kaos!'::text,'geçiyordu'::text,'geçti'::text,'geçti'::text,'Yalnız bir yaya kavşaktan geçiyordu ki birden yüzlercesi daha akın etti. Tam bir kaos!'::text),
(373527,41503,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy magányos gyalogos éppen ... a kereszteződésen, amikor hirtelen még több száz ember özönlött be. Teljes káosz!'::text,'kelt át'::text,'átkelt'::text,'átkelt'::text,'Egy magányos gyalogos éppen kelt át a kereszteződésen, amikor hirtelen még több száz ember özönlött be. Teljes káosz!'::text),
(373530,41504,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hunderte Fußgänger haben diese Kreuzung schon ..., und die Autos warten seit einer Ewigkeit!'::text,'überquert'::text,'überquert'::text,'überquert'::text,'Hunderte Fußgänger haben diese Kreuzung schon überquert, und die Autos warten seit einer Ewigkeit!'::text),
(373534,41504,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сотні пішоходів уже ... це перехрестя, а машини чекають цілу вічність!'::text,'перейшли'::text,'переходять'::text,'перейшли'::text,'Сотні пішоходів уже перейшли це перехрестя, а машини чекають цілу вічність!'::text),
(373533,41504,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cientos de peatones ya ... este cruce, ¡y los coches llevan esperando una eternidad!'::text,'han cruzado'::text,'han estado cruzando'::text,'cruzaron'::text,'Cientos de peatones ya han cruzado este cruce, ¡y los coches llevan esperando una eternidad!'::text),
(373532,41504,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Déjà des centaines de piétons ... ce carrefour, et les voitures attendent depuis une éternité !'::text,'ont traversé'::text,'traversent'::text,'ont traversé'::text,'Déjà des centaines de piétons ont traversé ce carrefour, et les voitures attendent depuis une éternité !'::text),
(373535,41504,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yüzlerce yaya bu kavşaktan çoktan ..., arabalar ise bir asırdır bekliyor!'::text,'geçti'::text,'geçiyor'::text,'geçti'::text,'Yüzlerce yaya bu kavşaktan çoktan geçti, arabalar ise bir asırdır bekliyor!'::text),
(373536,41504,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már több száz gyalogos ... ezen a kereszteződésen, az autók meg már egy örökkévalóság óta várnak!'::text,'kelt át'::text,'kel át'::text,'kelt át'::text,'Már több száz gyalogos kelt át ezen a kereszteződésen, az autók meg már egy örökkévalóság óta várnak!'::text),
(373539,41505,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Fußgängerin hätte sich keine Sorgen ...; der Van würde bei Rot nie losfahren! Totale Panik für nichts!'::text,'machen müssen'::text,'machen dürfen'::text,'machen müssen'::text,'Die Fußgängerin hätte sich keine Sorgen machen müssen; der Van würde bei Rot nie losfahren! Totale Panik für nichts!'::text),
(373543,41505,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пішохідці ... хвилюватися: фургон ніколи не рушив би на червоний! Повна паніка на рівному місці!'::text,'не треба було'::text,'не можна було'::text,'не треба'::text,'Пішохідці не треба було хвилюватися: фургон ніколи не рушив би на червоний! Повна паніка на рівному місці!'::text),
(373542,41505,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La peatona ... preocuparse; ¡la furgoneta nunca se movería en rojo! ¡Pánico total para nada!'::text,'no tenía por qué'::text,'no debía'::text,'no tiene por qué'::text,'La peatona no tenía por qué preocuparse; ¡la furgoneta nunca se movería en rojo! ¡Pánico total para nada!'::text),
(373541,41505,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La piétonne ... s''inquiéter ; le van ne démarrerait jamais au rouge ! Panique totale pour rien !'::text,'n''avait pas besoin de'::text,'ne devait pas'::text,'n''a pas besoin de'::text,'La piétonne n''avait pas besoin de s''inquiéter ; le van ne démarrerait jamais au rouge ! Panique totale pour rien !'::text),
(373544,41505,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yayanın endişelenmesine hiç ...; minibüs kırmızıda asla hareket etmezdi! Boşuna tam bir panik!'::text,'gerek yoktu'::text,'gerek yoktu'::text,'gerek yok'::text,'Yayanın endişelenmesine hiç gerek yoktu; minibüs kırmızıda asla hareket etmezdi! Boşuna tam bir panik!'::text),
(373545,41505,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gyalogosnak ... aggódnia; a furgon pirosnál sosem indult volna el! Totál pánik semmiért!'::text,'nem kellett volna'::text,'nem lett volna szabad'::text,'nem kell'::text,'A gyalogosnak nem kellett volna aggódnia; a furgon pirosnál sosem indult volna el! Totál pánik semmiért!'::text),
(373548,41506,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, diese Fußgängerin hat sich ihren korallfarbenen Anzug ... lassen, nur um über diese Kreuzung zu gehen.'::text,'schneidern'::text,'schneidern'::text,'schneidern'::text,'Hör mal, ich hab gehört, diese Fußgängerin hat sich ihren korallfarbenen Anzug schneidern lassen, nur um über diese Kreuzung zu gehen.'::text),
(373552,41506,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що ця пішохідка ... свій кораловий костюм на замовлення, аби лише перейти це перехрестя.'::text,'пошила'::text,'пошити'::text,'пошити'::text,'Слухай, я чула, що ця пішохідка пошила свій кораловий костюм на замовлення, аби лише перейти це перехрестя.'::text),
(373551,41506,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me han dicho que esa peatona se mandó ... su traje coral solo para atravesar este cruce.'::text,'hacer a medida'::text,'hacer a medida'::text,'hacer a medida'::text,'Oye, me han dicho que esa peatona se mandó hacer a medida su traje coral solo para atravesar este cruce.'::text),
(373550,41506,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il paraît que cette piétonne a fait ... son tailleur corail rien que pour traverser ce carrefour.'::text,'faire sur mesure'::text,'faire sur mesure'::text,'faire sur mesure'::text,'Écoute, il paraît que cette piétonne a fait faire sur mesure son tailleur corail rien que pour traverser ce carrefour.'::text),
(373553,41506,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre o yaya mercan rengi takımını sırf bu kavşaktan geçmek için ısmarlama ...'::text,'diktirmiş'::text,'diktirmiş'::text,'diktirmiş'::text,'Dinle, duyduğuma göre o yaya mercan rengi takımını sırf bu kavşaktan geçmek için ısmarlama diktirmiş.'::text),
(373554,41506,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy az a gyalogos ... a korallszínű kosztümjét, csak hogy átkeljen ezen a kereszteződésen.'::text,'megvarratta'::text,'megvarratta'::text,'megvarratta'::text,'Figyelj, azt hallottam, hogy az a gyalogos megvarratta a korallszínű kosztümjét, csak hogy átkeljen ezen a kereszteződésen.'::text),
(373557,41507,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oh mein Gott, sie hat mir erzählt, jeder Fußgänger wünscht sich, die Ampeln ... länger grün.'::text,'blieben'::text,'bleiben'::text,'werden bleiben'::text,'Oh mein Gott, sie hat mir erzählt, jeder Fußgänger wünscht sich, die Ampeln blieben länger grün.'::text),
(373561,41507,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Боже мій, вона сказала мені, що кожен пішохід хоче, щоб світлофори ... зеленими довше.'::text,'залишалися'::text,'залишаються'::text,'залишатимуться'::text,'Боже мій, вона сказала мені, що кожен пішохід хоче, щоб світлофори залишалися зеленими довше.'::text),
(373560,41507,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dios mío, me dijo que todo peatón desea que los semáforos ... en verde más tiempo.'::text,'se quedaran'::text,'se quedan'::text,'se quedarán'::text,'Dios mío, me dijo que todo peatón desea que los semáforos se quedaran en verde más tiempo.'::text),
(373559,41507,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oh mon Dieu, elle m''a dit que chaque piéton aimerait que les feux ... verts plus longtemps.'::text,'restent'::text,'restent'::text,'resteront'::text,'Oh mon Dieu, elle m''a dit que chaque piéton aimerait que les feux restent verts plus longtemps.'::text),
(373562,41507,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aman Tanrım, bana dedi ki her yaya ışıkların daha uzun süre yeşil ... ister.'::text,'kalmasını'::text,'kalmasını'::text,'kalacağını'::text,'Aman Tanrım, bana dedi ki her yaya ışıkların daha uzun süre yeşil kalmasını ister.'::text),
(373563,41507,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te jó ég, azt mondta, hogy minden gyalogos azt szeretné, ha a lámpák tovább ... zöldek.'::text,'maradnának'::text,'maradnak'::text,'maradni fognak'::text,'Te jó ég, azt mondta, hogy minden gyalogos azt szeretné, ha a lámpák tovább maradnának zöldek.'::text),
(373575,41509,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du bist ... selbstbewusste Fußgängerin; dein Gang über die Kreuzung war echt smooth.'::text,'eine ziemlich'::text,'eine ziemlich'::text,'ziemlich'::text,'Ehrlich, du bist eine ziemlich selbstbewusste Fußgängerin; dein Gang über die Kreuzung war echt smooth.'::text),
(373579,41509,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... впевнена пішохідка; твоя хода через перехрестя була просто бездоганна.'::text,'досить'::text,'досить'::text,'досить'::text,'Чесно, ти досить впевнена пішохідка; твоя хода через перехрестя була просто бездоганна.'::text),
(373578,41509,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, eres ... peatona segura de sí misma; ese paseo por el cruce fue impecable.'::text,'toda una'::text,'toda una'::text,'bastante'::text,'La verdad, eres toda una peatona segura de sí misma; ese paseo por el cruce fue impecable.'::text),
(373577,41509,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu es ... piétonne sûre d''elle ; ta traversée du carrefour était trop fluide.'::text,'une sacrée'::text,'une sacrée'::text,'plutôt'::text,'Franchement, tu es une sacrée piétonne sûre d''elle ; ta traversée du carrefour était trop fluide.'::text),
(373580,41509,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen ... özgüvenli bir yayasın; kavşaktan geçişin çok havalıydı.'::text,'oldukça'::text,'oldukça'::text,'oldukça'::text,'Açıkçası sen oldukça özgüvenli bir yayasın; kavşaktan geçişin çok havalıydı.'::text),
(373581,41509,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te ... magabiztos gyalogos vagy; az az átkelés a kereszteződésen nagyon laza volt.'::text,'egy elég'::text,'egy elég'::text,'elég'::text,'Őszintén, te egy elég magabiztos gyalogos vagy; az az átkelés a kereszteződésen nagyon laza volt.'::text),
(373584,41510,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Van wartete an der roten Ampel, ... die Fußgängerin sicher über die Straße gehen konnte.'::text,'damit'::text,'im Falle von'::text,'trotz'::text,'Der Van wartete an der roten Ampel, damit die Fußgängerin sicher über die Straße gehen konnte.'::text),
(373588,41510,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Фургон чекав на червоне світло, ... пішохідка могла безпечно перейти.'::text,'щоб'::text,'у разі'::text,'попри'::text,'Фургон чекав на червоне світло, щоб пішохідка могла безпечно перейти.'::text),
(373587,41510,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La furgoneta esperó en el semáforo en rojo ... la peatona pudiera cruzar con seguridad.'::text,'para que'::text,'en caso de'::text,'a pesar de'::text,'La furgoneta esperó en el semáforo en rojo para que la peatona pudiera cruzar con seguridad.'::text),
(373586,41510,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le van a attendu au feu rouge ... la piétonne puisse traverser en toute sécurité.'::text,'pour que'::text,'en cas de'::text,'malgré'::text,'Le van a attendu au feu rouge pour que la piétonne puisse traverser en toute sécurité.'::text),
(373589,41510,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minibüs, yaya güvenle karşıya geçebilsin ... kırmızı ışıkta bekledi.'::text,'diye'::text,'durumunda'::text,'rağmen'::text,'Minibüs, yaya güvenle karşıya geçebilsin diye kırmızı ışıkta bekledi.'::text),
(373590,41510,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A furgon várt a piros lámpánál, ... a gyalogos biztonságosan átkelhessen.'::text,'hogy'::text,'abban az esetben'::text,'annak ellenére'::text,'A furgon várt a piros lámpánál, hogy a gyalogos biztonságosan átkelhessen.'::text),
(373593,41511,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis die Ampeln wieder umschalten, werden Hunderte Fußgänger die Kreuzung ...'::text,'überquert haben'::text,'überqueren'::text,'überquert'::text,'Bis die Ampeln wieder umschalten, werden Hunderte Fußgänger die Kreuzung überquert haben.'::text),
(373597,41511,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки світлофори знову перемкнуться, сотні пішоходів уже ... перехрестя.'::text,'перейдуть'::text,'перейдуть'::text,'перейшли'::text,'Поки світлофори знову перемкнуться, сотні пішоходів уже перейдуть перехрестя.'::text),
(373596,41511,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando los semáforos cambien otra vez, cientos de peatones ... el cruce.'::text,'habrán cruzado'::text,'cruzarán'::text,'cruzaron'::text,'Para cuando los semáforos cambien otra vez, cientos de peatones habrán cruzado el cruce.'::text),
(373595,41511,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici à ce que les feux changent à nouveau, des centaines de piétons ... le carrefour.'::text,'auront traversé'::text,'traverseront'::text,'ont traversé'::text,'D''ici à ce que les feux changent à nouveau, des centaines de piétons auront traversé le carrefour.'::text),
(373598,41511,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Işıklar tekrar değişene kadar yüzlerce yaya kavşaktan ...'::text,'geçmiş olacak'::text,'geçecek'::text,'geçti'::text,'Işıklar tekrar değişene kadar yüzlerce yaya kavşaktan geçmiş olacak.'::text),
(373599,41511,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a lámpák újra váltanak, több száz gyalogos már ... a kereszteződésen.'::text,'átkelt'::text,'át fog kelni'::text,'átkelt'::text,'Mire a lámpák újra váltanak, több száz gyalogos már átkelt a kereszteződésen.'::text),
(355530,39504,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie hat geschworen, dass sie sich die Füße ..., bevor sie in die Trauben gesprungen sind.'::text,'gewaschen hatten'::text,'gewaschen haben'::text,'waschen'::text,'Bestie, sie hat geschworen, dass sie sich die Füße gewaschen hatten, bevor sie in die Trauben gesprungen sind.'::text),
(355534,39504,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона клялася, що вони ... ноги, перш ніж стрибнути у виноград.'::text,'помили'::text,'помили'::text,'миють'::text,'Подруго, вона клялася, що вони помили ноги, перш ніж стрибнути у виноград.'::text),
(355533,39504,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, juró que ... los pies antes de meterse de un salto en las uvas.'::text,'se habían lavado'::text,'se han lavado'::text,'se lavan'::text,'Amiga, juró que se habían lavado los pies antes de meterse de un salto en las uvas.'::text),
(355532,39504,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle a juré qu''ils ... les pieds avant de sauter dans le raisin.'::text,'s''étaient lavé'::text,'se sont lavé'::text,'se lavent'::text,'Ma belle, elle a juré qu''ils s''étaient lavé les pieds avant de sauter dans le raisin.'::text),
(355535,39504,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, üzümlerin içine atlamadan önce ayaklarını ... diye yemin etti.'::text,'yıkamışlardı'::text,'yıkadılar'::text,'yıkıyorlar'::text,'Kanka, üzümlerin içine atlamadan önce ayaklarını yıkamışlardı diye yemin etti.'::text),
(355536,39504,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, megesküdött, hogy ... a lábukat, mielőtt beugrottak a szőlőbe.'::text,'megmosták'::text,'megmosták'::text,'megmossák'::text,'Csajszi, megesküdött, hogy megmosták a lábukat, mielőtt beugrottak a szőlőbe.'::text),
(355539,39505,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er noch fester stampft, ... seine Füße eine Woche lang lila. Genau das, was wir gebraucht haben.'::text,'bleiben'::text,'blieben'::text,'blieben'::text,'Wenn er noch fester stampft, bleiben seine Füße eine Woche lang lila. Genau das, was wir gebraucht haben.'::text),
(355543,39505,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він тупатиме ще сильніше, його ноги ... фіолетовими цілий тиждень. Саме те, що нам було треба.'::text,'залишаться'::text,'залишилися б'::text,'залишилися'::text,'Якщо він тупатиме ще сильніше, його ноги залишаться фіолетовими цілий тиждень. Саме те, що нам було треба.'::text),
(355542,39505,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si pisa todavía más fuerte, sus pies ... morados una semana. Justo lo que necesitábamos.'::text,'se quedarán'::text,'se quedarían'::text,'se quedaron'::text,'Si pisa todavía más fuerte, sus pies se quedarán morados una semana. Justo lo que necesitábamos.'::text),
(355541,39505,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il piétine encore plus fort, ses pieds ... violets pendant une semaine. Exactement ce qu''il nous fallait.'::text,'resteront'::text,'resteraient'::text,'sont restés'::text,'S''il piétine encore plus fort, ses pieds resteront violets pendant une semaine. Exactement ce qu''il nous fallait.'::text),
(355544,39505,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biraz daha sert tepinirse ayakları bir hafta boyunca mor ... – tam da ihtiyacımız olan şey.'::text,'kalacak'::text,'kalırdı'::text,'kaldı'::text,'Biraz daha sert tepinirse ayakları bir hafta boyunca mor kalacak – tam da ihtiyacımız olan şey.'::text),
(355545,39505,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még erősebben tapos, a lába egy hétig lila ... – pontosan erre volt szükségünk.'::text,'marad'::text,'maradna'::text,'maradt'::text,'Ha még erősebben tapos, a lába egy hétig lila marad – pontosan erre volt szükségünk.'::text),
(355548,39506,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie Stiefel trügen, ... sich ihre Füße nicht lila. Aber barfuß, natürlich die klügste Wahl.'::text,'färbten'::text,'färben'::text,'färbten'::text,'Wenn sie Stiefel trügen, färbten sich ihre Füße nicht lila. Aber barfuß, natürlich die klügste Wahl.'::text),
(355552,39506,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вони були в чоботях, їхні ноги ... фіолетовими. Але босоніж — очевидно, найрозумніший вибір.'::text,'не стали б'::text,'не стануть'::text,'не стали'::text,'Якби вони були в чоботях, їхні ноги не стали б фіолетовими. Але босоніж — очевидно, найрозумніший вибір.'::text),
(355551,39506,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si llevaran botas, sus pies ... morados. Pero descalzos, obviamente la opción más inteligente.'::text,'no se pondrían'::text,'no se pondrán'::text,'no se pusieron'::text,'Si llevaran botas, sus pies no se pondrían morados. Pero descalzos, obviamente la opción más inteligente.'::text),
(355550,39506,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils portaient des bottes, leurs pieds ... violets. Mais pieds nus, évidemment le choix le plus malin.'::text,'ne deviendraient pas'::text,'ne deviendront pas'::text,'ne sont pas devenus'::text,'S''ils portaient des bottes, leurs pieds ne deviendraient pas violets. Mais pieds nus, évidemment le choix le plus malin.'::text),
(355553,39506,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çizme giyselerdi ayakları mora ... – ama çıplak ayak, tabii ki en akıllıca seçim.'::text,'dönmezdi'::text,'dönmeyecek'::text,'dönmedi'::text,'Çizme giyselerdi ayakları mora dönmezdi – ama çıplak ayak, tabii ki en akıllıca seçim.'::text),
(355554,39506,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha csizmát hordanának, a lábuk ... lilává. De mezítláb, persze, ez a legokosabb választás.'::text,'nem válna'::text,'nem válik'::text,'nem vált'::text,'Ha csizmát hordanának, a lábuk nem válna lilává. De mezítláb, persze, ez a legokosabb választás.'::text),
(355557,39507,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Trauben werden in einem großen Holzbottich mit bloßen Füßen ...'::text,'gestampft'::text,'stampfen'::text,'stampfend'::text,'Die Trauben werden in einem großen Holzbottich mit bloßen Füßen gestampft.'::text),
(355561,39507,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Виноград ... босими ногами у великому дерев’яному чані.'::text,'чавиться'::text,'чавить'::text,'чавлячи'::text,'Виноград чавиться босими ногами у великому дерев’яному чані.'::text),
(355560,39507,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las uvas ... con los pies descalzos en una gran tina de madera.'::text,'son pisadas'::text,'pisan'::text,'pisando'::text,'Las uvas son pisadas con los pies descalzos en una gran tina de madera.'::text),
(355559,39507,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le raisin ... pieds nus dans une grande cuve en bois.'::text,'est foulé'::text,'foule'::text,'foulant'::text,'Le raisin est foulé pieds nus dans une grande cuve en bois.'::text),
(355562,39507,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üzümler büyük bir ahşap fıçıda çıplak ayaklarla ...'::text,'eziliyor'::text,'eziyor'::text,'ezerek'::text,'Üzümler büyük bir ahşap fıçıda çıplak ayaklarla eziliyor.'::text),
(355563,39507,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szőlőt mezítláb ... egy nagy fakádban.'::text,'taposják'::text,'tapossa'::text,'taposva'::text,'A szőlőt mezítláb taposják egy nagy fakádban.'::text),
(355566,39508,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre bloßen Füße ... die Trauben in lila Saft.'::text,'verwandelten'::text,'wurden verwandelt'::text,'verwandelnd'::text,'Ihre bloßen Füße verwandelten die Trauben in lila Saft.'::text),
(355570,39508,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їхні босі ноги ... виноград на фіолетовий сік.'::text,'перетворили'::text,'були перетворені'::text,'перетворюючи'::text,'Їхні босі ноги перетворили виноград на фіолетовий сік.'::text),
(355569,39508,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sus pies descalzos ... las uvas en zumo morado.'::text,'convirtieron'::text,'fueron convertidos'::text,'convirtiendo'::text,'Sus pies descalzos convirtieron las uvas en zumo morado.'::text),
(355568,39508,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Leurs pieds nus ... le raisin en jus violet.'::text,'ont transformé'::text,'ont été transformés'::text,'transformant'::text,'Leurs pieds nus ont transformé le raisin en jus violet.'::text),
(355571,39508,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çıplak ayakları üzümleri mor bir suya ...'::text,'dönüştürdü'::text,'dönüştürüldü'::text,'dönüştürerek'::text,'Çıplak ayakları üzümleri mor bir suya dönüştürdü.'::text),
(355572,39508,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csupasz lábuk ... a szőlőt lila lévé.'::text,'változtatta'::text,'változtatva lett'::text,'változtatva'::text,'A csupasz lábuk változtatta a szőlőt lila lévé.'::text),
(355575,39509,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Füße ... ihnen helfen, das 200-Liter-Ziel bis Sonnenuntergang zu erreichen, auch wenn sich niemand sicher ist.'::text,'könnten'::text,'müssen'::text,'können nicht'::text,'Ihre Füße könnten ihnen helfen, das 200-Liter-Ziel bis Sonnenuntergang zu erreichen, auch wenn sich niemand sicher ist.'::text),
(355579,39509,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їхні ноги ... допомогти їм досягти цілі у 200 літрів до заходу сонця, хоча ніхто не впевнений.'::text,'могли б'::text,'мусять'::text,'не можуть'::text,'Їхні ноги могли б допомогти їм досягти цілі у 200 літрів до заходу сонця, хоча ніхто не впевнений.'::text),
(355578,39509,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sus pies ... ayudarles a alcanzar el objetivo de 200 litros antes del atardecer, aunque nadie está seguro.'::text,'podrían'::text,'deben'::text,'no pueden'::text,'Sus pies podrían ayudarles a alcanzar el objetivo de 200 litros antes del atardecer, aunque nadie está seguro.'::text),
(355577,39509,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Leurs pieds ... les aider à atteindre l''objectif de 200 litres avant le coucher du soleil, même si personne n''en est sûr.'::text,'pourraient'::text,'doivent'::text,'ne peuvent pas'::text,'Leurs pieds pourraient les aider à atteindre l''objectif de 200 litres avant le coucher du soleil, même si personne n''en est sûr.'::text),
(355580,39509,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayakları gün batımına kadar 200 litrelik hedefe ulaşmalarına yardım ..., ama kimse emin değil.'::text,'edebilir'::text,'etmeli'::text,'edemez'::text,'Ayakları gün batımına kadar 200 litrelik hedefe ulaşmalarına yardım edebilir, ama kimse emin değil.'::text),
(355581,39509,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lábuk ... nekik elérni a 200 literes célt napnyugtáig, bár senki sem biztos benne.'::text,'segíthet'::text,'segítenie kell'::text,'nem segíthet'::text,'A lábuk segíthet nekik elérni a 200 literes célt napnyugtáig, bár senki sem biztos benne.'::text),
(355584,39510,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann, ... Füße lila sind, lacht im Bottich.'::text,'dessen'::text,'der'::text,'welcher'::text,'Der Mann, dessen Füße lila sind, lacht im Bottich.'::text),
(355588,39510,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік, ... ноги фіолетові, сміється в чані.'::text,'у якого'::text,'який'::text,'що'::text,'Чоловік, у якого ноги фіолетові, сміється в чані.'::text),
(355587,39510,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... pies están morados se ríe en la tina.'::text,'cuyos'::text,'quien'::text,'que'::text,'El hombre cuyos pies están morados se ríe en la tina.'::text),
(355586,39510,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... les pieds sont violets rit dans la cuve.'::text,'dont'::text,'qui'::text,'lequel'::text,'L''homme dont les pieds sont violets rit dans la cuve.'::text),
(355589,39510,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ayakları mor olan adam fıçıda gülüyor.'::text,''::text,NULL::text,NULL::text,'Ayakları mor olan adam fıçıda gülüyor.'::text),
(355590,39510,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a férfi, ... lába lila, nevet a kádban.'::text,'akinek a'::text,'aki'::text,'ami'::text,'Az a férfi, akinek a lába lila, nevet a kádban.'::text),
(355593,39511,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann sagte, er ... am nächsten Tag wieder die Füße in den Bottich stecken.'::text,'würde'::text,'werde'::text,'steckt'::text,'Der Mann sagte, er würde am nächsten Tag wieder die Füße in den Bottich stecken.'::text),
(355597,39511,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік сказав, що наступного дня знову ... ноги в чан.'::text,'опустить'::text,'опустить'::text,'опускає'::text,'Чоловік сказав, що наступного дня знову опустить ноги в чан.'::text),
(355596,39511,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre dijo que al día siguiente ... los pies en la tina otra vez.'::text,'metería'::text,'meterá'::text,'mete'::text,'El hombre dijo que al día siguiente metería los pies en la tina otra vez.'::text),
(355595,39511,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme a dit qu''il ... de nouveau les pieds dans la cuve le lendemain.'::text,'mettrait'::text,'mettra'::text,'met'::text,'L''homme a dit qu''il mettrait de nouveau les pieds dans la cuve le lendemain.'::text),
(355598,39511,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam ertesi gün ayaklarını yine fıçıya ... söyledi.'::text,'koyacağını'::text,'koyacağını'::text,'koyduğunu'::text,'Adam ertesi gün ayaklarını yine fıçıya koyacağını söyledi.'::text),
(355599,39511,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi azt mondta, hogy másnap újra ... a lábát a kádba.'::text,'be fogja tenni'::text,'be fogja tenni'::text,'beteszi'::text,'A férfi azt mondta, hogy másnap újra be fogja tenni a lábát a kádba.'::text),
(355611,39513,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, er hat mir erzählt, dass er es genießt, seine nackten Füße in kalte Trauben zu ...'::text,'versenken'::text,'versenken'::text,'versenken'::text,'Girl, er hat mir erzählt, dass er es genießt, seine nackten Füße in kalte Trauben zu versenken.'::text),
(355615,39513,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що кайфує ... босі ноги в холодний виноград.'::text,'занурювати'::text,'занурювати'::text,'занурювати'::text,'Подруго, він сказав мені, що кайфує занурювати босі ноги в холодний виноград.'::text),
(355614,39513,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que le encanta ... los pies descalzos en uvas frías.'::text,'hundir'::text,'hundir'::text,'hundir'::text,'Tía, me dijo que le encanta hundir los pies descalzos en uvas frías.'::text),
(355613,39513,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit qu''il adore ... ses pieds nus dans du raisin froid.'::text,'plonger'::text,'plonger'::text,'plonger'::text,'Meuf, il m''a dit qu''il adore plonger ses pieds nus dans du raisin froid.'::text),
(355616,39513,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana çıplak ayaklarını soğuk üzümlere ... bayıldığını söyledi.'::text,'batırmaya'::text,'batırmaya'::text,'batırmaya'::text,'Kızım, bana çıplak ayaklarını soğuk üzümlere batırmaya bayıldığını söyledi.'::text),
(355617,39513,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy imádja ... a csupasz lábát a hideg szőlőbe.'::text,'belemeríteni'::text,'belemeríteni'::text,'belemeríteni'::text,'Csajszi, azt mondta, hogy imádja belemeríteni a csupasz lábát a hideg szőlőbe.'::text),
(345090,38344,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, der Typ, ... auf dem Sofa heult, ertrinkt lowkey in Taschentüchern.'::text,'der'::text,'das'::text,'dessen'::text,'Alter, der Typ, der auf dem Sofa heult, ertrinkt lowkey in Taschentüchern.'::text),
(345094,38344,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, хлопець, ... плаче на тому дивані, реально тоне в серветках.'::text,'який'::text,'що'::text,'чий'::text,'Чувак, хлопець, який плаче на тому дивані, реально тоне в серветках.'::text),
(345093,38344,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, el chaval ... está llorando en ese sofá está literalmente ahogándose en pañuelos.'::text,'que'::text,'el cual'::text,'cuyo'::text,'Tío, el chaval que está llorando en ese sofá está literalmente ahogándose en pañuelos.'::text),
(345092,38344,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, le gars ... pleure sur ce canapé se noie carrément dans les mouchoirs.'::text,'qui'::text,'lequel'::text,'dont'::text,'Mec, le gars qui pleure sur ce canapé se noie carrément dans les mouchoirs.'::text),
(345095,38344,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o kanepede ... ağlayan çocuk resmen mendillerde boğuluyor.'::text,''::text,NULL::text,NULL::text,'Kanka, o kanepede ağlayan çocuk resmen mendillerde boğuluyor.'::text),
(345096,38344,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, az a srác, ... azon a kanapén sír, konkrétan fuldoklik a zsebkendőkben.'::text,'aki'::text,'ami'::text,'akinek a'::text,'Haver, az a srác, aki azon a kanapén sír, konkrétan fuldoklik a zsebkendőkben.'::text),
(345099,38345,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte seinem Manager, dass er wegen des Berichts 2 Stunden lang ...'::text,'geweint hatte'::text,'geweint hat'::text,'weint'::text,'Er sagte seinem Manager, dass er wegen des Berichts 2 Stunden lang geweint hatte.'::text),
(345103,38345,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав менеджерові, що ... 2 години через звіт.'::text,'плакав'::text,'плаче'::text,'плаче'::text,'Він сказав менеджерові, що плакав 2 години через звіт.'::text),
(345102,38345,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le dijo a su mánager que ... durante 2 horas por el informe.'::text,'había estado llorando'::text,'ha estado llorando'::text,'está llorando'::text,'Le dijo a su mánager que había estado llorando durante 2 horas por el informe.'::text),
(345101,38345,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit à son manager qu''il ... pendant 2 heures à cause du rapport.'::text,'avait pleuré'::text,'a pleuré'::text,'pleure'::text,'Il a dit à son manager qu''il avait pleuré pendant 2 heures à cause du rapport.'::text),
(345104,38345,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Müdürüne rapor yüzünden 2 saat boyunca ... söyledi.'::text,'ağlamış olduğunu'::text,'ağladığını'::text,'ağlamakta olduğunu'::text,'Müdürüne rapor yüzünden 2 saat boyunca ağlamış olduğunu söyledi.'::text),
(345105,38345,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta a menedzserének, hogy 2 órán át ... a jelentés miatt.'::text,'sírt'::text,'sírt'::text,'sír'::text,'Azt mondta a menedzserének, hogy 2 órán át sírt a jelentés miatt.'::text),
(345108,38346,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als er ein Kind war, ... er bei jedem traurigen Film.'::text,'weinte'::text,'weinte'::text,'war gewohnt zu weinen'::text,'Als er ein Kind war, weinte er bei jedem traurigen Film.'::text),
(345112,38346,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли він був дитиною, він ... на кожному сумному фільмі.'::text,'плакав'::text,'плакав'::text,'звик плакати'::text,'Коли він був дитиною, він плакав на кожному сумному фільмі.'::text),
(345111,38346,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando era niño, ... en cada película triste.'::text,'lloraba'::text,'solía llorar'::text,'estaba acostumbrado a llorar'::text,'Cuando era niño, lloraba en cada película triste.'::text),
(345110,38346,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand il était enfant, il ... à chaque film triste.'::text,'pleurait'::text,'avait l''habitude de pleurer'::text,'était habitué à pleurer'::text,'Quand il était enfant, il pleurait à chaque film triste.'::text),
(345113,38346,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocukken her hüzünlü filmde ...'::text,'ağlardı'::text,'ağlardı'::text,'ağlamaya alışkındı'::text,'Çocukken her hüzünlü filmde ağlardı.'::text),
(345114,38346,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gyerekkorában minden szomorú filmen ...'::text,'sírt'::text,'szokott sírni'::text,'hozzá volt szokva a síráshoz'::text,'Gyerekkorában minden szomorú filmen sírt.'::text),
(345117,38347,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er kann nicht aufhören zu weinen und ... ständig Taschentücher aus der Box.'::text,'zieht'::text,'zu ziehen'::text,'zog'::text,'Er kann nicht aufhören zu weinen und zieht ständig Taschentücher aus der Box.'::text),
(345121,38347,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він не може перестати плакати і постійно ... серветки з коробки.'::text,'витягує'::text,'витягувати'::text,'витягнув'::text,'Він не може перестати плакати і постійно витягує серветки з коробки.'::text),
(345120,38347,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No puede dejar de llorar y sigue ... pañuelos de la caja.'::text,'sacando'::text,'sacar'::text,'sacó'::text,'No puede dejar de llorar y sigue sacando pañuelos de la caja.'::text),
(345119,38347,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il n''arrive pas à arrêter de pleurer et il continue de ... des mouchoirs de la boîte.'::text,'tirer'::text,'tirer'::text,'a tiré'::text,'Il n''arrive pas à arrêter de pleurer et il continue de tirer des mouchoirs de la boîte.'::text),
(345122,38347,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ağlamayı bırakamıyor ve kutudan durmadan mendil ...'::text,'çekiyor'::text,'çekmek'::text,'çekti'::text,'Ağlamayı bırakamıyor ve kutudan durmadan mendil çekiyor.'::text),
(345123,38347,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem tudja abbahagyni a sírást, és folyamatosan ... a zsebkendőket a dobozból.'::text,'húzza ki'::text,'kihúzni'::text,'kihúzta'::text,'Nem tudja abbahagyni a sírást, és folyamatosan húzza ki a zsebkendőket a dobozból.'::text),
(345126,38348,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er weint schon den ganzen Abend, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Er weint schon den ganzen Abend, oder?'::text),
(345130,38348,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він плаче весь вечір, ...?'::text,'чи не так'::text,'чи не так'::text,'чи не так'::text,'Він плаче весь вечір, чи не так?'::text),
(345129,38348,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lleva llorando toda la noche, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Lleva llorando toda la noche, ¿verdad?'::text),
(345128,38348,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il pleure depuis le début de la soirée, ... ?'::text,'pas vrai'::text,'pas vrai'::text,'pas vrai'::text,'Il pleure depuis le début de la soirée, pas vrai ?'::text),
(345131,38348,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün akşam ağlıyor, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Bütün akşam ağlıyor, değil mi?'::text),
(345132,38348,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egész este sír, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Egész este sír, ugye?'::text),
(345135,38349,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er kann nicht aufhören zu weinen – ... sein Freund am Telefon. Eindeutig ein entspannter Abend.'::text,'genauso wenig'::text,'genauso'::text,'genauso wenig'::text,'Er kann nicht aufhören zu weinen – genauso wenig sein Freund am Telefon. Eindeutig ein entspannter Abend.'::text),
(345139,38349,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він не може перестати плакати, і ... його друг на телефоні. Явно дуже спокійний вечір.'::text,'так само не може'::text,'так само може'::text,'так само не може'::text,'Він не може перестати плакати, і так само не може його друг на телефоні. Явно дуже спокійний вечір.'::text),
(345138,38349,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No puede dejar de llorar, y ... su amigo al teléfono. Está claro: una noche de lo más relajante.'::text,'tampoco puede'::text,'también puede'::text,'tampoco'::text,'No puede dejar de llorar, y tampoco puede su amigo al teléfono. Está claro: una noche de lo más relajante.'::text),
(345137,38349,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il n''arrive pas à arrêter de pleurer, et c''est ... pour son pote au téléphone. Clairement une soirée détente.'::text,'pareil'::text,'pareil'::text,'pareil'::text,'Il n''arrive pas à arrêter de pleurer, et c''est pareil pour son pote au téléphone. Clairement une soirée détente.'::text),
(345140,38349,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ağlamayı bırakamıyor, telefondaki arkadaşı da ... – belli ki çok rahatlatıcı bir akşam.'::text,'bırakamıyor'::text,'bırakabiliyor'::text,'bırakamıyor'::text,'Ağlamayı bırakamıyor, telefondaki arkadaşı da bırakamıyor – belli ki çok rahatlatıcı bir akşam.'::text),
(345141,38349,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem tudja abbahagyni a sírást, és ... a barátja a telefonban. Egyértelműen pihentető este.'::text,'ugyanígy nem tudja'::text,'ugyanígy tudja'::text,'ugyanígy nem'::text,'Nem tudja abbahagyni a sírást, és ugyanígy nem tudja a barátja a telefonban. Egyértelműen pihentető este.'::text),
(345144,38350,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... stundenlang geweint, bevor die Taschentuchbox endlich leer war. Eine Tragödie!'::text,'hatte'::text,'hat'::text,'weint'::text,'Er hatte stundenlang geweint, bevor die Taschentuchbox endlich leer war. Eine Tragödie!'::text),
(345148,38350,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... годинами, поки коробка з серветками нарешті не спорожніла. Трагедія!'::text,'плакав'::text,'плаче'::text,'плаче'::text,'Він плакав годинами, поки коробка з серветками нарешті не спорожніла. Трагедія!'::text),
(345147,38350,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... llorando durante horas antes de que la caja de pañuelos por fin quedara vacía. ¡Una tragedia!'::text,'Había estado'::text,'Ha estado'::text,'Está'::text,'Había estado llorando durante horas antes de que la caja de pañuelos por fin quedara vacía. ¡Una tragedia!'::text),
(345146,38350,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... pendant des heures avant que la boîte de mouchoirs soit enfin vide. Une tragédie !'::text,'avait pleuré'::text,'a pleuré'::text,'pleure'::text,'Il avait pleuré pendant des heures avant que la boîte de mouchoirs soit enfin vide. Une tragédie !'::text),
(345149,38350,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mendil kutusu sonunda boşalana kadar saatlerce ... – tam bir trajedi!'::text,'ağlamıştı'::text,'ağladı'::text,'ağlıyor'::text,'Mendil kutusu sonunda boşalana kadar saatlerce ağlamıştı – tam bir trajedi!'::text),
(345150,38350,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Órákon át ..., mire a zsebkendős doboz végre kiürült. Tragédia!'::text,'sírt'::text,'sírt'::text,'sír'::text,'Órákon át sírt, mire a zsebkendős doboz végre kiürült. Tragédia!'::text),
(345162,38352,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, anscheinend wird er um zehn Uhr schon drei Stunden am Stück ...'::text,'geweint haben'::text,'weinen'::text,'geweint haben'::text,'Bestie, anscheinend wird er um zehn Uhr schon drei Stunden am Stück geweint haben.'::text),
(345166,38352,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, до десятої він ... вже три години поспіль.'::text,'плакатиме'::text,'плакатиме'::text,'виплачеться'::text,'Подруго, кажуть, до десятої він плакатиме вже три години поспіль.'::text),
(345165,38352,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer a las diez ... tres horas seguidas.'::text,'llevará llorando'::text,'estará llorando'::text,'habrá llorado'::text,'Amiga, al parecer a las diez llevará llorando tres horas seguidas.'::text),
(345164,38352,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment, à dix heures, il ... trois heures d''affilée.'::text,'aura pleuré'::text,'pleurera'::text,'aura pleuré'::text,'Ma belle, apparemment, à dix heures, il aura pleuré trois heures d''affilée.'::text),
(345167,38352,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre saat ona kadar üç saattir aralıksız ...'::text,'ağlıyor olacak'::text,'ağlıyor olacak'::text,'ağlamış olacak'::text,'Kanka, duyduğuma göre saat ona kadar üç saattir aralıksız ağlıyor olacak.'::text),
(345168,38352,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag tízkor már három órája ... egyfolytában.'::text,'sír'::text,'sírni fog'::text,'ki fogja sírni magát'::text,'Csajszi, állítólag tízkor már három órája sír egyfolytában.'::text),
(345171,38353,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er diesen traurigen Film nicht geschaut hätte, ... er nicht den ganzen Abend geweint.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn er diesen traurigen Film nicht geschaut hätte, hätte er nicht den ganzen Abend geweint.'::text),
(345175,38353,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він не дивився той сумний фільм, він ... весь вечір.'::text,'не плакав би'::text,'не плакатиме'::text,'не плакав'::text,'Якби він не дивився той сумний фільм, він не плакав би весь вечір.'::text),
(345174,38353,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera visto esa película triste, no ... toda la noche.'::text,'habría llorado'::text,'llorará'::text,'lloró'::text,'Si no hubiera visto esa película triste, no habría llorado toda la noche.'::text),
(345173,38353,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il n''avait pas regardé ce film triste, il ... de toute la soirée.'::text,'n''aurait pas pleuré'::text,'ne pleurera pas'::text,'n''a pas pleuré'::text,'S''il n''avait pas regardé ce film triste, il n''aurait pas pleuré de toute la soirée.'::text),
(345176,38353,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O hüzünlü filmi izlemeseydi bütün akşam ...'::text,'ağlamazdı'::text,'ağlamayacak'::text,'ağlamadı'::text,'O hüzünlü filmi izlemeseydi bütün akşam ağlamazdı.'::text),
(345177,38353,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem nézte volna meg azt a szomorú filmet, egész este ...'::text,'nem sírt volna'::text,'nem fog sírni'::text,'nem sírt'::text,'Ha nem nézte volna meg azt a szomorú filmet, egész este nem sírt volna.'::text),
(361434,40160,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... gerade ihren Kaffee, als ein riesiger Becher auf der Theke auftauchte.'::text,'trank'::text,'trank'::text,'hat getrunken'::text,'Sie trank gerade ihren Kaffee, als ein riesiger Becher auf der Theke auftauchte.'::text),
(361438,40160,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... каву, коли на прилавку з’явився величезний кухоль.'::text,'пила'::text,'випила'::text,'випила'::text,'Вона пила каву, коли на прилавку з’явився величезний кухоль.'::text),
(361437,40160,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... su café cuando apareció una taza enorme en la barra.'::text,'Estaba tomando'::text,'Tomó'::text,'Ha tomado'::text,'Estaba tomando su café cuando apareció una taza enorme en la barra.'::text),
(361436,40160,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... son café quand un mug énorme est apparu sur le comptoir.'::text,'buvait'::text,'a bu'::text,'a bu'::text,'Elle buvait son café quand un mug énorme est apparu sur le comptoir.'::text),
(361439,40160,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tezgâhta devasa bir kupa belirdiğinde kahvesini ...'::text,'içiyordu'::text,'içti'::text,'içti'::text,'Tezgâhta devasa bir kupa belirdiğinde kahvesini içiyordu.'::text),
(361440,40160,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éppen a kávéját ..., amikor egy óriási bögre jelent meg a pulton.'::text,'itta'::text,'megitta'::text,'megitta'::text,'Éppen a kávéját itta, amikor egy óriási bögre jelent meg a pulton.'::text),
(361443,40161,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Barista ... seit fünf Minuten immer größere Becher, und dieser hier ist riesig.'::text,'bringt'::text,'bringt gerade'::text,'bringt'::text,'Der Barista bringt seit fünf Minuten immer größere Becher, und dieser hier ist riesig.'::text),
(361447,40161,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бариста вже п’ять хвилин ... дедалі більші кухлі, і цей — величезний.'::text,'приносить'::text,'приносить'::text,'приносить'::text,'Бариста вже п’ять хвилин приносить дедалі більші кухлі, і цей — величезний.'::text),
(361446,40161,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El barista lleva cinco minutos ... tazas cada vez más grandes, y esta es enorme.'::text,'trayendo'::text,'está trayendo'::text,'trae'::text,'El barista lleva cinco minutos trayendo tazas cada vez más grandes, y esta es enorme.'::text),
(361445,40161,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le barista ... des mugs de plus en plus grands depuis cinq minutes, et celui-ci est énorme.'::text,'apporte'::text,'est en train d''apporter'::text,'apporte'::text,'Le barista apporte des mugs de plus en plus grands depuis cinq minutes, et celui-ci est énorme.'::text),
(361448,40161,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Barista beş dakikadır giderek büyüyen kupalar ..., bu da devasa.'::text,'getiriyor'::text,'getiriyor'::text,'getirir'::text,'Barista beş dakikadır giderek büyüyen kupalar getiriyor, bu da devasa.'::text),
(361449,40161,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barista öt perce ... egyre nagyobb bögréket, és ez óriási.'::text,'hoz'::text,'éppen hoz'::text,'hoz'::text,'A barista öt perce hoz egyre nagyobb bögréket, és ez óriási.'::text),
(361452,40162,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der riesige Becher auftauchte, ... sie ihn mit beiden Händen.'::text,'packte'::text,'packte gerade'::text,'hat gepackt'::text,'Als der riesige Becher auftauchte, packte sie ihn mit beiden Händen.'::text),
(361456,40162,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли з’явився величезний кухоль, вона ... його обома руками.'::text,'схопила'::text,'хапала'::text,'схопила'::text,'Коли з’явився величезний кухоль, вона схопила його обома руками.'::text),
(361455,40162,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando apareció la taza enorme, la ... con las dos manos.'::text,'agarró'::text,'estaba agarrando'::text,'ha agarrado'::text,'Cuando apareció la taza enorme, la agarró con las dos manos.'::text),
(361454,40162,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le mug énorme est apparu, elle l''... à deux mains.'::text,'a attrapé'::text,'attrapait'::text,'a attrapé'::text,'Quand le mug énorme est apparu, elle l''a attrapé à deux mains.'::text),
(361457,40162,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devasa kupa belirdiğinde onu iki eliyle ...'::text,'kavradı'::text,'kavrıyordu'::text,'kavradı'::text,'Devasa kupa belirdiğinde onu iki eliyle kavradı.'::text),
(361458,40162,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor megjelent az óriási bögre, két kézzel ...'::text,'megragadta'::text,'ragadta meg éppen'::text,'megragadta'::text,'Amikor megjelent az óriási bögre, két kézzel megragadta.'::text),
(361461,40163,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, der Barista hat mir erzählt, dass sie heute schon drei riesige Kaffees ...'::text,'getrunken hat'::text,'getrunken hat'::text,'trank'::text,'Bestie, der Barista hat mir erzählt, dass sie heute schon drei riesige Kaffees getrunken hat.'::text),
(361465,40163,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, бариста сказав мені, що вона сьогодні вже ... три величезних кави.'::text,'випила'::text,'пила'::text,'випила'::text,'Подруго, бариста сказав мені, що вона сьогодні вже випила три величезних кави.'::text),
(361464,40163,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, el barista me dijo que hoy ya ... tres cafés enormes.'::text,'se ha tomado'::text,'ha estado tomando'::text,'se tomó'::text,'Amiga, el barista me dijo que hoy ya se ha tomado tres cafés enormes.'::text),
(361463,40163,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, le barista m''a dit qu''elle ... trois cafés énormes rien qu''aujourd''hui.'::text,'a bu'::text,'boit'::text,'a bu'::text,'Ma belle, le barista m''a dit qu''elle a bu trois cafés énormes rien qu''aujourd''hui.'::text),
(361466,40163,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, barista bana bugün şimdiden üç devasa kahve ... söyledi.'::text,'içtiğini'::text,'içmekte olduğunu'::text,'içtiğini'::text,'Kanka, barista bana bugün şimdiden üç devasa kahve içtiğini söyledi.'::text),
(361467,40163,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, a barista mesélte, hogy ma már három óriási kávét ...'::text,'megivott'::text,'ivott'::text,'megivott'::text,'Csajszi, a barista mesélte, hogy ma már három óriási kávét megivott.'::text),
(361470,40164,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, ich hab gehört, dass sie schon bezahlt ..., bevor der riesige Becher kam.'::text,'hatte'::text,'hat'::text,'war'::text,'Rate mal, ich hab gehört, dass sie schon bezahlt hatte, bevor der riesige Becher kam.'::text),
(361474,40164,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, я чула, що вона ... заплатила ще до того, як принесли величезний кухоль.'::text,''::text,NULL::text,NULL::text,'Уяви, я чула, що вона заплатила ще до того, як принесли величезний кухоль.'::text),
(361473,40164,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, me dijeron que ya ... pagado antes de que llegara la taza enorme.'::text,'había'::text,'ha'::text,'estaba'::text,'Adivina qué, me dijeron que ya había pagado antes de que llegara la taza enorme.'::text),
(361472,40164,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, il paraît qu''elle ... déjà payé avant que le mug énorme arrive.'::text,'avait'::text,'a'::text,'était'::text,'Devine quoi, il paraît qu''elle avait déjà payé avant que le mug énorme arrive.'::text),
(361475,40164,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, duydum ki devasa kupa gelmeden önce ... çoktan ödemişti.'::text,''::text,NULL::text,NULL::text,'Bil bakalım, duydum ki devasa kupa gelmeden önce çoktan ödemişti.'::text),
(361476,40164,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt hallottam, hogy ... már kifizette, mielőtt megérkezett az óriási bögre.'::text,''::text,NULL::text,NULL::text,'Képzeld, azt hallottam, hogy már kifizette, mielőtt megérkezett az óriási bögre.'::text),
(361479,40165,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie wird den ganzen Tag an diesem riesigen Becher ..., ohne Witz.'::text,'trinken'::text,'trinken'::text,'trinkt'::text,'Bro, sie wird den ganzen Tag an diesem riesigen Becher trinken, ohne Witz.'::text),
(361483,40165,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... з цього величезного кухля цілий день, чесне слово.'::text,'питиме'::text,'вип’є'::text,'п’є'::text,'Бро, вона питиме з цього величезного кухля цілий день, чесне слово.'::text),
(361482,40165,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... de esa taza enorme todo el día, en serio.'::text,'estará bebiendo'::text,'beberá'::text,'bebe'::text,'Bro, estará bebiendo de esa taza enorme todo el día, en serio.'::text),
(361481,40165,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... dans ce mug énorme toute la journée, sans mentir.'::text,'sera en train de boire'::text,'boira'::text,'boit'::text,'Frérot, elle sera en train de boire dans ce mug énorme toute la journée, sans mentir.'::text),
(361484,40165,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bütün gün o devasa kupadan ..., yalan yok.'::text,'içiyor olacak'::text,'içecek'::text,'içiyor'::text,'Kanka, bütün gün o devasa kupadan içiyor olacak, yalan yok.'::text),
(361485,40165,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, egész nap abból az óriási bögréből ..., komolyan.'::text,'fog inni'::text,'meg fogja inni'::text,'iszik'::text,'Tesó, egész nap abból az óriási bögréből fog inni, komolyan.'::text),
(361488,40166,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Bro, ich wette, sie ... diesen riesigen Kaffee nicht auf einmal aus, echt jetzt.'::text,'trinkt'::text,'trinkt'::text,'trinkt gerade'::text,'Nee Bro, ich wette, sie trinkt diesen riesigen Kaffee nicht auf einmal aus, echt jetzt.'::text),
(361492,40166,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, закладаюся, що вона ... цю величезну каву за раз, реально.'::text,'не доп’є'::text,'не допиватиме'::text,'не допиває'::text,'Не, бро, закладаюся, що вона не доп’є цю величезну каву за раз, реально.'::text),
(361491,40166,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, bro, te apuesto a que ... ese café enorme de una vez, en serio.'::text,'no se terminará'::text,'no se estará terminando'::text,'no se está terminando'::text,'Qué va, bro, te apuesto a que no se terminará ese café enorme de una vez, en serio.'::text),
(361490,40166,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan frérot, je parie qu''elle ... ce café énorme d''un coup, sérieux.'::text,'ne finira pas'::text,'ne sera pas en train de finir'::text,'ne finit pas'::text,'Nan frérot, je parie qu''elle ne finira pas ce café énorme d''un coup, sérieux.'::text),
(361493,40166,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, bahse girerim o devasa kahveyi bir dikişte ..., cidden.'::text,'bitirmeyecek'::text,'bitiriyor olmayacak'::text,'bitirmiyor'::text,'Yok kanka, bahse girerim o devasa kahveyi bir dikişte bitirmeyecek, cidden.'::text),
(361494,40166,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, tesó, fogadok, hogy azt az óriási kávét ... egy húzásra, komolyan.'::text,'nem issza ki'::text,'nem fogja kiinni'::text,'nem issza ki'::text,'Á, tesó, fogadok, hogy azt az óriási kávét nem issza ki egy húzásra, komolyan.'::text),
(361497,40167,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Kunde den riesigen Becher ..., steigt der Preis laut Richtlinie um 300 Prozent.'::text,'bestellt'::text,'bestellte'::text,'bestellen wird'::text,'Wenn ein Kunde den riesigen Becher bestellt, steigt der Preis laut Richtlinie um 300 Prozent.'::text),
(361501,40167,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо клієнт ... величезний кухоль, ціна, згідно з правилами, зростає на 300 відсотків.'::text,'замовляє'::text,'замовив'::text,'замовить'::text,'Якщо клієнт замовляє величезний кухоль, ціна, згідно з правилами, зростає на 300 відсотків.'::text),
(361500,40167,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un cliente ... la taza enorme, el precio sube un 300 %, según la política.'::text,'pide'::text,'pidió'::text,'pedirá'::text,'Si un cliente pide la taza enorme, el precio sube un 300 %, según la política.'::text),
(361499,40167,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un client ... le mug énorme, le prix augmente de 300 %, conformément à la politique.'::text,'commande'::text,'a commandé'::text,'commandera'::text,'Si un client commande le mug énorme, le prix augmente de 300 %, conformément à la politique.'::text),
(361502,40167,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir müşteri devasa kupayı ..., politika gereği fiyat yüzde 300 artar.'::text,'sipariş ederse'::text,'sipariş ettiyse'::text,'sipariş edecekse'::text,'Bir müşteri devasa kupayı sipariş ederse, politika gereği fiyat yüzde 300 artar.'::text),
(361503,40167,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy vásárló ... az óriási bögrét, az ár a szabályzat szerint 300 százalékkal nő.'::text,'megrendeli'::text,'megrendelte'::text,'meg fogja rendelni'::text,'Ha egy vásárló megrendeli az óriási bögrét, az ár a szabályzat szerint 300 százalékkal nő.'::text),
(361506,40168,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Barista einen riesigen Becher bringt, ... sie mehr Kaffee zum Trinken, weil er riesig ist.'::text,'hat'::text,'hätte'::text,'hatte'::text,'Wenn der Barista einen riesigen Becher bringt, hat sie mehr Kaffee zum Trinken, weil er riesig ist.'::text),
(361510,40168,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо бариста принесе величезний кухоль, у неї ... більше кави, бо він величезний.'::text,'буде'::text,'було б'::text,'було'::text,'Якщо бариста принесе величезний кухоль, у неї буде більше кави, бо він величезний.'::text),
(361509,40168,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el barista trae una taza enorme, ... más café para beber, porque es enorme.'::text,'tendrá'::text,'tendría'::text,'tuvo'::text,'Si el barista trae una taza enorme, tendrá más café para beber, porque es enorme.'::text),
(361508,40168,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le barista apporte un mug énorme, elle ... plus de café à boire, parce qu''il est énorme.'::text,'aura'::text,'aurait'::text,'a eu'::text,'Si le barista apporte un mug énorme, elle aura plus de café à boire, parce qu''il est énorme.'::text),
(361511,40168,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Barista devasa bir kupa getirirse içecek daha çok kahvesi ..., çünkü kupa devasa.'::text,'olacak'::text,'olurdu'::text,'oldu'::text,'Barista devasa bir kupa getirirse içecek daha çok kahvesi olacak, çünkü kupa devasa.'::text),
(361512,40168,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a barista óriási bögrét hoz, több meginnivaló kávéja ..., mert az óriási.'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha a barista óriási bögrét hoz, több meginnivaló kávéja lesz, mert az óriási.'::text),
(350931,38993,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, der Typ ... schon den ganzen Tag Geld und zählt immer noch wie ein Profi, echt jetzt.'::text,'wechselt'::text,'wechselt gerade'::text,'wechselt'::text,'Yo, der Typ wechselt schon den ganzen Tag Geld und zählt immer noch wie ein Profi, echt jetzt.'::text),
(350935,38993,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, цей чувак ... гроші цілий день і досі рахує як профі, реально.'::text,'міняє'::text,'міняє'::text,'міняє'::text,'Йо, цей чувак міняє гроші цілий день і досі рахує як профі, реально.'::text),
(350934,38993,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, este tío lleva todo el día ... dinero y sigue contando como un pro, en serio.'::text,'cambiando'::text,'está cambiando'::text,'cambia'::text,'Oye, este tío lleva todo el día cambiando dinero y sigue contando como un pro, en serio.'::text),
(350933,38993,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, ce gars ... de l''argent toute la journée et compte encore comme un pro, sérieux.'::text,'change'::text,'est en train de changer'::text,'change'::text,'Yo, ce gars change de l''argent toute la journée et compte encore comme un pro, sérieux.'::text),
(350936,38993,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu adam bütün gün para ... ve hâlâ bir profesyonel gibi sayıyor, cidden.'::text,'bozuyor'::text,'bozuyor'::text,'bozar'::text,'Kanka, bu adam bütün gün para bozuyor ve hâlâ bir profesyonel gibi sayıyor, cidden.'::text),
(350937,38993,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ez a srác egész nap ... a pénzt, és még mindig úgy számol, mint egy profi, komolyan.'::text,'váltja'::text,'váltja'::text,'váltja'::text,'Figyu, ez a srác egész nap váltja a pénzt, és még mindig úgy számol, mint egy profi, komolyan.'::text),
(350940,38994,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... tauschen Touristen so viele Scheine an einem kleinen Schalter.'::text,''::text,'sie'::text,'sind'::text,'Selten tauschen Touristen so viele Scheine an einem kleinen Schalter.'::text),
(350944,38994,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рідко ... туристи обмінюють стільки банкнот в одному маленькому пункті.'::text,''::text,'вони'::text,'є'::text,'Рідко туристи обмінюють стільки банкнот в одному маленькому пункті.'::text),
(350943,38994,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rara vez ... los turistas cambian tantos billetes en un solo mostrador pequeño.'::text,''::text,'ellos'::text,'son'::text,'Rara vez los turistas cambian tantos billetes en un solo mostrador pequeño.'::text),
(350942,38994,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement ... des touristes échangent autant de billets à un seul petit guichet.'::text,''::text,'ils'::text,'sont'::text,'Rarement des touristes échangent autant de billets à un seul petit guichet.'::text),
(350945,38994,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nadiren ... turistler tek bir küçük tezgâhta bu kadar çok banknot bozdurur.'::text,''::text,'onlar'::text,NULL::text,'Nadiren turistler tek bir küçük tezgâhta bu kadar çok banknot bozdurur.'::text),
(350946,38994,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ritkán ... váltanak be a turisták ennyi bankjegyet egyetlen kis pultnál.'::text,''::text,'ők'::text,'vannak'::text,'Ritkán váltanak be a turisták ennyi bankjegyet egyetlen kis pultnál.'::text),
(350949,38995,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ließ den Geldwechsler 500 Euro für einen Kunden ...'::text,'wechseln'::text,'wechseln'::text,'gewechselt'::text,'Sie ließ den Geldwechsler 500 Euro für einen Kunden wechseln.'::text),
(350953,38995,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона доручила міняйлові ... 500 євро для клієнта.'::text,'обміняти'::text,'обміняти'::text,'обміняв'::text,'Вона доручила міняйлові обміняти 500 євро для клієнта.'::text),
(350952,38995,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hizo que el cambista ... 500 euros para un cliente.'::text,'cambiara'::text,'cambiar'::text,'cambió'::text,'Hizo que el cambista cambiara 500 euros para un cliente.'::text),
(350951,38995,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a fait ... 500 euros au cambiste pour un client.'::text,'changer'::text,'changer'::text,'changé'::text,'Elle a fait changer 500 euros au cambiste pour un client.'::text),
(350954,38995,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Döviz bürosundaki adama bir müşteri için 500 avro ...'::text,'bozdurdu'::text,'bozdurdu'::text,'bozdu'::text,'Döviz bürosundaki adama bir müşteri için 500 avro bozdurdu.'::text),
(350955,38995,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pénzváltóval ... be 500 eurót egy ügyfél számára.'::text,'váltatott'::text,'váltatott'::text,'váltott'::text,'A pénzváltóval váltatott be 500 eurót egy ügyfél számára.'::text),
(350958,38996,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau wünschte, sie ... ihr Geld gestern hier gewechselt, als der Kurs besser war.'::text,'hätte'::text,'hat'::text,'würde'::text,'Die Frau wünschte, sie hätte ihr Geld gestern hier gewechselt, als der Kurs besser war.'::text),
(350962,38996,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка шкодує, що не ... гроші тут учора, коли курс був кращий.'::text,'обміняла'::text,'обміняла'::text,'обміняє'::text,'Жінка шкодує, що не обміняла гроші тут учора, коли курс був кращий.'::text),
(350961,38996,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer desearía ... su dinero aquí ayer, cuando el cambio era mejor.'::text,'haber cambiado'::text,'cambió'::text,'cambiaría'::text,'La mujer desearía haber cambiado su dinero aquí ayer, cuando el cambio era mejor.'::text),
(350960,38996,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme aimerait ... son argent ici hier, quand le taux était meilleur.'::text,'avoir changé'::text,'changé'::text,'changerait'::text,'La femme aimerait avoir changé son argent ici hier, quand le taux était meilleur.'::text),
(350963,38996,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın keşke parasını dün, kur daha iyiyken burada ... diyor.'::text,'bozdursaydım'::text,'bozdurdum'::text,'bozdururdum'::text,'Kadın keşke parasını dün, kur daha iyiyken burada bozdursaydım diyor.'::text),
(350964,38996,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő azt kívánja, bárcsak tegnap ... itt be a pénzét, amikor jobb volt az árfolyam.'::text,'váltotta volna'::text,'váltotta'::text,'váltaná'::text,'A nő azt kívánja, bárcsak tegnap váltotta volna itt be a pénzét, amikor jobb volt az árfolyam.'::text),
(350967,38997,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Geldwechsler, ... Stand in einem Basar steht, wechselt typischerweise mehrere Währungen.'::text,'dessen'::text,'der'::text,'welcher'::text,'Der Geldwechsler, dessen Stand in einem Basar steht, wechselt typischerweise mehrere Währungen.'::text),
(350971,38997,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Міняйло, ... кіоск стоїть на базарі, зазвичай обмінює кілька валют.'::text,'чий'::text,'який'::text,'що'::text,'Міняйло, чий кіоск стоїть на базарі, зазвичай обмінює кілька валют.'::text),
(350970,38997,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cambista, ... puesto está en un bazar, cambia típicamente varias divisas.'::text,'cuyo'::text,'quien'::text,'que'::text,'El cambista, cuyo puesto está en un bazar, cambia típicamente varias divisas.'::text),
(350969,38997,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le cambiste, ... le stand se trouve dans un bazar, change typiquement plusieurs devises.'::text,'dont'::text,'qui'::text,'lequel'::text,'Le cambiste, dont le stand se trouve dans un bazar, change typiquement plusieurs devises.'::text),
(350972,38997,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tezgâhı bir çarşıda olan sarraf tipik olarak birkaç döviz bozar.'::text,''::text,NULL::text,NULL::text,'Tezgâhı bir çarşıda olan sarraf tipik olarak birkaç döviz bozar.'::text),
(350973,38997,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pénzváltó, ... bódéja egy bazárban van, jellemzően többféle valutát vált.'::text,'akinek a'::text,'aki'::text,'ami'::text,'A pénzváltó, akinek a bódéja egy bazárban van, jellemzően többféle valutát vált.'::text),
(350976,38998,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sie ihr Geld nicht sofort wechselt, ist die ganze Reise ruiniert!'::text,'Wenn'::text,'Für den Fall, dass'::text,'Vorausgesetzt, dass'::text,'Wenn sie ihr Geld nicht sofort wechselt, ist die ganze Reise ruiniert!'::text),
(350980,38998,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... вона не обміняє гроші просто зараз, уся поїздка зіпсована!'::text,'Якщо'::text,'На випадок, якщо'::text,'За умови, що'::text,'Якщо вона не обміняє гроші просто зараз, уся поїздка зіпсована!'::text),
(350979,38998,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... cambie su dinero ahora mismo, todo el viaje está arruinado!'::text,'A menos que'::text,'En caso de que'::text,'Siempre que'::text,'¡A menos que cambie su dinero ahora mismo, todo el viaje está arruinado!'::text),
(350978,38998,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... elle change son argent tout de suite, tout le voyage est fichu !'::text,'Sauf si'::text,'Au cas où'::text,'Si'::text,'Sauf si elle change son argent tout de suite, tout le voyage est fichu !'::text),
(350981,38998,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... parasını hemen şimdi bozdurmazsa, bütün gezi mahvolur!'::text,'Eğer'::text,'Olur da'::text,'Yeter ki'::text,'Eğer parasını hemen şimdi bozdurmazsa, bütün gezi mahvolur!'::text),
(350982,38998,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... most azonnal nem váltja át a pénzét, az egész utazás tönkremegy!'::text,'Ha'::text,'Arra az esetre, ha'::text,'Feltéve, hogy'::text,'Ha most azonnal nem váltja át a pénzét, az egész utazás tönkremegy!'::text),
(350985,38999,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wusste, dass ihr Leben, sobald sie ihr Geld gewechselt hätte, nie mehr dasselbe sein ...!'::text,'würde'::text,'wird'::text,'wird'::text,'Sie wusste, dass ihr Leben, sobald sie ihr Geld gewechselt hätte, nie mehr dasselbe sein würde!'::text),
(350989,38999,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона знала, що щойно обміняє гроші, її життя вже ніколи не ... таким, як раніше!'::text,'буде'::text,'буде'::text,'буде'::text,'Вона знала, що щойно обміняє гроші, її життя вже ніколи не буде таким, як раніше!'::text),
(350988,38999,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Sabía que, en cuanto cambiara su dinero, su vida nunca ... a ser la misma!'::text,'volvería'::text,'volverá'::text,'va a volver'::text,'¡Sabía que, en cuanto cambiara su dinero, su vida nunca volvería a ser la misma!'::text),
(350987,38999,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle savait qu''une fois son argent changé, sa vie ne ... plus jamais la même !'::text,'serait'::text,'sera'::text,'va être'::text,'Elle savait qu''une fois son argent changé, sa vie ne serait plus jamais la même !'::text),
(350990,38999,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Parasını bozdurduğu anda hayatının bir daha asla eskisi gibi ... biliyordu!'::text,'olmayacağını'::text,'olmayacağını'::text,'olmayacağını'::text,'Parasını bozdurduğu anda hayatının bir daha asla eskisi gibi olmayacağını biliyordu!'::text),
(350991,38999,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tudta, hogy amint átváltja a pénzét, az élete soha többé nem ... ugyanaz!'::text,'lesz'::text,'lesz'::text,'lesz'::text,'Tudta, hogy amint átváltja a pénzét, az élete soha többé nem lesz ugyanaz!'::text),
(351003,39001,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hatte die Scheine schon gezählt, als sie ..., noch mehr Geld zu wechseln.'::text,'bat'::text,'gebeten hatte'::text,'hat gebeten'::text,'Er hatte die Scheine schon gezählt, als sie bat, noch mehr Geld zu wechseln.'::text),
(351007,39001,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він уже перерахував банкноти, коли вона ... обміняти ще грошей.'::text,'попросила'::text,'попросила'::text,'попросила'::text,'Він уже перерахував банкноти, коли вона попросила обміняти ще грошей.'::text),
(351006,39001,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ya había contado los billetes cuando ella ... cambiar más dinero.'::text,'pidió'::text,'había pedido'::text,'ha pedido'::text,'Él ya había contado los billetes cuando ella pidió cambiar más dinero.'::text),
(351005,39001,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il avait déjà compté les billets quand elle ... à changer plus d''argent.'::text,'a demandé'::text,'avait demandé'::text,'a demandé'::text,'Il avait déjà compté les billets quand elle a demandé à changer plus d''argent.'::text),
(351008,39001,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O banknotları çoktan saymıştı ki kadın daha fazla para bozdurmak ...'::text,'istedi'::text,'istemişti'::text,'istedi'::text,'O banknotları çoktan saymıştı ki kadın daha fazla para bozdurmak istedi.'::text),
(351009,39001,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már megszámolta a bankjegyeket, amikor a nő ..., hogy váltson még pénzt.'::text,'kérte'::text,'kérte'::text,'kérte'::text,'Már megszámolta a bankjegyeket, amikor a nő kérte, hogy váltson még pénzt.'::text),
(351012,39002,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis sie den Basar verlässt, wird sie all ihre Euro in lokale Scheine ...'::text,'umgetauscht haben'::text,'umtauschen'::text,'tauscht um'::text,'Bis sie den Basar verlässt, wird sie all ihre Euro in lokale Scheine umgetauscht haben.'::text),
(351016,39002,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона вийде з базару, то вже ... всі свої євро на місцеві банкноти.'::text,'обміняє'::text,'обміняє'::text,'обмінює'::text,'Поки вона вийде з базару, то вже обміняє всі свої євро на місцеві банкноти.'::text),
(351015,39002,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando salga del bazar, ... todos sus euros por billetes locales.'::text,'habrá cambiado'::text,'cambiará'::text,'cambia'::text,'Para cuando salga del bazar, habrá cambiado todos sus euros por billetes locales.'::text),
(351014,39002,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici à ce qu''elle quitte le bazar, elle ... tous ses euros contre des billets locaux.'::text,'aura changé'::text,'changera'::text,'change'::text,'D''ici à ce qu''elle quitte le bazar, elle aura changé tous ses euros contre des billets locaux.'::text),
(351017,39002,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çarşıdan çıkana kadar bütün avrolarını yerel paraya ...'::text,'bozdurmuş olacak'::text,'bozduracak'::text,'bozduruyor'::text,'Çarşıdan çıkana kadar bütün avrolarını yerel paraya bozdurmuş olacak.'::text),
(351018,39002,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire elhagyja a bazárt, már az összes euróját ... helyi bankjegyekre.'::text,'átváltotta'::text,'át fogja váltani'::text,'átváltja'::text,'Mire elhagyja a bazárt, már az összes euróját átváltotta helyi bankjegyekre.'::text),
(331455,36829,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie hat gerade die Kissen arrangiert, als sie einfach rückwärts drauf ..., irgendwie ikonisch.'::text,'fiel'::text,'am Fallen war'::text,'gefallen ist'::text,'Bro, sie hat gerade die Kissen arrangiert, als sie einfach rückwärts drauf fiel, irgendwie ikonisch.'::text),
(331459,36829,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона розкладала подушки, коли просто ... на них спиною, досить культово.'::text,'впала'::text,'падала'::text,'впала'::text,'Бро, вона розкладала подушки, коли просто впала на них спиною, досить культово.'::text),
(331458,36829,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, estaba colocando los cojines cuando de repente ... de espaldas sobre ellos, bastante icónico.'::text,'se cayó'::text,'se estaba cayendo'::text,'se ha caído'::text,'Bro, estaba colocando los cojines cuando de repente se cayó de espaldas sobre ellos, bastante icónico.'::text),
(331457,36829,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle arrangeait les coussins quand elle ... d''un coup en arrière dessus, un peu iconique.'::text,'est tombée'::text,'tombait'::text,'est tombée'::text,'Frérot, elle arrangeait les coussins quand elle est tombée d''un coup en arrière dessus, un peu iconique.'::text),
(331460,36829,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yastıkları diziyordu ki birden sırtüstü üstlerine ..., bayağı ikonik.'::text,'düştü'::text,'düşüyordu'::text,'düştü'::text,'Kanka, yastıkları diziyordu ki birden sırtüstü üstlerine düştü, bayağı ikonik.'::text),
(331461,36829,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, épp a párnákat rendezgette, amikor egyszerűen hanyatt ... rájuk, elég ikonikus.'::text,'esett'::text,'esett éppen'::text,'esett'::text,'Tesó, épp a párnákat rendezgette, amikor egyszerűen hanyatt esett rájuk, elég ikonikus.'::text),
(331464,36830,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat bisher 4 Kissen ..., was genau im Soll liegt.'::text,'arrangiert'::text,'arrangiert'::text,'arrangiert'::text,'Sie hat bisher 4 Kissen arrangiert, was genau im Soll liegt.'::text),
(331468,36830,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Досі вона ... 4 подушки, що точно відповідає плану.'::text,'розклала'::text,'розкладала'::text,'розкладає'::text,'Досі вона розклала 4 подушки, що точно відповідає плану.'::text),
(331467,36830,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasta ahora ... 4 cojines, lo que cumple exactamente el objetivo.'::text,'ha colocado'::text,'ha estado colocando'::text,'está colocando'::text,'Hasta ahora ha colocado 4 cojines, lo que cumple exactamente el objetivo.'::text),
(331466,36830,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jusqu''ici, elle ... 4 coussins, ce qui est pile dans l''objectif.'::text,'a disposé'::text,'a disposé'::text,'dispose'::text,'Jusqu''ici, elle a disposé 4 coussins, ce qui est pile dans l''objectif.'::text),
(331469,36830,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu ana kadar 4 yastık ..., bu da tam hedefte.'::text,'dizdi'::text,'diziyor'::text,'diziyor'::text,'Şu ana kadar 4 yastık dizdi, bu da tam hedefte.'::text),
(331470,36830,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eddig 4 párnát ..., ami pontosan megfelel a célnak.'::text,'rendezett el'::text,'rendezgetett'::text,'rendez el'::text,'Eddig 4 párnát rendezett el, ami pontosan megfelel a célnak.'::text),
(331473,36831,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie legte sich hin, nachdem sie die Kissen ..., weil sie ja arrangiert waren.'::text,'arrangiert hatte'::text,'arrangiert hat'::text,'arrangiert'::text,'Sie legte sich hin, nachdem sie die Kissen arrangiert hatte, weil sie ja arrangiert waren.'::text),
(331477,36831,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона лягла, після того як ... подушки, бо вони були розкладені.'::text,'розклала'::text,'розклала'::text,'розкладає'::text,'Вона лягла, після того як розклала подушки, бо вони були розкладені.'::text),
(331476,36831,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se tumbó después de que ... los cojines, porque estaban colocados.'::text,'había colocado'::text,'ha colocado'::text,'coloca'::text,'Se tumbó después de que había colocado los cojines, porque estaban colocados.'::text),
(331475,36831,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle s''est allongée après qu''elle ... les coussins, parce qu''ils étaient disposés.'::text,'avait disposé'::text,'a disposé'::text,'dispose'::text,'Elle s''est allongée après qu''elle avait disposé les coussins, parce qu''ils étaient disposés.'::text),
(331478,36831,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yastıkları ... sonra uzandı, çünkü yastıklar dizilmişti.'::text,'dizmiş olduktan'::text,'dizdikten'::text,'dizdikten'::text,'Yastıkları dizmiş olduktan sonra uzandı, çünkü yastıklar dizilmişti.'::text),
(331479,36831,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lefeküdt, miután ... a párnákat, mert el voltak rendezve.'::text,'elrendezte'::text,'elrendezte'::text,'elrendezi'::text,'Lefeküdt, miután elrendezte a párnákat, mert el voltak rendezve.'::text),
(331491,36833,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn ich Kissen so arrangieren würde wie du, ... mein Sofa auch so gut aus.'::text,'sähe'::text,'sieht'::text,'sieht'::text,'Ehrlich, wenn ich Kissen so arrangieren würde wie du, sähe mein Sofa auch so gut aus.'::text),
(331495,36833,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби я розкладав подушки як ти, мій диван ... так само класно.'::text,'виглядав би'::text,'виглядатиме'::text,'виглядає'::text,'Чесно, якби я розкладав подушки як ти, мій диван виглядав би так само класно.'::text),
(331494,36833,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, si yo colocara los cojines como tú, mi sofá ... así de bien.'::text,'se vería'::text,'se verá'::text,'se ve'::text,'La verdad, si yo colocara los cojines como tú, mi sofá se vería así de bien.'::text),
(331493,36833,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si j''arrangeais les coussins comme toi, mon canapé ... aussi bien.'::text,'aurait l''air'::text,'aura l''air'::text,'a l''air'::text,'Franchement, si j''arrangeais les coussins comme toi, mon canapé aurait l''air aussi bien.'::text),
(331496,36833,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası yastıkları senin gibi dizsem kanepem de bu kadar güzel ...'::text,'görünürdü'::text,'görünecek'::text,'görünüyor'::text,'Açıkçası yastıkları senin gibi dizsem kanepem de bu kadar güzel görünürdü.'::text),
(331497,36833,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha én is úgy rendezném el a párnákat, mint te, a kanapém is ilyen jól ...'::text,'nézne ki'::text,'fog kinézni'::text,'néz ki'::text,'Őszintén, ha én is úgy rendezném el a párnákat, mint te, a kanapém is ilyen jól nézne ki.'::text),
(331500,36834,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kissen wurden in einer ordentlichen Reihe entlang der Sofalehne ...'::text,'arrangiert'::text,'arrangierten'::text,'arrangieren gerade'::text,'Die Kissen wurden in einer ordentlichen Reihe entlang der Sofalehne arrangiert.'::text),
(331504,36834,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подушки ... вздовж спинки дивана рівним рядком.'::text,'були розкладені'::text,'розклали'::text,'розкладають'::text,'Подушки були розкладені вздовж спинки дивана рівним рядком.'::text),
(331503,36834,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los cojines ... a lo largo del respaldo del sofá en una fila ordenada.'::text,'fueron colocados'::text,'colocaron'::text,'están colocando'::text,'Los cojines fueron colocados a lo largo del respaldo del sofá en una fila ordenada.'::text),
(331502,36834,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les coussins ... le long du dossier du canapé en une rangée bien nette.'::text,'ont été disposés'::text,'ont disposé'::text,'sont en train de disposer'::text,'Les coussins ont été disposés le long du dossier du canapé en une rangée bien nette.'::text),
(331505,36834,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yastıklar kanepenin arkası boyunca düzgün bir sıra halinde ...'::text,'dizildi'::text,'dizdi'::text,'diziyor'::text,'Yastıklar kanepenin arkası boyunca düzgün bir sıra halinde dizildi.'::text),
(331506,36834,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A párnákat ... a kanapé háttámlája mentén egy takaros sorban.'::text,'elrendezték'::text,'elrendezte'::text,'rendezik'::text,'A párnákat elrendezték a kanapé háttámlája mentén egy takaros sorban.'::text),
(331509,36835,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... jedes Kissen, bevor sie einen Schritt zurücktrat, um zu schauen.'::text,'arrangierte'::text,'wurde arrangiert'::text,'arrangierend'::text,'Sie arrangierte jedes Kissen, bevor sie einen Schritt zurücktrat, um zu schauen.'::text),
(331513,36835,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... кожну подушку, перш ніж відступити, щоб подивитися.'::text,'поправила'::text,'була поправлена'::text,'поправляючи'::text,'Вона поправила кожну подушку, перш ніж відступити, щоб подивитися.'::text),
(331512,36835,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... cada cojín antes de dar un paso atrás para mirar.'::text,'Colocó'::text,'Fue colocado'::text,'Colocando'::text,'Colocó cada cojín antes de dar un paso atrás para mirar.'::text),
(331511,36835,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... chaque coussin avant de reculer pour regarder.'::text,'a arrangé'::text,'a été arrangée'::text,'arrangeant'::text,'Elle a arrangé chaque coussin avant de reculer pour regarder.'::text),
(331514,36835,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geri çekilip bakmadan önce her yastığı ...'::text,'düzeltti'::text,'düzeltildi'::text,'düzelterek'::text,'Geri çekilip bakmadan önce her yastığı düzeltti.'::text),
(331515,36835,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... minden párnát, mielőtt hátralépett, hogy megnézze.'::text,'Elrendezett'::text,'El lett rendezve'::text,'Elrendezve'::text,'Elrendezett minden párnát, mielőtt hátralépett, hogy megnézze.'::text),
(331518,36836,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... nach dem Arrangieren von ganzen vier Kissen sehr müde sein. Wirklich anstrengende Arbeit.'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Sie muss nach dem Arrangieren von ganzen vier Kissen sehr müde sein. Wirklich anstrengende Arbeit.'::text),
(331522,36836,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після того як вона розклала аж чотири подушки, вона ... бути дуже втомленою. Справді виснажлива робота.'::text,'мусить'::text,'може'::text,'не може'::text,'Після того як вона розклала аж чотири подушки, вона мусить бути дуже втомленою. Справді виснажлива робота.'::text),
(331521,36836,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... estar muy cansada después de colocar cuatro cojines enteros. Un trabajo realmente agotador.'::text,'Debe de'::text,'Puede'::text,'No puede'::text,'Debe de estar muy cansada después de colocar cuatro cojines enteros. Un trabajo realmente agotador.'::text),
(331520,36836,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... être très fatiguée après avoir arrangé quatre coussins entiers. Un travail vraiment épuisant.'::text,'doit'::text,'pourrait'::text,'ne peut pas'::text,'Elle doit être très fatiguée après avoir arrangé quatre coussins entiers. Un travail vraiment épuisant.'::text),
(331523,36836,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Koca dört yastığı dizdikten sonra çok yorgun ... – gerçekten yorucu bir iş.'::text,'olmalı'::text,'olabilir'::text,'olamaz'::text,'Koca dört yastığı dizdikten sonra çok yorgun olmalı – gerçekten yorucu bir iş.'::text),
(331524,36836,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egész négy párna elrendezése után ... nagyon fáradt. Igazán kimerítő munka.'::text,'biztos'::text,'talán'::text,'nem lehet'::text,'Egész négy párna elrendezése után biztos nagyon fáradt. Igazán kimerítő munka.'::text),
(331527,36837,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kissen, ... sie entlang des Sofas arrangiert hat, sind senfgelb, rosa und petrol.'::text,'die'::text,'wer'::text,'deren'::text,'Die Kissen, die sie entlang des Sofas arrangiert hat, sind senfgelb, rosa und petrol.'::text),
(331531,36837,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подушки, ... вона розклала вздовж дивана, гірчичні, рожеві й бірюзові.'::text,'які'::text,'хто'::text,'чиї'::text,'Подушки, які вона розклала вздовж дивана, гірчичні, рожеві й бірюзові.'::text),
(331530,36837,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los cojines ... colocó a lo largo del sofá son mostaza, rosa y verde azulado.'::text,'que'::text,'quien'::text,'cuyos'::text,'Los cojines que colocó a lo largo del sofá son mostaza, rosa y verde azulado.'::text),
(331529,36837,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les coussins ... elle a arrangés le long du canapé sont moutarde, rose et bleu canard.'::text,'que'::text,'qui'::text,'dont'::text,'Les coussins que elle a arrangés le long du canapé sont moutarde, rose et bleu canard.'::text),
(331532,36837,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... kanepe boyunca dizdiği yastıklar hardal, pembe ve petrol mavisi.'::text,''::text,NULL::text,NULL::text,'Kanepe boyunca dizdiği yastıklar hardal, pembe ve petrol mavisi.'::text),
(331533,36837,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A párnák, ... a kanapé mentén elrendezett, mustársárgák, rózsaszínek és kékeszöldek.'::text,'amelyeket'::text,'akik'::text,'amelyeknek a'::text,'A párnák, amelyeket a kanapé mentén elrendezett, mustársárgák, rózsaszínek és kékeszöldek.'::text),
(331536,36838,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sagte, sie ... die Kissen nach Farbe arrangiert.'::text,'hätte'::text,'habe'::text,'arrangiere'::text,'Sie sagte, sie hätte die Kissen nach Farbe arrangiert.'::text),
(331540,36838,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала, що ... подушки за кольором.'::text,'розклала'::text,'розклала'::text,'розкладає'::text,'Вона сказала, що розклала подушки за кольором.'::text),
(331539,36838,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que ... los cojines por color.'::text,'había colocado'::text,'ha colocado'::text,'coloca'::text,'Dijo que había colocado los cojines por color.'::text),
(331538,36838,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit qu''elle ... les coussins par couleur.'::text,'avait arrangé'::text,'a arrangé'::text,'arrange'::text,'Elle a dit qu''elle avait arrangé les coussins par couleur.'::text),
(331541,36838,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yastıkları renge göre ... söyledi.'::text,'dizmiş olduğunu'::text,'dizdiğini'::text,'dizdiğini'::text,'Yastıkları renge göre dizmiş olduğunu söyledi.'::text),
(331542,36838,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy szín szerint ... el a párnákat.'::text,'rendezte'::text,'rendezte'::text,'rendezi'::text,'Azt mondta, hogy szín szerint rendezte el a párnákat.'::text),
(331545,36839,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als Kind ... sie ihre Spielsachen auch immer in Reihen auf dem Sofa.'::text,'ordnete'::text,'ordnete'::text,'war gewohnt zu ordnen'::text,'Als Kind ordnete sie ihre Spielsachen auch immer in Reihen auf dem Sofa.'::text),
(331549,36839,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У дитинстві вона теж ... свої іграшки рядками на дивані.'::text,'розкладала'::text,'розкладала'::text,'звикла розкладати'::text,'У дитинстві вона теж розкладала свої іграшки рядками на дивані.'::text),
(331548,36839,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De niña, también ... sus juguetes en filas en el sofá.'::text,'colocaba'::text,'solía colocar'::text,'estaba acostumbrada a colocar'::text,'De niña, también colocaba sus juguetes en filas en el sofá.'::text),
(331547,36839,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Enfant, elle ... aussi ses jouets en rangées sur le canapé.'::text,'alignait'::text,'avait l''habitude d''aligner'::text,'était habituée à aligner'::text,'Enfant, elle alignait aussi ses jouets en rangées sur le canapé.'::text),
(331550,36839,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocukken oyuncaklarını da kanepenin üstüne sıra sıra ...'::text,'dizerdi'::text,'dizerdi'::text,'dizmeye alışkındı'::text,'Çocukken oyuncaklarını da kanepenin üstüne sıra sıra dizerdi.'::text),
(331551,36839,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gyerekként a játékait is sorba ... a kanapén.'::text,'rakta'::text,'rakta'::text,'szokta rakni'::text,'Gyerekként a játékait is sorba rakta a kanapén.'::text),
(342723,38081,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... sie schon wieder die Kupferkessel. Was für ein aufregender Job.'::text,'poliert'::text,'wird polieren'::text,'poliert'::text,'Morgen um diese Zeit poliert sie schon wieder die Kupferkessel. Was für ein aufregender Job.'::text),
(342727,38081,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час вона знову ... мідні котли. Яка захоплива робота.'::text,'поліруватиме'::text,'відполірує'::text,'полірує'::text,'Завтра в цей час вона знову поліруватиме мідні котли. Яка захоплива робота.'::text),
(342726,38081,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora ... otra vez los tanques de cobre. ¡Qué trabajo más emocionante!'::text,'estará puliendo'::text,'pulirá'::text,'pule'::text,'Mañana a esta hora estará puliendo otra vez los tanques de cobre. ¡Qué trabajo más emocionante!'::text),
(342725,38081,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, elle ... de nouveau les cuves en cuivre. Quel boulot passionnant.'::text,'sera en train de polir'::text,'polira'::text,'polit'::text,'Demain à la même heure, elle sera en train de polir de nouveau les cuves en cuivre. Quel boulot passionnant.'::text),
(342728,38081,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte yine bakır kazanları ... – ne heyecan verici bir iş.'::text,'parlatıyor olacak'::text,'parlatacak'::text,'parlatıyor'::text,'Yarın bu saatte yine bakır kazanları parlatıyor olacak – ne heyecan verici bir iş.'::text),
(342729,38081,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor megint ... a rézüstöket. Micsoda izgalmas munka.'::text,'fogja fényesíteni'::text,'fényesíti ki'::text,'fényesíti'::text,'Holnap ilyenkor megint fogja fényesíteni a rézüstöket. Micsoda izgalmas munka.'::text),
(342732,38082,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie schwört, sie ... morgen die Kupferkessel. Eindeutig oberste Priorität.'::text,'putzt'::text,'wird putzen'::text,'putzt gerade'::text,'Sie schwört, sie putzt morgen die Kupferkessel. Eindeutig oberste Priorität.'::text),
(342736,38082,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона клянеться, що завтра ... мідні котли. Явно головний пріоритет.'::text,'почистить'::text,'чиститиме'::text,'чистить'::text,'Вона клянеться, що завтра почистить мідні котли. Явно головний пріоритет.'::text),
(342735,38082,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jura que mañana ... los tanques de cobre. Claramente, la máxima prioridad.'::text,'limpiará'::text,'estará limpiando'::text,'está limpiando'::text,'Jura que mañana limpiará los tanques de cobre. Claramente, la máxima prioridad.'::text),
(342734,38082,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle jure qu''elle ... les cuves en cuivre demain. Clairement une priorité absolue.'::text,'nettoiera'::text,'sera en train de nettoyer'::text,'nettoie'::text,'Elle jure qu''elle nettoiera les cuves en cuivre demain. Clairement une priorité absolue.'::text),
(342737,38082,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bakır kazanları ... yemin ediyor. Belli ki bir numaralı öncelik.'::text,'temizleyeceğine'::text,'temizliyor olacağına'::text,'temizlediğine'::text,'Yarın bakır kazanları temizleyeceğine yemin ediyor. Belli ki bir numaralı öncelik.'::text),
(342738,38082,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megesküszik, hogy holnap ... a rézüstöket. Nyilván ez az első számú prioritás.'::text,'kitisztítja'::text,'tisztítani fogja'::text,'tisztítja'::text,'Megesküszik, hogy holnap kitisztítja a rézüstöket. Nyilván ez az első számú prioritás.'::text),
(342750,38084,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Brauerei beschloss, all ihre hohen Kessel aus Kupfer ...'::text,'zu bauen'::text,'das Bauen'::text,'gebaut'::text,'Die Brauerei beschloss, all ihre hohen Kessel aus Kupfer zu bauen.'::text),
(342754,38084,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пивоварня вирішила ... всі свої високі котли з міді.'::text,'виготовити'::text,'виготовлення'::text,'виготовила'::text,'Пивоварня вирішила виготовити всі свої високі котли з міді.'::text),
(342753,38084,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cervecería decidió ... todos sus tanques altos de cobre.'::text,'hacer'::text,'haciendo'::text,'hizo'::text,'La cervecería decidió hacer todos sus tanques altos de cobre.'::text),
(342752,38084,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La brasserie a décidé de ... toutes ses grandes cuves en cuivre.'::text,'fabriquer'::text,'fabriquant'::text,'fabriqué'::text,'La brasserie a décidé de fabriquer toutes ses grandes cuves en cuivre.'::text),
(342755,38084,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bira fabrikası bütün yüksek kazanlarını bakırdan ... karar verdi.'::text,'yapmaya'::text,'yapmayı'::text,'yaptı'::text,'Bira fabrikası bütün yüksek kazanlarını bakırdan yapmaya karar verdi.'::text),
(342756,38084,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sörfőzde úgy döntött, hogy az összes magas üstjét rézből ...'::text,'készíti el'::text,'elkészítve'::text,'elkészítette'::text,'A sörfőzde úgy döntött, hogy az összes magas üstjét rézből készíti el.'::text),
(342759,38085,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die hohen Kessel sind aus Kupfer, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Die hohen Kessel sind aus Kupfer, oder?'::text),
(342763,38085,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ті високі котли з міді, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Ті високі котли з міді, правда?'::text),
(342762,38085,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esos tanques altos son de cobre, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Esos tanques altos son de cobre, ¿verdad?'::text),
(342761,38085,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ces grandes cuves sont en cuivre, ... ?'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'Ces grandes cuves sont en cuivre, n''est-ce pas ?'::text),
(342764,38085,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yüksek kazanlar bakırdan, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'O yüksek kazanlar bakırdan, değil mi?'::text),
(342765,38085,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azok a magas üstök rézből vannak, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Azok a magas üstök rézből vannak, ugye?'::text),
(342768,38086,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kupferkessel glühen wie ein Inferno, und ... die Hängelampe!'::text,'genauso'::text,'genauso'::text,'genauso wenig'::text,'Die Kupferkessel glühen wie ein Inferno, und genauso die Hängelampe!'::text),
(342772,38086,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мідні котли палають, як пекло, і ... підвісна лампа!'::text,'так само'::text,'так само'::text,'так само не'::text,'Мідні котли палають, як пекло, і так само підвісна лампа!'::text),
(342771,38086,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Los tanques de cobre brillan como un infierno, y ... la lámpara colgante!'::text,'también'::text,'también'::text,'tampoco'::text,'¡Los tanques de cobre brillan como un infierno, y también la lámpara colgante!'::text),
(342770,38086,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les cuves en cuivre flamboient comme un enfer, ... la lampe suspendue !'::text,'tout comme'::text,'tout comme'::text,'contrairement à'::text,'Les cuves en cuivre flamboient comme un enfer, tout comme la lampe suspendue !'::text),
(342773,38086,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bakır kazanlar cehennem gibi parlıyor, asılı lamba ...!'::text,'da öyle'::text,'da öyle'::text,'da öyle değil'::text,'Bakır kazanlar cehennem gibi parlıyor, asılı lamba da öyle!'::text),
(342774,38086,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rézüstök úgy izzanak, mint a pokol, és ... a függőlámpa!'::text,'ugyanígy'::text,'ugyanígy'::text,'ugyanígy nem'::text,'A rézüstök úgy izzanak, mint a pokol, és ugyanígy a függőlámpa!'::text),
(342777,38087,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, ich hab gehört, dass sie bis Freitag alle Kupferkessel ...'::text,'poliert haben werden'::text,'polieren werden'::text,'am Polieren sein werden'::text,'Girl, ich hab gehört, dass sie bis Freitag alle Kupferkessel poliert haben werden.'::text),
(342781,38087,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що до п’ятниці вони ... всі мідні котли.'::text,'відполірують'::text,'відполірують'::text,'поліруватимуть'::text,'Подруго, я чула, що до п’ятниці вони відполірують всі мідні котли.'::text),
(342780,38087,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, he oído que para el viernes ... todos los tanques de cobre.'::text,'habrán pulido'::text,'pulirán'::text,'estarán puliendo'::text,'Tía, he oído que para el viernes habrán pulido todos los tanques de cobre.'::text),
(342779,38087,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il paraît que d''ici vendredi, ils ... toutes les cuves en cuivre.'::text,'auront poli'::text,'poliront'::text,'seront en train de polir'::text,'Meuf, il paraît que d''ici vendredi, ils auront poli toutes les cuves en cuivre.'::text),
(342782,38087,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre cumaya kadar bütün bakır kazanları ...'::text,'parlatmış olacaklarmış'::text,'parlatacaklarmış'::text,'parlatıyor olacaklarmış'::text,'Kızım, duyduğuma göre cumaya kadar bütün bakır kazanları parlatmış olacaklarmış.'::text),
(342783,38087,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy péntekre az összes rézüstöt ...'::text,'kifényesítik'::text,'ki fogják fényesíteni'::text,'fényesíteni fogják'::text,'Csajszi, azt hallottam, hogy péntekre az összes rézüstöt kifényesítik.'::text),
(342786,38088,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätten die Bauleute Stahl statt Kupfer verwendet, ... die Brauerei letztes Jahr Geld gespart.'::text,'hätte'::text,'würde'::text,'hat'::text,'Hätten die Bauleute Stahl statt Kupfer verwendet, hätte die Brauerei letztes Jahr Geld gespart.'::text),
(342790,38088,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби будівельники використали сталь замість міді, пивоварня ... гроші минулого року.'::text,'заощадила б'::text,'заощадила б'::text,'заощадила'::text,'Якби будівельники використали сталь замість міді, пивоварня заощадила б гроші минулого року.'::text),
(342789,38088,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si los constructores hubieran usado acero en lugar de cobre, la cervecería ... dinero el año pasado.'::text,'habría ahorrado'::text,'ahorraría'::text,'ahorró'::text,'Si los constructores hubieran usado acero en lugar de cobre, la cervecería habría ahorrado dinero el año pasado.'::text),
(342788,38088,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les constructeurs avaient utilisé de l''acier au lieu du cuivre, la brasserie ... de l''argent l''an dernier.'::text,'aurait économisé'::text,'économiserait'::text,'a économisé'::text,'Si les constructeurs avaient utilisé de l''acier au lieu du cuivre, la brasserie aurait économisé de l''argent l''an dernier.'::text),
(342791,38088,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnşaatçılar bakır yerine çelik kullansaydı, bira fabrikası geçen yıl para ...'::text,'tasarruf etmiş olurdu'::text,'tasarruf ederdi'::text,'tasarruf etti'::text,'İnşaatçılar bakır yerine çelik kullansaydı, bira fabrikası geçen yıl para tasarruf etmiş olurdu.'::text),
(342792,38088,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az építők réz helyett acélt használtak volna, a sörfőzde tavaly pénzt ...'::text,'spórolt volna'::text,'spórolna'::text,'spórolt'::text,'Ha az építők réz helyett acélt használtak volna, a sörfőzde tavaly pénzt spórolt volna.'::text),
(342795,38089,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also, angeblich stammt ... in diesen Kesseln von einem alten Kirchendach.'::text,'das Kupfer'::text,'ein Kupfer'::text,'Kupfer'::text,'Okay, also, angeblich stammt das Kupfer in diesen Kesseln von einem alten Kirchendach.'::text),
(342799,38089,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, ходять чутки, що ... в тих котлах походить зі старого церковного даху.'::text,'мідь'::text,'мідь'::text,'мідь'::text,'Коротше, ходять чутки, що мідь в тих котлах походить зі старого церковного даху.'::text),
(342798,38089,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues dicen que ... de esos tanques salió del tejado de una vieja iglesia.'::text,'el cobre'::text,'un cobre'::text,'cobre'::text,'Vale, pues dicen que el cobre de esos tanques salió del tejado de una vieja iglesia.'::text),
(342797,38089,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, la rumeur dit que ... de ces cuves vient d''un vieux toit d''église.'::text,'le cuivre'::text,'un cuivre'::text,'cuivre'::text,'Bon alors, la rumeur dit que le cuivre de ces cuves vient d''un vieux toit d''église.'::text),
(342800,38089,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, söylentiye göre o kazanlardaki ... eski bir kilise çatısından gelmiş.'::text,'bakır'::text,'bir bakır'::text,'bakır'::text,'Tamam, söylentiye göre o kazanlardaki bakır eski bir kilise çatısından gelmiş.'::text),
(342801,38089,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval a pletyka szerint ... azokban az üstökben egy régi templomtetőből származik.'::text,'a réz'::text,'egy réz'::text,'réz'::text,'Oké, szóval a pletyka szerint a réz azokban az üstökben egy régi templomtetőből származik.'::text),
(342813,38091,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... stundenlang vor diesen Kupferkesseln gearbeitet, bevor deine Freunde kamen. Ikonisch.'::text,'hattest'::text,'hast'::text,'arbeitest'::text,'Du hattest stundenlang vor diesen Kupferkesseln gearbeitet, bevor deine Freunde kamen. Ikonisch.'::text),
(342817,38091,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... перед тими мідними котлами годинами, поки не прийшли твої друзі. Іконічно.'::text,'працювала'::text,'працювала'::text,'працюєш'::text,'Ти працювала перед тими мідними котлами годинами, поки не прийшли твої друзі. Іконічно.'::text),
(342816,38091,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... horas trabajando delante de esos tanques de cobre antes de que llegaran tus amigos. Icónico.'::text,'Llevabas'::text,'Llevas'::text,'Estás'::text,'Llevabas horas trabajando delante de esos tanques de cobre antes de que llegaran tus amigos. Icónico.'::text),
(342815,38091,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... pendant des heures devant ces cuves en cuivre avant l''arrivée de tes amis. Iconique.'::text,'avais travaillé'::text,'as travaillé'::text,'travailles'::text,'Tu avais travaillé pendant des heures devant ces cuves en cuivre avant l''arrivée de tes amis. Iconique.'::text),
(342818,38091,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşların gelmeden önce saatlerce o bakır kazanların önünde ... – efsane.'::text,'çalışıyordun'::text,'çalışıyorsun'::text,'çalışıyorsun'::text,'Arkadaşların gelmeden önce saatlerce o bakır kazanların önünde çalışıyordun – efsane.'::text),
(342819,38091,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Órákig ... azok előtt a rézüstök előtt, mielőtt megjöttek a barátaid. Ikonikus.'::text,'dolgoztál'::text,'dolgoztál'::text,'dolgozol'::text,'Órákig dolgoztál azok előtt a rézüstök előtt, mielőtt megjöttek a barátaid. Ikonikus.'::text),
(359256,39918,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Reihen von Lichterketten ... vom Mann im geblümten Hemd an die Wand gehängt.'::text,'wurden'::text,'hingen'::text,'hängen'::text,'Reihen von Lichterketten wurden vom Mann im geblümten Hemd an die Wand gehängt.'::text),
(359260,39918,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ряди вогників ... на стіну чоловіком у квітчастій сорочці.'::text,'були повішені'::text,'повісили'::text,'висять'::text,'Ряди вогників були повішені на стіну чоловіком у квітчастій сорочці.'::text),
(359259,39918,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Filas de lucecitas ... en la pared por el hombre de la camisa de flores.'::text,'fueron colgadas'::text,'colgaron'::text,'están colgando'::text,'Filas de lucecitas fueron colgadas en la pared por el hombre de la camisa de flores.'::text),
(359258,39918,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Des rangées de guirlandes lumineuses ... au mur par l''homme en chemise à fleurs.'::text,'ont été accrochées'::text,'ont accroché'::text,'sont accrochées'::text,'Des rangées de guirlandes lumineuses ont été accrochées au mur par l''homme en chemise à fleurs.'::text),
(359261,39918,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çiçekli gömlekli adam tarafından duvara sıra sıra ışık zincirleri ...'::text,'asıldı'::text,'astı'::text,'asılı duruyor'::text,'Çiçekli gömlekli adam tarafından duvara sıra sıra ışık zincirleri asıldı.'::text),
(359262,39918,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fényfüzérsorokat a virágos inges férfi ... fel a falra.'::text,'akasztotta'::text,'akasztották'::text,'akasztja'::text,'A fényfüzérsorokat a virágos inges férfi akasztotta fel a falra.'::text),
(359265,39919,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann ... die ganze Girlande in 10 Minuten auf, noch vor dem Zeitplan.'::text,'hängte'::text,'wurde gehängt'::text,'hängend'::text,'Der Mann hängte die ganze Girlande in 10 Minuten auf, noch vor dem Zeitplan.'::text),
(359269,39919,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік ... всю гірлянду за 10 хвилин, раніше за графік.'::text,'повісив'::text,'був повішений'::text,'вішаючи'::text,'Чоловік повісив всю гірлянду за 10 хвилин, раніше за графік.'::text),
(359268,39919,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... toda la guirnalda en 10 minutos, antes de lo previsto.'::text,'colgó'::text,'fue colgado'::text,'colgando'::text,'El hombre colgó toda la guirnalda en 10 minutos, antes de lo previsto.'::text),
