(359270,39919,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam bütün girlandı 10 dakikada, plandan önce ...'::text,'astı'::text,'asıldı'::text,'asarak'::text,'Adam bütün girlandı 10 dakikada, plandan önce astı.'::text),
(359271,39919,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi 10 perc alatt ... fel az egész girlandot, a tervezettnél hamarabb.'::text,'akasztotta'::text,'lett akasztva'::text,'akasztva'::text,'A férfi 10 perc alatt akasztotta fel az egész girlandot, a tervezettnél hamarabb.'::text),
(359283,39921,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Girlande, ... von der Wand hängt, bildet eine Schlaufe, was typischerweise durch Schwerkraft verursacht wird.'::text,'die'::text,'wer'::text,'deren'::text,'Die Girlande, die von der Wand hängt, bildet eine Schlaufe, was typischerweise durch Schwerkraft verursacht wird.'::text),
(359287,39921,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гірлянда, ... звисає зі стіни, утворює петлю, що зазвичай спричиняє гравітація.'::text,'яка'::text,'хто'::text,'чия'::text,'Гірлянда, яка звисає зі стіни, утворює петлю, що зазвичай спричиняє гравітація.'::text),
