(359285,39921,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La guirlande ... pend du mur forme une boucle, ce qui est typiquement causé par la gravité.'::text,'qui'::text,'qui'::text,'dont'::text,'La guirlande qui pend du mur forme une boucle, ce qui est typiquement causé par la gravité.'::text),
(359288,39921,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Duvardan ... sarkan girland bir ilmek oluşturuyor, ki bu tipik olarak yer çekiminden kaynaklanır.'::text,''::text,NULL::text,NULL::text,'Duvardan sarkan girland bir ilmek oluşturuyor, ki bu tipik olarak yer çekiminden kaynaklanır.'::text),
(359289,39921,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A girland, ... a falról lóg, hurkot formál, amit jellemzően a gravitáció okoz.'::text,'amely'::text,'aki'::text,'amelynek a'::text,'A girland, amely a falról lóg, hurkot formál, amit jellemzően a gravitáció okoz.'::text),
(359292,39922,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ..., Deko aufzuhängen, aber jetzt lebt er komplett dafür!'::text,'hasste es früher'::text,'hasste es immer'::text,'war gewohnt, es zu hassen'::text,'Er hasste es früher, Deko aufzuhängen, aber jetzt lebt er komplett dafür!'::text),
(359296,39922,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... вішати прикраси, а тепер просто живе цим!'::text,'раніше ненавидів'::text,'бувало, ненавидів'::text,'звик ненавидіти'::text,'Він раніше ненавидів вішати прикраси, а тепер просто живе цим!'::text),
(359295,39922,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... colgar adornos, pero ahora vive totalmente para ello!'::text,'Solía odiar'::text,'Odiaba'::text,'Estaba acostumbrado a odiar'::text,'¡Solía odiar colgar adornos, pero ahora vive totalmente para ello!'::text),
(359294,39922,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, il ... accrocher des décorations, mais maintenant il vit carrément pour ça !'::text,'détestait'::text,'détestait'::text,'était habitué à détester'::text,'Avant, il détestait accrocher des décorations, mais maintenant il vit carrément pour ça !'::text),
(359297,39922,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden süs asmaktan ..., ama şimdi resmen bunun için yaşıyor!'::text,'nefret ederdi'::text,'nefret ederdi'::text,'nefret etmeye alışkındı'::text,'Eskiden süs asmaktan nefret ederdi, ama şimdi resmen bunun için yaşıyor!'::text),
(359298,39922,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen ... a díszek felaggatását, most viszont egyenesen ezért él!'::text,'utálta'::text,'utálta'::text,'hozzá volt szokva, hogy utálja'::text,'Régen utálta a díszek felaggatását, most viszont egyenesen ezért él!'::text),
(359301,39923,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er weigert sich, auch nur eine einzige Girlande schief ..., sonst ist die ganze Party ruiniert!'::text,'aufzuhängen'::text,'aufzuhängen'::text,'aufhängen'::text,'Er weigert sich, auch nur eine einzige Girlande schief aufzuhängen, sonst ist die ganze Party ruiniert!'::text),
(359305,39923,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він відмовляється ... хоча б одну гірлянду криво, бо інакше вся вечірка зіпсована!'::text,'вішати'::text,'вішання'::text,'вішати'::text,'Він відмовляється вішати хоча б одну гірлянду криво, бо інакше вся вечірка зіпсована!'::text),
