(359303,39923,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il refuse de ... une seule guirlande de travers, sinon toute la fête est fichue !'::text,'mettre'::text,'mettant'::text,'mettre'::text,'Il refuse de mettre une seule guirlande de travers, sinon toute la fête est fichue !'::text),
