(359310,39924,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Luftschlangen hängen von jeder Ecke der Decke, ...?'::text,'nicht wahr'::text,'nicht wahr'::text,'nicht wahr'::text,'Die Luftschlangen hängen von jeder Ecke der Decke, nicht wahr?'::text),
