(352674,39186,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vörös szakállú férfi eddig húsz csata-rekonstrukcióban ...'::text,'harcolt'::text,'harcolt'::text,'harcol'::text,'A vörös szakállú férfi eddig húsz csata-rekonstrukcióban harcolt.'::text),
(352677,39187,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der gestürzte Kämpfer bestritt, schlecht ..., und gab seinem Schild die Schuld.'::text,'gekämpft zu haben'::text,'zu kämpfen'::text,'kämpfte'::text,'Der gestürzte Kämpfer bestritt, schlecht gekämpft zu haben, und gab seinem Schild die Schuld.'::text),
(352681,39187,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Повалений боєць заперечив, що ... погано, і звинуватив свій щит.'::text,'бився'::text,'битися'::text,'бився'::text,'Повалений боєць заперечив, що бився погано, і звинуватив свій щит.'::text),
(352680,39187,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El luchador caído negó ... mal y le echó la culpa a su escudo.'::text,'haber luchado'::text,'luchar'::text,'luchó'::text,'El luchador caído negó haber luchado mal y le echó la culpa a su escudo.'::text),
(352679,39187,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le combattant tombé a nié avoir mal ... et a accusé son bouclier.'::text,'combattu'::text,'combattre'::text,'combattu'::text,'Le combattant tombé a nié avoir mal combattu et a accusé son bouclier.'::text),
(352682,39187,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Düşen savaşçı kötü ... inkâr etti ve suçu kalkanına attı.'::text,'dövüştüğünü'::text,'dövüşmeyi'::text,'dövüştü'::text,'Düşen savaşçı kötü dövüştüğünü inkâr etti ve suçu kalkanına attı.'::text),
(352683,39187,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az elesett harcos tagadta, hogy rosszul ..., és a pajzsát hibáztatta.'::text,'harcolt'::text,'harcolni'::text,'harcolt'::text,'Az elesett harcos tagadta, hogy rosszul harcolt, és a pajzsát hibáztatta.'::text),
(352686,39188,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kämpfer auf dem Rasen ... nicht lange gekämpft haben; er ging schon in der ersten Minute zu Boden.'::text,'kann'::text,'muss'::text,'sollte'::text,'Der Kämpfer auf dem Rasen kann nicht lange gekämpft haben; er ging schon in der ersten Minute zu Boden.'::text),
(352690,39188,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Боєць на траві ... битися довго; він упав уже на першій хвилині.'::text,'не міг'::text,'мусив'::text,'мав би'::text,'Боєць на траві не міг битися довго; він упав уже на першій хвилині.'::text),
(352689,39188,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El luchador del césped ... luchado mucho rato; cayó en el primer minuto.'::text,'no puede haber'::text,'debe de haber'::text,'debería haber'::text,'El luchador del césped no puede haber luchado mucho rato; cayó en el primer minuto.'::text),
(352688,39188,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le combattant dans l''herbe ... longtemps ; il est tombé dès la première minute.'::text,'n''a pas pu combattre'::text,'a dû combattre'::text,'aurait dû combattre'::text,'Le combattant dans l''herbe n''a pas pu combattre longtemps ; il est tombé dès la première minute.'::text),
(352691,39188,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çimdeki savaşçı uzun süre dövüşmüş ...; daha ilk dakikada yere düştü.'::text,'olamaz'::text,'olmalı'::text,'olmalıydı'::text,'Çimdeki savaşçı uzun süre dövüşmüş olamaz; daha ilk dakikada yere düştü.'::text),
(352692,39188,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A füvön fekvő harcos ... sokáig; már az első percben elesett.'::text,'nem harcolhatott'::text,'biztosan harcolt'::text,'kellett volna harcolnia'::text,'A füvön fekvő harcos nem harcolhatott sokáig; már az első percben elesett.'::text),
(352695,39189,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kunde ließ 40 Darsteller in voller Rüstung für das Publikum ...'::text,'kämpfen'::text,'kämpfen'::text,'gekämpft'::text,'Der Kunde ließ 40 Darsteller in voller Rüstung für das Publikum kämpfen.'::text),
(352699,39189,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Клієнт змусив 40 реконструкторів ... в повних обладунках для глядачів.'::text,'битися'::text,'битися'::text,'билися'::text,'Клієнт змусив 40 реконструкторів битися в повних обладунках для глядачів.'::text),
(352698,39189,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cliente hizo ... a 40 recreadores con armadura completa para el público.'::text,'luchar'::text,'luchar'::text,'luchado'::text,'El cliente hizo luchar a 40 recreadores con armadura completa para el público.'::text),
(352697,39189,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le client a fait ... 40 reconstituteurs en armure complète pour la foule.'::text,'combattre'::text,'combattre'::text,'combattu'::text,'Le client a fait combattre 40 reconstituteurs en armure complète pour la foule.'::text),
(352700,39189,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Müşteri 40 canlandırma oyuncusunu seyirciler için tam zırhla ...'::text,'dövüştürdü'::text,'dövüştürdü'::text,'dövüştü'::text,'Müşteri 40 canlandırma oyuncusunu seyirciler için tam zırhla dövüştürdü.'::text),
(352701,39189,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ügyfél 40 hagyományőrzőt ... teljes páncélban a közönségnek.'::text,'harcoltatott'::text,'harcoltatott'::text,'harcolt'::text,'Az ügyfél 40 hagyományőrzőt harcoltatott teljes páncélban a közönségnek.'::text),
(352704,39190,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kämpfer auf dem Rasen wünschte, er ... hinter einem größeren Schild gekämpft.'::text,'hätte'::text,'habe'::text,'würde'::text,'Der Kämpfer auf dem Rasen wünschte, er hätte hinter einem größeren Schild gekämpft.'::text),
(352708,39190,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Боєць на траві шкодує, що не ... за більшим щитом.'::text,'бився'::text,'бився'::text,'битиметься'::text,'Боєць на траві шкодує, що не бився за більшим щитом.'::text),
(352707,39190,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El luchador del césped desearía ... detrás de un escudo más grande.'::text,'haber luchado'::text,'luchó'::text,'lucharía'::text,'El luchador del césped desearía haber luchado detrás de un escudo más grande.'::text),
(352706,39190,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le combattant dans l''herbe aimerait ... derrière un bouclier plus grand.'::text,'avoir combattu'::text,'combattre'::text,'combattrait'::text,'Le combattant dans l''herbe aimerait avoir combattu derrière un bouclier plus grand.'::text),
(352709,39190,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çimdeki savaşçı keşke daha büyük bir kalkanın arkasında ... diyor.'::text,'dövüşseydim'::text,'dövüştüm'::text,'dövüşürdüm'::text,'Çimdeki savaşçı keşke daha büyük bir kalkanın arkasında dövüşseydim diyor.'::text),
(352710,39190,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A füvön fekvő harcos azt kívánja, bárcsak egy nagyobb pajzs mögött ...'::text,'harcolt volna'::text,'harcolna'::text,'harcolni fog'::text,'A füvön fekvő harcos azt kívánja, bárcsak egy nagyobb pajzs mögött harcolt volna.'::text),
(352713,39191,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Darsteller, ... Kampf typischerweise mittelalterlichen Regeln folgt, tragen Kettenhemden.'::text,'deren'::text,'die'::text,'welche'::text,'Die Darsteller, deren Kampf typischerweise mittelalterlichen Regeln folgt, tragen Kettenhemden.'::text),
(352717,39191,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Реконструктори, ... бій зазвичай відбувається за середньовічними правилами, носять кольчуги.'::text,'чий'::text,'які'::text,'що'::text,'Реконструктори, чий бій зазвичай відбувається за середньовічними правилами, носять кольчуги.'::text),
(352716,39191,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los recreadores, ... combate sigue típicamente reglas medievales, llevan cota de malla.'::text,'cuyo'::text,'quienes'::text,'que'::text,'Los recreadores, cuyo combate sigue típicamente reglas medievales, llevan cota de malla.'::text),
(352715,39191,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les reconstituteurs, ... le combat suit typiquement des règles médiévales, portent des cottes de mailles.'::text,'dont'::text,'qui'::text,'lesquels'::text,'Les reconstituteurs, dont le combat suit typiquement des règles médiévales, portent des cottes de mailles.'::text),
(352718,39191,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... dövüşü tipik olarak ortaçağ kurallarına uyan canlandırma oyuncuları zincir zırh giyer.'::text,''::text,NULL::text,NULL::text,'Dövüşü tipik olarak ortaçağ kurallarına uyan canlandırma oyuncuları zincir zırh giyer.'::text),
(352719,39191,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hagyományőrzők, ... harca jellemzően középkori szabályokat követ, láncinget viselnek.'::text,'akiknek a'::text,'akik'::text,'amelyek'::text,'A hagyományőrzők, akiknek a harca jellemzően középkori szabályokat követ, láncinget viselnek.'::text),
(352731,39193,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonnenuntergang werden sie sechs Stunden lang ..., und das Feld wird totales Chaos sein!'::text,'gekämpft haben'::text,'kämpfen'::text,'kämpfen'::text,'Bis Sonnenuntergang werden sie sechs Stunden lang gekämpft haben, und das Feld wird totales Chaos sein!'::text),
(352735,39193,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця вони ... вже шість годин, і на полі буде повний хаос!'::text,'битимуться'::text,'битимуться'::text,'битимуться'::text,'До заходу сонця вони битимуться вже шість годин, і на полі буде повний хаос!'::text),
(352734,39193,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para el atardecer ... seis horas luchando, y el campo será un caos total!'::text,'llevarán'::text,'estarán'::text,'lucharán'::text,'¡Para el atardecer llevarán seis horas luchando, y el campo será un caos total!'::text),
(352733,39193,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, ils ... pendant six heures, et le terrain sera un chaos total !'::text,'se seront battus'::text,'se battront'::text,'se battront'::text,'D''ici le coucher du soleil, ils se seront battus pendant six heures, et le terrain sera un chaos total !'::text),
(352736,39193,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar altı saattir ... ve alan tam bir kaos olacak!'::text,'dövüşüyor olacaklar'::text,'dövüşüyor olacaklar'::text,'dövüşecekler'::text,'Gün batımına kadar altı saattir dövüşüyor olacaklar ve alan tam bir kaos olacak!'::text),
(352737,39193,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napnyugtára már hat órája ..., és a mező totális káosz lesz!'::text,'harcolnak'::text,'harcolni fognak'::text,'harcolni fognak'::text,'Napnyugtára már hat órája harcolnak, és a mező totális káosz lesz!'::text),
(339321,37703,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, ich hab gehört, die Fans ... jeden Platz besetzt, bevor der Angriff überhaupt anfing.'::text,'hatten'::text,'haben'::text,'besetzen'::text,'Girl, ich hab gehört, die Fans hatten jeden Platz besetzt, bevor der Angriff überhaupt anfing.'::text),
(339325,37703,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що фанати ... всі місця ще до того, як атака взагалі почалася.'::text,'зайняли'::text,'зайняли'::text,'займають'::text,'Подруго, я чула, що фанати зайняли всі місця ще до того, як атака взагалі почалася.'::text),
(339324,37703,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me han dicho que los fans ... todos los asientos antes de que empezara la carga.'::text,'habían llenado'::text,'han llenado'::text,'llenan'::text,'Tía, me han dicho que los fans habían llenado todos los asientos antes de que empezara la carga.'::text),
(339323,37703,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il paraît que les fans ... toutes les places avant même le début de la charge.'::text,'avaient rempli'::text,'ont rempli'::text,'remplissent'::text,'Meuf, il paraît que les fans avaient rempli toutes les places avant même le début de la charge.'::text),
(339326,37703,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre hücum başlamadan önce taraftarlar her koltuğu ...'::text,'doldurmuştu'::text,'doldurdu'::text,'dolduruyor'::text,'Kızım, duyduğuma göre hücum başlamadan önce taraftarlar her koltuğu doldurmuştu.'::text),
(339327,37703,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy a szurkolók minden helyet ..., mielőtt a roham egyáltalán elkezdődött.'::text,'elfoglaltak'::text,'elfoglaltak'::text,'elfoglalnak'::text,'Csajszi, azt hallottam, hogy a szurkolók minden helyet elfoglaltak, mielőtt a roham egyáltalán elkezdődött.'::text),
(339330,37704,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Schildwall hält, ... der Angriff die feindliche Linie.'::text,'durchbricht'::text,'würde durchbrechen'::text,'durchbrach'::text,'Wenn der Schildwall hält, durchbricht der Angriff die feindliche Linie.'::text),
(339334,37704,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо стіна щитів витримає, атака ... ворожу лінію.'::text,'прорве'::text,'прорвала б'::text,'прорвала'::text,'Якщо стіна щитів витримає, атака прорве ворожу лінію.'::text),
(339333,37704,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el muro de escudos aguanta, la carga ... la línea enemiga.'::text,'romperá'::text,'rompería'::text,'rompió'::text,'Si el muro de escudos aguanta, la carga romperá la línea enemiga.'::text),
(339332,37704,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le mur de boucliers tient, la charge ... la ligne ennemie.'::text,'brisera'::text,'briserait'::text,'a brisé'::text,'Si le mur de boucliers tient, la charge brisera la ligne ennemie.'::text),
(339335,37704,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalkan duvarı dayanırsa hücum düşman hattını ...'::text,'yaracak'::text,'yarardı'::text,'yardı'::text,'Kalkan duvarı dayanırsa hücum düşman hattını yaracak.'::text),
(339336,37704,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a pajzsfal kitart, a roham ... az ellenséges vonalat.'::text,'áttöri'::text,'áttörné'::text,'áttörte'::text,'Ha a pajzsfal kitart, a roham áttöri az ellenséges vonalat.'::text),
(339339,37705,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Krieger langsamer liefen, ... ihr Angriff weniger furchteinflößend aus.'::text,'sähe'::text,'sieht'::text,'sieht'::text,'Wenn die Krieger langsamer liefen, sähe ihr Angriff weniger furchteinflößend aus.'::text),
(339343,37705,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби воїни бігли повільніше, їхня атака ... менш страшною.'::text,'виглядала б'::text,'виглядатиме'::text,'виглядає'::text,'Якби воїни бігли повільніше, їхня атака виглядала б менш страшною.'::text),
(339342,37705,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si los guerreros corrieran más despacio, su carga ... menos aterradora.'::text,'parecería'::text,'parecerá'::text,'parece'::text,'Si los guerreros corrieran más despacio, su carga parecería menos aterradora.'::text),
(339341,37705,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les guerriers couraient moins vite, leur charge ... moins effrayante.'::text,'paraîtrait'::text,'paraîtra'::text,'paraît'::text,'Si les guerriers couraient moins vite, leur charge paraîtrait moins effrayante.'::text),
(339344,37705,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Savaşçılar daha yavaş koşsa hücumları daha az korkutucu ...'::text,'görünürdü'::text,'görünecek'::text,'görünüyor'::text,'Savaşçılar daha yavaş koşsa hücumları daha az korkutucu görünürdü.'::text),
(339345,37705,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a harcosok lassabban futnának, a rohamuk kevésbé ... ijesztőnek.'::text,'tűnne'::text,'fog tűnni'::text,'tűnik'::text,'Ha a harcosok lassabban futnának, a rohamuk kevésbé tűnne ijesztőnek.'::text),
(339348,37706,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Angriff ... vom rotbärtigen Krieger an der Spitze angeführt.'::text,'wurde'::text,'führte'::text,'führt'::text,'Der Angriff wurde vom rotbärtigen Krieger an der Spitze angeführt.'::text),
(339352,37706,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Атаку ... рудобородий воїн на чолі.'::text,'вів'::text,'вів'::text,'веде'::text,'Атаку вів рудобородий воїн на чолі.'::text),
(339351,37706,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La carga ... por el guerrero de barba pelirroja al frente.'::text,'fue dirigida'::text,'dirigió'::text,'está dirigiendo'::text,'La carga fue dirigida por el guerrero de barba pelirroja al frente.'::text),
(339350,37706,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La charge ... par le guerrier à la barbe rousse en tête.'::text,'a été menée'::text,'a mené'::text,'mène'::text,'La charge a été menée par le guerrier à la barbe rousse en tête.'::text),
(339353,37706,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hücum öndeki kızıl sakallı savaşçı tarafından ...'::text,'yönetildi'::text,'yönetti'::text,'yönetiyor'::text,'Hücum öndeki kızıl sakallı savaşçı tarafından yönetildi.'::text),
(339354,37706,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rohamot az élen álló vörös szakállú harcos ...'::text,'vezette'::text,'vezették'::text,'vezeti'::text,'A rohamot az élen álló vörös szakállú harcos vezette.'::text),
(339357,37707,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die ganze Reihe ... den Angriff im selben Moment.'::text,'startete'::text,'wurde gestartet'::text,'startend'::text,'Die ganze Reihe startete den Angriff im selben Moment.'::text),
(339361,37707,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уся шеренга ... атаку в ту саму мить.'::text,'почала'::text,'була почата'::text,'починаючи'::text,'Уся шеренга почала атаку в ту саму мить.'::text),
(339360,37707,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toda la fila ... la carga en el mismo momento.'::text,'inició'::text,'fue iniciada'::text,'iniciando'::text,'Toda la fila inició la carga en el mismo momento.'::text),
(339359,37707,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toute la ligne ... la charge au même moment.'::text,'a lancé'::text,'a été lancée'::text,'lançant'::text,'Toute la ligne a lancé la charge au même moment.'::text),
(339362,37707,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün sıra hücumu aynı anda ...'::text,'başlattı'::text,'başlatıldı'::text,'başlatarak'::text,'Bütün sıra hücumu aynı anda başlattı.'::text),
(339363,37707,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egész sor ugyanabban a pillanatban ... a rohamot.'::text,'elindította'::text,'el lett indítva'::text,'elindítva'::text,'Az egész sor ugyanabban a pillanatban elindította a rohamot.'::text),
(339366,37708,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Menge jubelt, also ... der Angriff gut laufen.'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Die Menge jubelt, also muss der Angriff gut laufen.'::text),
(339370,37708,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Натовп радіє, тож атака ... йде добре.'::text,'напевно'::text,'можливо'::text,'точно не'::text,'Натовп радіє, тож атака напевно йде добре.'::text),
(339369,37708,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La multitud está aclamando, así que la carga ... estar yendo bien.'::text,'debe de'::text,'podría'::text,'no puede'::text,'La multitud está aclamando, así que la carga debe de estar yendo bien.'::text),
(339368,37708,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La foule acclame, donc la charge ... bien se passer.'::text,'doit'::text,'pourrait'::text,'ne peut pas'::text,'La foule acclame, donc la charge doit bien se passer.'::text),
(339371,37708,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalabalık tezahürat yapıyor, demek ki hücum iyi gidiyor ...'::text,'olmalı'::text,'olabilir'::text,'olamaz'::text,'Kalabalık tezahürat yapıyor, demek ki hücum iyi gidiyor olmalı.'::text),
(339372,37708,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tömeg ujjong, szóval a roham ... jól halad.'::text,'biztosan'::text,'talán'::text,'nem lehet, hogy'::text,'A tömeg ujjong, szóval a roham biztosan jól halad.'::text),
(339375,37709,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Angriff, ... typischerweise auf einen Schildwall folgt, erfordert präzises Timing.'::text,'der'::text,'wer'::text,'dessen'::text,'Der Angriff, der typischerweise auf einen Schildwall folgt, erfordert präzises Timing.'::text),
(339379,37709,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Атака, ... зазвичай іде після стіни щитів, потребує точного таймінгу.'::text,'яка'::text,'хто'::text,'чия'::text,'Атака, яка зазвичай іде після стіни щитів, потребує точного таймінгу.'::text),
(339378,37709,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La carga, ... típicamente sigue a un muro de escudos, requiere una sincronización precisa.'::text,'que'::text,'quien'::text,'cuya'::text,'La carga, que típicamente sigue a un muro de escudos, requiere una sincronización precisa.'::text),
(339377,37709,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La charge, ... suit typiquement un mur de boucliers, exige un timing précis.'::text,'qui'::text,'qui'::text,'dont'::text,'La charge, qui suit typiquement un mur de boucliers, exige un timing précis.'::text),
(339380,37709,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tipik olarak bir kalkan duvarının ardından gelen hücum kesin bir zamanlama gerektirir.'::text,''::text,NULL::text,NULL::text,'Tipik olarak bir kalkan duvarının ardından gelen hücum kesin bir zamanlama gerektirir.'::text),
(339381,37709,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A roham, ... jellemzően egy pajzsfalat követ, pontos időzítést igényel.'::text,'amely'::text,'aki'::text,'amelynek a'::text,'A roham, amely jellemzően egy pajzsfalat követ, pontos időzítést igényel.'::text),
(339393,37711,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeden Sommer ... sich die Krieger zum Angriff auf, und die Menge schrie!'::text,'stellten'::text,'stellten'::text,'waren gewohnt, sich aufzustellen'::text,'Jeden Sommer stellten sich die Krieger zum Angriff auf, und die Menge schrie!'::text),
(339397,37711,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щоліта воїни ... для атаки, а натовп кричав!'::text,'шикувалися'::text,'шикувалися'::text,'звикли шикуватися'::text,'Щоліта воїни шикувалися для атаки, а натовп кричав!'::text),
(339396,37711,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cada verano los guerreros ... para la carga, y la multitud gritaba!'::text,'se alineaban'::text,'solían alinearse'::text,'estaban acostumbrados a alinearse'::text,'¡Cada verano los guerreros se alineaban para la carga, y la multitud gritaba!'::text),
(339395,37711,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque été, les guerriers ... pour la charge, et la foule hurlait !'::text,'s''alignaient'::text,'avaient l''habitude de s''aligner'::text,'étaient habitués à s''aligner'::text,'Chaque été, les guerriers s''alignaient pour la charge, et la foule hurlait !'::text),
(339398,37711,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her yaz savaşçılar hücum için sıraya ..., kalabalık da çığlık atardı!'::text,'girerdi'::text,'girerdi'::text,'girmeye alışkındı'::text,'Her yaz savaşçılar hücum için sıraya girerdi, kalabalık da çığlık atardı!'::text),
(339399,37711,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden nyáron a harcosok ... a rohamhoz, a tömeg pedig sikoltozott!'::text,'felsorakoztak'::text,'felsorakoztak'::text,'hozzá voltak szokva, hogy felsorakozzanak'::text,'Minden nyáron a harcosok felsorakoztak a rohamhoz, a tömeg pedig sikoltozott!'::text),
(339402,37712,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er weigert sich, den Angriff ..., bevor der Schildwall steht. Sonst Chaos!'::text,'zu starten'::text,'starten'::text,'starten'::text,'Er weigert sich, den Angriff zu starten, bevor der Schildwall steht. Sonst Chaos!'::text),
(339406,37712,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він відмовляється ... атаку, поки стіна щитів не буде готова. Інакше хаос!'::text,'починати'::text,'починання'::text,'почати'::text,'Він відмовляється починати атаку, поки стіна щитів не буде готова. Інакше хаос!'::text),
(339405,37712,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se niega a ... la carga hasta que el muro de escudos esté listo. ¡Si no, caos!'::text,'iniciar'::text,'iniciando'::text,'iniciar'::text,'Se niega a iniciar la carga hasta que el muro de escudos esté listo. ¡Si no, caos!'::text),
(339404,37712,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il refuse de ... la charge tant que le mur de boucliers n''est pas prêt. Sinon, c''est le chaos !'::text,'lancer'::text,'lançant'::text,'lancer'::text,'Il refuse de lancer la charge tant que le mur de boucliers n''est pas prêt. Sinon, c''est le chaos !'::text),
(339407,37712,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalkan duvarı hazır olana kadar hücumu ... reddediyor. Yoksa kaos!'::text,'başlatmayı'::text,'başlatmak'::text,'başlat'::text,'Kalkan duvarı hazır olana kadar hücumu başlatmayı reddediyor. Yoksa kaos!'::text),
(339408,37712,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hajlandó ... a rohamot, amíg a pajzsfal nincs kész. Különben káosz!'::text,'elindítani'::text,'elindítva'::text,'elindít'::text,'Nem hajlandó elindítani a rohamot, amíg a pajzsfal nincs kész. Különben káosz!'::text),
(386958,42996,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich lüg nicht, du ... nicht so laut geseufzt, wenn der Flug pünktlich gestartet wäre.'::text,'hättest'::text,'wirst'::text,'hast'::text,'Ich lüg nicht, du hättest nicht so laut geseufzt, wenn der Flug pünktlich gestartet wäre.'::text),
(386962,42996,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти ... так голосно, якби рейс вилетів вчасно.'::text,'не зітхала б'::text,'не зітхатимеш'::text,'не зітхала'::text,'Не буду брехати, ти не зітхала б так голосно, якби рейс вилетів вчасно.'::text),
(386961,42996,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, no ... tan fuerte si el vuelo hubiera salido a tiempo.'::text,'habrías suspirado'::text,'suspirarás'::text,'suspiraste'::text,'No voy a mentir, no habrías suspirado tan fuerte si el vuelo hubiera salido a tiempo.'::text),
(386960,42996,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ... aussi fort si le vol était parti à l''heure.'::text,'n''aurais pas soupiré'::text,'ne soupireras pas'::text,'n''as pas soupiré'::text,'Je vais pas mentir, tu n''aurais pas soupiré aussi fort si le vol était parti à l''heure.'::text),
(386963,42996,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, uçuş zamanında kalksaydı bu kadar yüksek sesle ...'::text,'iç çekmezdin'::text,'iç çekmeyeceksin'::text,'iç çekmedin'::text,'Yalan yok, uçuş zamanında kalksaydı bu kadar yüksek sesle iç çekmezdin.'::text),
(386964,42996,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fogok hazudni, nem ... ekkorát, ha a járat időben indult volna.'::text,'sóhajtottál volna'::text,'fogsz sóhajtani'::text,'sóhajtottál'::text,'Nem fogok hazudni, nem sóhajtottál volna ekkorát, ha a járat időben indult volna.'::text),
(386967,42997,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre der Flug pünktlich gestartet, ... sie jetzt nicht an die Decke seufzen. Lustige Reise, ganz klar.'::text,'würde'::text,'hätte'::text,'wird'::text,'Wäre der Flug pünktlich gestartet, würde sie jetzt nicht an die Decke seufzen. Lustige Reise, ganz klar.'::text),
(386971,42997,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби рейс вилетів вчасно, вона зараз ... у стелю. Весела поїздка, ясна річ.'::text,'не зітхала б'::text,'не зітхала б'::text,'не зітхатиме'::text,'Якби рейс вилетів вчасно, вона зараз не зітхала б у стелю. Весела поїздка, ясна річ.'::text),
(386970,42997,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el vuelo hubiera salido a tiempo, ahora no ... suspirando al techo. Un viaje divertido, está claro.'::text,'estaría'::text,'habría estado'::text,'estará'::text,'Si el vuelo hubiera salido a tiempo, ahora no estaría suspirando al techo. Un viaje divertido, está claro.'::text),
(386969,42997,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le vol était parti à l''heure, elle ... en train de soupirer au plafond maintenant. Voyage marrant, clairement.'::text,'ne serait pas'::text,'n''aurait pas été'::text,'ne sera pas'::text,'Si le vol était parti à l''heure, elle ne serait pas en train de soupirer au plafond maintenant. Voyage marrant, clairement.'::text),
(386972,42997,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uçuş zamanında kalksaydı şimdi tavana bakıp iç ... – eğlenceli bir gezi, belli ki.'::text,'çekiyor olmazdı'::text,'çekmiş olmazdı'::text,'çekiyor olmayacak'::text,'Uçuş zamanında kalksaydı şimdi tavana bakıp iç çekiyor olmazdı – eğlenceli bir gezi, belli ki.'::text),
(386973,42997,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a járat időben indult volna, most nem ... a plafonra. Vicces út, nyilván.'::text,'sóhajtozna'::text,'sóhajtozott volna'::text,'fog sóhajtozni'::text,'Ha a járat időben indult volna, most nem sóhajtozna a plafonra. Vicces út, nyilván.'::text),
(386976,42998,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr erster Seufzer soll am nächsten Gate gehört ... – sehr leise, natürlich.'::text,'worden sein'::text,'worden sein'::text,'worden sein'::text,'Ihr erster Seufzer soll am nächsten Gate gehört worden sein – sehr leise, natürlich.'::text),
(386980,42998,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, її перше зітхання ... чути аж біля сусіднього гейта. Дуже тихе, звісно.'::text,'було'::text,'було'::text,'було'::text,'Кажуть, її перше зітхання було чути аж біля сусіднього гейта. Дуже тихе, звісно.'::text),
(386979,42998,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dicen que su primer suspiro ... en la puerta de al lado. Muy silencioso, obviamente.'::text,'se oyó'::text,'se oyó'::text,'se oyó'::text,'Dicen que su primer suspiro se oyó en la puerta de al lado. Muy silencioso, obviamente.'::text),
(386978,42998,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son premier soupir aurait ... entendu jusqu''à la porte voisine. Très discret, évidemment.'::text,'été'::text,'été'::text,'été'::text,'Son premier soupir aurait été entendu jusqu''à la porte voisine. Très discret, évidemment.'::text),
(386981,42998,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Söylenene göre ilk iç çekişi yan kapıdan bile ... – çok sessiz, tabii ki.'::text,'duyulmuş'::text,'duyulmuş'::text,'duyulmuş'::text,'Söylenene göre ilk iç çekişi yan kapıdan bile duyulmuş – çok sessiz, tabii ki.'::text),
(386982,42998,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Állítólag az első sóhaját még a szomszéd kapunál is ... – nagyon halk, nyilván.'::text,'hallani lehetett'::text,'hallani lehetett'::text,'hallani lehetett'::text,'Állítólag az első sóhaját még a szomszéd kapunál is hallani lehetett – nagyon halk, nyilván.'::text),
(386985,42999,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie gab zu, fünfmal an die Decke ... zu haben. Eine entspannte Reisende, natürlich.'::text,'geseufzt'::text,'seufzen'::text,'geseufzt'::text,'Sie gab zu, fünfmal an die Decke geseufzt zu haben. Eine entspannte Reisende, natürlich.'::text),
(386989,42999,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона визнала, що ... у стелю п’ять разів. Спокійна мандрівниця, звісно.'::text,'зітхнула'::text,'зітхнути'::text,'зітхнула'::text,'Вона визнала, що зітхнула у стелю п’ять разів. Спокійна мандрівниця, звісно.'::text),
(386988,42999,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Admitió ... cinco veces mirando al techo. Una viajera tranquila, obviamente.'::text,'haber suspirado'::text,'suspirar'::text,'suspiró'::text,'Admitió haber suspirado cinco veces mirando al techo. Una viajera tranquila, obviamente.'::text),
(386987,42999,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a avoué ... cinq fois au plafond. Une voyageuse calme, évidemment.'::text,'avoir soupiré'::text,'soupirer'::text,'a soupiré'::text,'Elle a avoué avoir soupiré cinq fois au plafond. Une voyageuse calme, évidemment.'::text),
(386990,42999,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavana bakıp beş kez ... itiraf etti. Sakin bir yolcu, tabii ki.'::text,'iç çektiğini'::text,'iç çekmeyi'::text,'iç çekti'::text,'Tavana bakıp beş kez iç çektiğini itiraf etti. Sakin bir yolcu, tabii ki.'::text),
(386991,42999,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beismerte, hogy ötször ... a plafonra. Nyugodt utazó, nyilván.'::text,'sóhajtott fel'::text,'felsóhajtani'::text,'felsóhajtott'::text,'Beismerte, hogy ötször sóhajtott fel a plafonra. Nyugodt utazó, nyilván.'::text),
(386994,43000,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... einen früheren Flug buchen sollen! Jetzt seufzt sie für immer an diesem Gate!'::text,'hätte'::text,'muss wohl'::text,'könnte'::text,'Sie hätte einen früheren Flug buchen sollen! Jetzt seufzt sie für immer an diesem Gate!'::text),
(386998,43000,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... раніший рейс! Тепер вона зітхатиме біля цього гейта вічно!'::text,'мала забронювати'::text,'мабуть, забронювала'::text,'могла забронювати'::text,'Вона мала забронювати раніший рейс! Тепер вона зітхатиме біля цього гейта вічно!'::text),
(386997,43000,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... un vuelo anterior! ¡Ahora va a suspirar en esta puerta para siempre!'::text,'Debería haber reservado'::text,'Debe de haber reservado'::text,'Podía reservar'::text,'¡Debería haber reservado un vuelo anterior! ¡Ahora va a suspirar en esta puerta para siempre!'::text),
(386996,43000,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... un vol plus tôt ! Maintenant, elle va soupirer à cette porte pour toujours !'::text,'aurait dû réserver'::text,'a dû réserver'::text,'pouvait réserver'::text,'Elle aurait dû réserver un vol plus tôt ! Maintenant, elle va soupirer à cette porte pour toujours !'::text),
(386999,43000,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha erken bir uçuşa ...! Şimdi bu kapıda sonsuza kadar iç çekecek!'::text,'rezervasyon yaptırmalıydı'::text,'rezervasyon yaptırmış olmalı'::text,'rezervasyon yaptırabilirdi'::text,'Daha erken bir uçuşa rezervasyon yaptırmalıydı! Şimdi bu kapıda sonsuza kadar iç çekecek!'::text),
(387000,43000,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy korábbi járatot ...! Most örökké itt fog sóhajtozni ennél a kapunál!'::text,'kellett volna foglalnia'::text,'biztos foglalt'::text,'foglalhatott'::text,'Egy korábbi járatot kellett volna foglalnia! Most örökké itt fog sóhajtozni ennél a kapunál!'::text),
(387012,43002,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, ich hab gehört, sie hat eine Freundin ihren Flug ... lassen, während sie am Gate geseufzt hat.'::text,'checken'::text,'checken'::text,'checken'::text,'Girl, ich hab gehört, sie hat eine Freundin ihren Flug checken lassen, während sie am Gate geseufzt hat.'::text),
(387016,43002,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, вона попросила подругу ... її рейс, поки сама зітхала біля гейта.'::text,'перевірити'::text,'перевірити'::text,'перевіряючи'::text,'Подруго, я чула, вона попросила подругу перевірити її рейс, поки сама зітхала біля гейта.'::text),
(387015,43002,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me han dicho que consiguió que una amiga ... su vuelo mientras ella suspiraba en la puerta.'::text,'revisara'::text,'revisar'::text,'revisando'::text,'Tía, me han dicho que consiguió que una amiga revisara su vuelo mientras ella suspiraba en la puerta.'::text),
(387014,43002,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il paraît qu''elle a demandé à une amie de ... son vol pendant qu''elle soupirait à la porte.'::text,'vérifier'::text,'vérifier'::text,'vérifiant'::text,'Meuf, il paraît qu''elle a demandé à une amie de vérifier son vol pendant qu''elle soupirait à la porte.'::text),
(387017,43002,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duydum ki kapıda iç çekerken uçuşunu bir arkadaşına ...'::text,'kontrol ettirmiş'::text,'kontrol ettirmiş'::text,'kontrol ederek'::text,'Kızım, duydum ki kapıda iç çekerken uçuşunu bir arkadaşına kontrol ettirmiş.'::text),
(387018,43002,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy ... egy barátnőjével a járatát, amíg ő a kapunál sóhajtozott.'::text,'ellenőriztette'::text,'ellenőriztette'::text,'ellenőrizve'::text,'Csajszi, azt hallottam, hogy ellenőriztette egy barátnőjével a járatát, amíg ő a kapunál sóhajtozott.'::text),
(387021,43003,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, sie hat mir gesagt, sie wünschte, der Flug ... pünktlich gestartet, sie hat die ganze Nacht geseufzt.'::text,'wäre'::text,'sei'::text,'würde'::text,'Hör mal, sie hat mir gesagt, sie wünschte, der Flug wäre pünktlich gestartet, sie hat die ganze Nacht geseufzt.'::text),
(387025,43003,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона сказала мені, що шкодує, що рейс не ... вчасно, вона зітхала всю ніч.'::text,'вилетів'::text,'вилетів'::text,'вилетить'::text,'Слухай, вона сказала мені, що шкодує, що рейс не вилетів вчасно, вона зітхала всю ніч.'::text),
(387024,43003,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que ojalá el vuelo ... a tiempo, se pasó toda la noche suspirando.'::text,'hubiera salido'::text,'saliera'::text,'saldría'::text,'Oye, me dijo que ojalá el vuelo hubiera salido a tiempo, se pasó toda la noche suspirando.'::text),
(387023,43003,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle m''a dit qu''elle aurait aimé que le vol ... à l''heure, elle a soupiré toute la nuit.'::text,'soit parti'::text,'parte'::text,'partirait'::text,'Écoute, elle m''a dit qu''elle aurait aimé que le vol soit parti à l''heure, elle a soupiré toute la nuit.'::text),
(387026,43003,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana dedi ki keşke uçuş zamanında ..., bütün gece iç çekmiş.'::text,'kalksaydı'::text,'kalktı'::text,'kalkardı'::text,'Dinle, bana dedi ki keşke uçuş zamanında kalksaydı, bütün gece iç çekmiş.'::text),
(387027,43003,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, bárcsak a járat időben ..., egész éjjel sóhajtozott.'::text,'indult volna'::text,'indulna'::text,'fog indulni'::text,'Figyelj, azt mondta, bárcsak a járat időben indult volna, egész éjjel sóhajtozott.'::text),
(387030,43004,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau, ... Flug Verspätung hat, seufzt und schaut wieder auf die Uhr.'::text,'deren'::text,'die'::text,'welche'::text,'Die Frau, deren Flug Verspätung hat, seufzt und schaut wieder auf die Uhr.'::text),
(387034,43004,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка, ... рейс затримується, зітхає і знову дивиться на годинник.'::text,'чий'::text,'яка'::text,'що'::text,'Жінка, чий рейс затримується, зітхає і знову дивиться на годинник.'::text),
(387033,43004,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer, ... vuelo se retrasa, suspira y vuelve a mirar el reloj.'::text,'cuyo'::text,'quien'::text,'que'::text,'La mujer, cuyo vuelo se retrasa, suspira y vuelve a mirar el reloj.'::text),
(387032,43004,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme, ... le vol est retardé, soupire et regarde encore sa montre.'::text,'dont'::text,'qui'::text,'laquelle'::text,'La femme, dont le vol est retardé, soupire et regarde encore sa montre.'::text),
(387035,43004,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... uçuşu rötar yapan kadın iç çekip yine saatine bakıyor.'::text,''::text,NULL::text,NULL::text,'Uçuşu rötar yapan kadın iç çekip yine saatine bakıyor.'::text),
(387036,43004,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő, ... a járata késik, felsóhajt, és újra az órájára néz.'::text,'akinek a'::text,'aki'::text,'ami'::text,'A nő, akinek a a járata késik, felsóhajt, és újra az órájára néz.'::text),
(387039,43005,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie seufzte laut ... der langen Verspätung am Gate.'::text,'wegen'::text,'obwohl'::text,'für den Fall'::text,'Sie seufzte laut wegen der langen Verspätung am Gate.'::text),
(387043,43005,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона голосно зітхнула ... довгу затримку біля гейта.'::text,'через'::text,'хоча'::text,'на випадок'::text,'Вона голосно зітхнула через довгу затримку біля гейта.'::text),
(387042,43005,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Suspiró fuerte ... el largo retraso en la puerta.'::text,'por'::text,'aunque'::text,'por si'::text,'Suspiró fuerte por el largo retraso en la puerta.'::text),
(387041,43005,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a soupiré bruyamment ... du long retard à la porte.'::text,'à cause'::text,'bien que'::text,'au cas où'::text,'Elle a soupiré bruyamment à cause du long retard à la porte.'::text),
(387044,43005,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kapıdaki uzun rötar ... yüksek sesle iç çekti.'::text,'yüzünden'::text,'rağmen'::text,'diye'::text,'Kapıdaki uzun rötar yüzünden yüksek sesle iç çekti.'::text),
(387045,43005,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hangosan felsóhajtott a kapunál lévő hosszú késés ...'::text,'miatt'::text,'bár'::text,'arra az esetre'::text,'Hangosan felsóhajtott a kapunál lévő hosszú késés miatt.'::text),
(401070,44564,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... gerade zum Wählen nach vorne, als die ganze Schlange anfing, dich anzulächeln.'::text,'liefst'::text,'liefst'::text,'bist gelaufen'::text,'Ehrlich, du liefst gerade zum Wählen nach vorne, als die ganze Schlange anfing, dich anzulächeln.'::text),
(401074,44564,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... голосувати, коли вся черга почала тобі усміхатися.'::text,'ішла'::text,'підійшла'::text,'підійшла'::text,'Чесно, ти ішла голосувати, коли вся черга почала тобі усміхатися.'::text),
(401073,44564,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ... a votar cuando toda la cola empezó a sonreírte.'::text,'ibas'::text,'fuiste'::text,'has ido'::text,'La verdad, ibas a votar cuando toda la cola empezó a sonreírte.'::text),
(401072,44564,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... pour voter quand toute la file a commencé à te sourire.'::text,'t''avançais'::text,'t''es avancée'::text,'t''es avancée'::text,'Franchement, tu t''avançais pour voter quand toute la file a commencé à te sourire.'::text),
(401075,44564,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen oy vermeye ... ki bütün sıra sana gülümsemeye başladı.'::text,'yürüyordun'::text,'yürüdün'::text,'yürüdün'::text,'Açıkçası sen oy vermeye yürüyordun ki bütün sıra sana gülümsemeye başladı.'::text),
(401076,44564,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, épp szavazni ..., amikor az egész sor mosolyogni kezdett rád.'::text,'mentél'::text,'mentél'::text,'mentél'::text,'Őszintén, épp szavazni mentél, amikor az egész sor mosolyogni kezdett rád.'::text),
(401088,44566,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ihren Stimmzettel in die Urne und reckte die Faust in die Luft. Eine sehr schüchterne Wählerin, klar.'::text,'warf'::text,'warf gerade'::text,'hat geworfen'::text,'Sie warf ihren Stimmzettel in die Urne und reckte die Faust in die Luft. Eine sehr schüchterne Wählerin, klar.'::text),
(401092,44566,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... бюлетень в урну і вдарила кулаком у повітря. Дуже сором’язлива виборниця, ясна річ.'::text,'вкинула'::text,'вкидала'::text,'вкинула'::text,'Вона вкинула бюлетень в урну і вдарила кулаком у повітря. Дуже сором’язлива виборниця, ясна річ.'::text),
(401091,44566,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... su papeleta en la urna y lanzó un puñetazo al aire. Una votante muy tímida, claramente.'::text,'Metió'::text,'Estaba metiendo'::text,'Ha metido'::text,'Metió su papeleta en la urna y lanzó un puñetazo al aire. Una votante muy tímida, claramente.'::text),
(401090,44566,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... son bulletin dans l''urne et a brandi le poing. Une électrice très timide, clairement.'::text,'a glissé'::text,'glissait'::text,'a glissé'::text,'Elle a glissé son bulletin dans l''urne et a brandi le poing. Une électrice très timide, clairement.'::text),
(401093,44566,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oy pusulasını sandığa ... ve yumruğunu havaya kaldırdı. Çok utangaç bir seçmen, belli ki.'::text,'attı'::text,'atıyordu'::text,'attı'::text,'Oy pusulasını sandığa attı ve yumruğunu havaya kaldırdı. Çok utangaç bir seçmen, belli ki.'::text),
(401094,44566,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a szavazócédulát az urnába, és a levegőbe bokszolt. Nagyon félénk szavazó, nyilván.'::text,'Bedobta'::text,'Éppen dobta be'::text,'Bedobta'::text,'Bedobta a szavazócédulát az urnába, és a levegőbe bokszolt. Nagyon félénk szavazó, nyilván.'::text),
(401097,44567,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie hat schon ..., und sie ist irgendwie voll gehypt deswegen.'::text,'gewählt'::text,'gewählt'::text,'wählt gerade'::text,'Bro, sie hat schon gewählt, und sie ist irgendwie voll gehypt deswegen.'::text),
(401101,44567,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона вже ..., і вона від цього типу в захваті.'::text,'проголосувала'::text,'голосувала'::text,'голосує'::text,'Бро, вона вже проголосувала, і вона від цього типу в захваті.'::text),
(401100,44567,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ya ..., y está como súper emocionada.'::text,'ha votado'::text,'ha estado votando'::text,'está votando'::text,'Bro, ya ha votado, y está como súper emocionada.'::text),
(401099,44567,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, c''est bon, elle ..., et elle est grave hypée.'::text,'a voté'::text,'a voté'::text,'est en train de voter'::text,'Frérot, c''est bon, elle a voté, et elle est grave hypée.'::text),
(401102,44567,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o çoktan oyunu ..., bayağı da gaza gelmiş.'::text,'verdi'::text,'veriyor'::text,'veriyor'::text,'Kanka, o çoktan oyunu verdi, bayağı da gaza gelmiş.'::text),
(401103,44567,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, már ..., és elég fel van pörögve miatta.'::text,'szavazott'::text,'szavazott'::text,'szavaz'::text,'Tesó, már szavazott, és elég fel van pörögve miatta.'::text),
(401106,44568,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, als ich in die Turnhalle kam, hatte die halbe Stadt schon ..., ohne Witz.'::text,'gewählt'::text,'gewählt'::text,'wählt'::text,'Alter, als ich in die Turnhalle kam, hatte die halbe Stadt schon gewählt, ohne Witz.'::text),
(401110,44568,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, поки я дійшов до спортзалу, пів міста вже ..., без брехні.'::text,'проголосувало'::text,'проголосувало'::text,'голосує'::text,'Чувак, поки я дійшов до спортзалу, пів міста вже проголосувало, без брехні.'::text),
(401109,44568,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, cuando llegué al gimnasio, medio pueblo ya ..., sin mentir.'::text,'había votado'::text,'ha votado'::text,'vota'::text,'Tío, cuando llegué al gimnasio, medio pueblo ya había votado, sin mentir.'::text),
(401108,44568,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, quand je suis arrivé au gymnase, la moitié de la ville ... déjà voté, sans mentir.'::text,'avait'::text,'a'::text,'vote'::text,'Mec, quand je suis arrivé au gymnase, la moitié de la ville avait déjà voté, sans mentir.'::text),
(401111,44568,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ben spor salonuna varana kadar kasabanın yarısı çoktan oy ..., yalan yok.'::text,'vermişti'::text,'verdi'::text,'veriyor'::text,'Kanka, ben spor salonuna varana kadar kasabanın yarısı çoktan oy vermişti, yalan yok.'::text),
(401112,44568,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, mire a tornaterembe értem, a fél város már ..., komolyan.'::text,'szavazott'::text,'szavazott'::text,'szavaz'::text,'Haver, mire a tornaterembe értem, a fél város már szavazott, komolyan.'::text),
(401115,44569,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn alle in dieser Schlange wählen, ... die Wahlbeteiligung das 70-%-Ziel.'::text,'erreicht'::text,'würde erreichen'::text,'erreichte'::text,'Wenn alle in dieser Schlange wählen, erreicht die Wahlbeteiligung das 70-%-Ziel.'::text),
(401119,44569,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо кожен у цій черзі проголосує, явка ... цілі у 70 %.'::text,'досягне'::text,'досягла б'::text,'досягла'::text,'Якщо кожен у цій черзі проголосує, явка досягне цілі у 70 %.'::text),
(401118,44569,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si todos los de esta cola votan, la participación ... el objetivo del 70 %.'::text,'alcanzará'::text,'alcanzaría'::text,'alcanzó'::text,'Si todos los de esta cola votan, la participación alcanzará el objetivo del 70 %.'::text),
(401117,44569,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tout le monde dans cette file vote, la participation ... l''objectif de 70 %.'::text,'atteindra'::text,'atteindrait'::text,'a atteint'::text,'Si tout le monde dans cette file vote, la participation atteindra l''objectif de 70 %.'::text),
(401120,44569,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sıradaki herkes oy verirse katılım yüzde 70 hedefine ...'::text,'ulaşacak'::text,'ulaşırdı'::text,'ulaştı'::text,'Bu sıradaki herkes oy verirse katılım yüzde 70 hedefine ulaşacak.'::text),
(401121,44569,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha mindenki szavaz ebben a sorban, a részvétel ... a 70%-os célt.'::text,'eléri'::text,'elérné'::text,'elérte'::text,'Ha mindenki szavaz ebben a sorban, a részvétel eléri a 70%-os célt.'::text),
(401124,44570,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Turnhalle mehr Wahlkabinen hätte, ... die Leute viel schneller wählen.'::text,'würden'::text,'werden'::text,'wählten'::text,'Wenn die Turnhalle mehr Wahlkabinen hätte, würden die Leute viel schneller wählen.'::text),
(401128,44570,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби в спортзалі було більше кабінок для голосування, люди ... набагато швидше.'::text,'голосували б'::text,'голосуватимуть'::text,'голосували'::text,'Якби в спортзалі було більше кабінок для голосування, люди голосували б набагато швидше.'::text),
(401127,44570,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el gimnasio tuviera más cabinas de votación, la gente ... mucho más rápido.'::text,'votaría'::text,'votará'::text,'votó'::text,'Si el gimnasio tuviera más cabinas de votación, la gente votaría mucho más rápido.'::text),
(401126,44570,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le gymnase avait plus d''isoloirs, les gens ... beaucoup plus vite.'::text,'voteraient'::text,'voteront'::text,'ont voté'::text,'Si le gymnase avait plus d''isoloirs, les gens voteraient beaucoup plus vite.'::text),
(401129,44570,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Spor salonunda daha fazla oy kabini olsa insanlar çok daha hızlı oy ...'::text,'verirdi'::text,'verecek'::text,'verdi'::text,'Spor salonunda daha fazla oy kabini olsa insanlar çok daha hızlı oy verirdi.'::text),
(401130,44570,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a tornateremben több szavazófülke lenne, az emberek sokkal gyorsabban ...'::text,'szavaznának'::text,'fognak szavazni'::text,'szavaztak'::text,'Ha a tornateremben több szavazófülke lenne, az emberek sokkal gyorsabban szavaznának.'::text),
(401133,44571,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie aufwachte, wusste sie, dass sie vor der Arbeit wählen ...'::text,'würde'::text,'wird'::text,'wählt'::text,'Als sie aufwachte, wusste sie, dass sie vor der Arbeit wählen würde.'::text),
(401137,44571,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вона прокинулася, то знала, що ... перед роботою.'::text,'проголосує'::text,'проголосує'::text,'голосує'::text,'Коли вона прокинулася, то знала, що проголосує перед роботою.'::text),
(401136,44571,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando se despertó, sabía que ... antes del trabajo.'::text,'votaría'::text,'votará'::text,'está votando'::text,'Cuando se despertó, sabía que votaría antes del trabajo.'::text),
(401135,44571,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand elle s''est réveillée, elle savait qu''elle ... avant le travail.'::text,'voterait'::text,'votera'::text,'vote'::text,'Quand elle s''est réveillée, elle savait qu''elle voterait avant le travail.'::text),
(401138,44571,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uyandığında işten önce oy ... biliyordu.'::text,'vereceğini'::text,'vereceğini'::text,'verdiğini'::text,'Uyandığında işten önce oy vereceğini biliyordu.'::text),
(401139,44571,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor felébredt, tudta, hogy munka előtt ...'::text,'szavazni fog'::text,'szavazni fog'::text,'szavaz'::text,'Amikor felébredt, tudta, hogy munka előtt szavazni fog.'::text),
(401142,44572,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade jetzt ... die Frau im gelben Regenmantel in der Schulturnhalle.'::text,'wählt'::text,'wählt'::text,'hat gewählt'::text,'Gerade jetzt wählt die Frau im gelben Regenmantel in der Schulturnhalle.'::text),
(401146,44572,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто зараз жінка в жовтому дощовику ... у шкільному спортзалі.'::text,'голосує'::text,'голосує'::text,'проголосувала'::text,'Просто зараз жінка в жовтому дощовику голосує у шкільному спортзалі.'::text),
(401145,44572,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo, la mujer del chubasquero amarillo ... en el gimnasio del colegio.'::text,'está votando'::text,'vota'::text,'ha votado'::text,'Ahora mismo, la mujer del chubasquero amarillo está votando en el gimnasio del colegio.'::text),
(401144,44572,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, la femme en imperméable jaune ... dans le gymnase de l''école.'::text,'est en train de voter'::text,'vote'::text,'a voté'::text,'En ce moment, la femme en imperméable jaune est en train de voter dans le gymnase de l''école.'::text),
(401147,44572,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda sarı yağmurluklu kadın okulun spor salonunda oy ...'::text,'veriyor'::text,'verir'::text,'verdi'::text,'Şu anda sarı yağmurluklu kadın okulun spor salonunda oy veriyor.'::text),
(401148,44572,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éppen most a sárga esőkabátos nő ... az iskolai tornateremben.'::text,'szavaz'::text,'szavaz'::text,'szavazott'::text,'Éppen most a sárga esőkabátos nő szavaz az iskolai tornateremben.'::text),
(401160,44574,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis du diese Turnhalle verlässt, wirst du zum ersten Mal ... – Respekt.'::text,'gewählt haben'::text,'wählen'::text,'wählst'::text,'Bis du diese Turnhalle verlässt, wirst du zum ersten Mal gewählt haben – Respekt.'::text),
(401164,44574,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки ти вийдеш із цього спортзалу, ти ... вперше. Респект.'::text,'проголосуєш'::text,'голосуватимеш'::text,'голосуєш'::text,'Поки ти вийдеш із цього спортзалу, ти проголосуєш вперше. Респект.'::text),
(401163,44574,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando salgas de este gimnasio, ... por primera vez. Respeto.'::text,'habrás votado'::text,'votarás'::text,'estás votando'::text,'Para cuando salgas de este gimnasio, habrás votado por primera vez. Respeto.'::text),
(401162,44574,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici à ce que tu quittes ce gymnase, tu ... pour la première fois. Respect.'::text,'auras voté'::text,'voteras'::text,'votes'::text,'D''ici à ce que tu quittes ce gymnase, tu auras voté pour la première fois. Respect.'::text),
(401165,44574,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu spor salonundan çıkana kadar ilk kez oy ... – saygılar.'::text,'vermiş olacaksın'::text,'vereceksin'::text,'veriyorsun'::text,'Bu spor salonundan çıkana kadar ilk kez oy vermiş olacaksın – saygılar.'::text),
(401166,44574,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire elhagyod ezt a tornatermet, ... életedben először. Respekt.'::text,'már szavaztál'::text,'szavazni fogsz'::text,'szavazol'::text,'Mire elhagyod ezt a tornatermet, már szavaztál életedben először. Respekt.'::text),
(346791,38533,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er entwarf gerade das Dach, als er ..., ein rundes Loch hinzuzufügen.'::text,'beschloss'::text,'gerade beschloss'::text,'beschlossen hat'::text,'Er entwarf gerade das Dach, als er beschloss, ein rundes Loch hinzuzufügen.'::text),
(346795,38533,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він проєктував дах, коли ... додати круглий отвір.'::text,'вирішив'::text,'вирішував'::text,'вирішив'::text,'Він проєктував дах, коли вирішив додати круглий отвір.'::text),
(346794,38533,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estaba diseñando el tejado cuando ... añadir un agujero redondo.'::text,'decidió'::text,'estaba decidiendo'::text,'ha decidido'::text,'Estaba diseñando el tejado cuando decidió añadir un agujero redondo.'::text),
(346793,38533,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il dessinait le toit quand il ... d''ajouter un trou rond.'::text,'a décidé'::text,'décidait'::text,'a décidé'::text,'Il dessinait le toit quand il a décidé d''ajouter un trou rond.'::text),
(346796,38533,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çatıyı tasarlarken yuvarlak bir delik eklemeye ...'::text,'karar verdi'::text,'karar veriyordu'::text,'karar verdi'::text,'Çatıyı tasarlarken yuvarlak bir delik eklemeye karar verdi.'::text),
(346797,38533,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éppen a tetőt tervezte, amikor ..., hogy tesz rá egy kerek lyukat.'::text,'elhatározta'::text,'határozta el éppen'::text,'elhatározta'::text,'Éppen a tetőt tervezte, amikor elhatározta, hogy tesz rá egy kerek lyukat.'::text),
(346800,38534,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seit Jahren Vogelhäuser in dieser Werkstatt.'::text,'entwirft'::text,'entwirft gerade'::text,'entwirft'::text,'Er entwirft seit Jahren Vogelhäuser in dieser Werkstatt.'::text),
(346804,38534,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... шпаківні в цій майстерні вже багато років.'::text,'проєктує'::text,'проєктує'::text,'проєктує'::text,'Він проєктує шпаківні в цій майстерні вже багато років.'::text),
(346803,38534,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... años diseñando casitas para pájaros en este taller.'::text,'Lleva'::text,'Está'::text,'Diseña'::text,'Lleva años diseñando casitas para pájaros en este taller.'::text),
(346802,38534,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... des nichoirs dans cet atelier depuis des années.'::text,'conçoit'::text,'est en train de concevoir'::text,'conçoit'::text,'Il conçoit des nichoirs dans cet atelier depuis des années.'::text),
(346805,38534,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yıllardır bu atölyede kuş evleri ...'::text,'tasarlıyor'::text,'tasarlıyor'::text,'tasarlar'::text,'Yıllardır bu atölyede kuş evleri tasarlıyor.'::text),
(346806,38534,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évek óta ... madárodúkat ebben a műhelyben.'::text,'tervez'::text,'tervez éppen'::text,'tervez'::text,'Évek óta tervez madárodúkat ebben a műhelyben.'::text),
(346809,38535,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er entwarf gerade das Vogelhaus, als er plötzlich ...: „Hab''s!“'::text,'sagte'::text,'gerade sagte'::text,'gesagt hat'::text,'Er entwarf gerade das Vogelhaus, als er plötzlich sagte: „Hab''s!“'::text),
(346813,38535,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він проєктував шпаківню, коли раптом ... «Є!»'::text,'сказав'::text,'казав'::text,'сказав'::text,'Він проєктував шпаківню, коли раптом сказав «Є!»'::text),
(346812,38535,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estaba diseñando la casita para pájaros cuando de repente ...: «¡Lo tengo!»'::text,'dijo'::text,'estaba diciendo'::text,'ha dicho'::text,'Estaba diseñando la casita para pájaros cuando de repente dijo: «¡Lo tengo!»'::text),
(346811,38535,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il concevait le nichoir quand, tout à coup, il ... : « J''ai trouvé ! »'::text,'a dit'::text,'disait'::text,'a dit'::text,'Il concevait le nichoir quand, tout à coup, il a dit : « J''ai trouvé ! »'::text),
(346814,38535,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kuş evini tasarlarken birden “Buldum!” ...'::text,'dedi'::text,'diyordu'::text,'dedi'::text,'Kuş evini tasarlarken birden “Buldum!” Dedi.'::text),
(346815,38535,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éppen a madárodút tervezte, amikor hirtelen ...: „Megvan!”'::text,'azt mondta'::text,'éppen azt mondta'::text,'azt mondta'::text,'Éppen a madárodút tervezte, amikor hirtelen azt mondta: „Megvan!”'::text),
(346818,38536,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er hat heute so fünf Vogelhäuser ..., ehrlich gesagt legendär.'::text,'entworfen'::text,'entworfen'::text,'entwirft gerade'::text,'Bro, er hat heute so fünf Vogelhäuser entworfen, ehrlich gesagt legendär.'::text),
(346822,38536,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він сьогодні ... десь п’ять шпаківень, реально легенда.'::text,'спроєктував'::text,'проєктував'::text,'проєктує'::text,'Бро, він сьогодні спроєктував десь п’ять шпаківень, реально легенда.'::text),
(346821,38536,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, hoy ... como cinco casitas para pájaros, en plan leyenda.'::text,'ha diseñado'::text,'ha estado diseñando'::text,'está diseñando'::text,'Bro, hoy ha diseñado como cinco casitas para pájaros, en plan leyenda.'::text),
(346820,38536,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il ... genre cinq nichoirs aujourd''hui, un vrai boss.'::text,'a conçu'::text,'a conçu'::text,'est en train de concevoir'::text,'Frérot, il a conçu genre cinq nichoirs aujourd''hui, un vrai boss.'::text),
(346823,38536,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bugün beş tane falan kuş evi ..., resmen efsane.'::text,'tasarladı'::text,'tasarlıyor'::text,'tasarlıyor'::text,'Kanka, bugün beş tane falan kuş evi tasarladı, resmen efsane.'::text),
(346824,38536,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ma vagy öt madárodút ..., kész legenda.'::text,'tervezett'::text,'tervezett'::text,'tervez'::text,'Tesó, ma vagy öt madárodút tervezett, kész legenda.'::text),
(346827,38537,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zur Deadline um 17 Uhr hatte er das Vogelhaus ... und auch gebaut.'::text,'entworfen'::text,'entworfen'::text,'entwirft'::text,'Bis zur Deadline um 17 Uhr hatte er das Vogelhaus entworfen und auch gebaut.'::text),
(346831,38537,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До дедлайну о 17:00 він ... шпаківню і ще й побудував її.'::text,'спроєктував'::text,'спроєктував'::text,'проєктує'::text,'До дедлайну о 17:00 він спроєктував шпаківню і ще й побудував її.'::text),
(346830,38537,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la fecha límite de las 17:00, ya ... la casita para pájaros y también la había construido.'::text,'había diseñado'::text,'ha diseñado'::text,'diseña'::text,'Para la fecha límite de las 17:00, ya había diseñado la casita para pájaros y también la había construido.'::text),
(346829,38537,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À l''échéance de 17 h, il ... le nichoir et l''avait aussi construit.'::text,'avait conçu'::text,'a conçu'::text,'conçoit'::text,'À l''échéance de 17 h, il avait conçu le nichoir et l''avait aussi construit.'::text),
(346832,38537,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 17.00''deki son teslim tarihine kadar kuş evini ... ve inşa da etmişti.'::text,'tasarlamıştı'::text,'tasarladı'::text,'tasarlıyor'::text,'Saat 17.00''deki son teslim tarihine kadar kuş evini tasarlamıştı ve inşa da etmişti.'::text),
(346833,38537,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A 17 órás határidőre már ... a madárodút, és meg is építette.'::text,'megtervezte'::text,'megtervezte'::text,'tervezi'::text,'A 17 órás határidőre már megtervezte a madárodút, és meg is építette.'::text),
(346836,38538,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um zwölf wird er gerade ein weiteres Vogelhaus ..., weil er genau das tun wird.'::text,'entwerfen'::text,'entwerfen'::text,'entwirft'::text,'Morgen um zwölf wird er gerade ein weiteres Vogelhaus entwerfen, weil er genau das tun wird.'::text),
(346840,38538,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра опівдні він ... ще одну шпаківню, бо саме це він і робитиме.'::text,'проєктуватиме'::text,'спроєктує'::text,'проєктує'::text,'Завтра опівдні він проєктуватиме ще одну шпаківню, бо саме це він і робитиме.'::text),
(346839,38538,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a mediodía ... otra casita para pájaros, porque eso es lo que estará haciendo.'::text,'estará diseñando'::text,'diseñará'::text,'diseña'::text,'Mañana a mediodía estará diseñando otra casita para pájaros, porque eso es lo que estará haciendo.'::text),
(346838,38538,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à midi, il ... un autre nichoir, parce que c''est ce qu''il sera en train de faire.'::text,'sera en train de concevoir'::text,'concevra'::text,'conçoit'::text,'Demain à midi, il sera en train de concevoir un autre nichoir, parce que c''est ce qu''il sera en train de faire.'::text),
(346841,38538,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın öğlen başka bir kuş evi ..., çünkü o sırada yapıyor olacağı şey bu.'::text,'tasarlıyor olacak'::text,'tasarlayacak'::text,'tasarlıyor'::text,'Yarın öğlen başka bir kuş evi tasarlıyor olacak, çünkü o sırada yapıyor olacağı şey bu.'::text),
(346842,38538,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap délben egy újabb madárodút ..., mert éppen ezt fogja csinálni.'::text,'fog tervezni'::text,'megtervez'::text,'tervez'::text,'Holnap délben egy újabb madárodút fog tervezni, mert éppen ezt fogja csinálni.'::text),
(346854,38540,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du ein Vogelhaus ..., baust du es auch wirklich. Respekt.'::text,'entwirfst'::text,'entwerfen wirst'::text,'entworfen hast'::text,'Wenn du ein Vogelhaus entwirfst, baust du es auch wirklich. Respekt.'::text),
(346858,38540,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ти ... шпаківню, то справді її будуєш. Респект.'::text,'проєктуєш'::text,'спроєктуєш'::text,'спроєктував'::text,'Якщо ти проєктуєш шпаківню, то справді її будуєш. Респект.'::text),
(346857,38540,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ... una casita para pájaros, de verdad la construyes. Respeto.'::text,'diseñas'::text,'diseñarás'::text,'diseñaste'::text,'Si diseñas una casita para pájaros, de verdad la construyes. Respeto.'::text),
(346856,38540,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu ... un nichoir, tu le construis vraiment. Respect.'::text,'conçois'::text,'concevras'::text,'as conçu'::text,'Si tu conçois un nichoir, tu le construis vraiment. Respect.'::text),
(346859,38540,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kuş evi ..., gerçekten de inşa edersin. Saygılar.'::text,'tasarlarsan'::text,'tasarlayacaksan'::text,'tasarladıysan'::text,'Bir kuş evi tasarlarsan, gerçekten de inşa edersin. Saygılar.'::text),
(346860,38540,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ... egy madárodút, tényleg meg is építed. Respekt.'::text,'megtervezel'::text,'meg fogsz tervezni'::text,'megterveztél'::text,'Ha megtervezel egy madárodút, tényleg meg is építed. Respekt.'::text),
(346863,38541,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du als Nächstes ein Vogelbad entwirfst, ... ich ganz vorne in der Schlange, ich lüg nicht.'::text,'stehe'::text,'stünde'::text,'stehe'::text,'Wenn du als Nächstes ein Vogelbad entwirfst, stehe ich ganz vorne in der Schlange, ich lüg nicht.'::text),
(346867,38541,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо наступною ти спроєктуєш купальню для птахів, я ... першим у черзі, не брехатиму.'::text,'буду'::text,'був би'::text,'є'::text,'Якщо наступною ти спроєктуєш купальню для птахів, я буду першим у черзі, не брехатиму.'::text),
(346866,38541,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si lo próximo que diseñas es un bebedero para pájaros, ... el primero de la fila, no voy a mentir.'::text,'seré'::text,'sería'::text,'soy'::text,'Si lo próximo que diseñas es un bebedero para pájaros, seré el primero de la fila, no voy a mentir.'::text),
(346865,38541,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu conçois une baignoire à oiseaux après, je ... le premier dans la file, je vais pas mentir.'::text,'serai'::text,'serais'::text,'suis'::text,'Si tu conçois une baignoire à oiseaux après, je serai le premier dans la file, je vais pas mentir.'::text),
(346868,38541,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sırada bir kuş banyosu tasarlarsan kuyrukta ilk ben ..., yalan yok.'::text,'olacağım'::text,'olurdum'::text,NULL::text,'Sırada bir kuş banyosu tasarlarsan kuyrukta ilk ben olacağım, yalan yok.'::text),
(346869,38541,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha legközelebb madáritatót tervezel, én ... az első a sorban, nem fogok hazudni.'::text,'leszek'::text,'lennék'::text,'vagyok'::text,'Ha legközelebb madáritatót tervezel, én leszek az első a sorban, nem fogok hazudni.'::text),
(346881,38543,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... er ein Vogelhaus auf Papier und baute es dann. Wirklich bahnbrechend.'::text,'entwarf'::text,'hatte entworfen'::text,'entwarf gerade'::text,'Gestern entwarf er ein Vogelhaus auf Papier und baute es dann. Wirklich bahnbrechend.'::text),
(346885,38543,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора він ... шпаківню на папері, а потім побудував її. Справді революційно.'::text,'спроєктував'::text,'спроєктував'::text,'проєктував'::text,'Учора він спроєктував шпаківню на папері, а потім побудував її. Справді революційно.'::text),
(346884,38543,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayer ... una casita para pájaros en papel y luego la construyó. Realmente revolucionario.'::text,'diseñó'::text,'había diseñado'::text,'estaba diseñando'::text,'Ayer diseñó una casita para pájaros en papel y luego la construyó. Realmente revolucionario.'::text),
(346883,38543,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, il ... un nichoir sur papier, puis il l''a construit. Vraiment révolutionnaire.'::text,'a conçu'::text,'avait conçu'::text,'concevait'::text,'Hier, il a conçu un nichoir sur papier, puis il l''a construit. Vraiment révolutionnaire.'::text),
(346886,38543,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün kâğıt üzerinde bir kuş evi ... ve sonra onu yaptı. Gerçekten çığır açıcı.'::text,'tasarladı'::text,'tasarlamıştı'::text,'tasarlıyordu'::text,'Dün kâğıt üzerinde bir kuş evi tasarladı ve sonra onu yaptı. Gerçekten çığır açıcı.'::text),
(346887,38543,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap ... egy madárodút papíron, aztán meg is építette. Igazán úttörő.'::text,'megtervezett'::text,'megtervezett'::text,'tervezett'::text,'Tegnap megtervezett egy madárodút papíron, aztán meg is építette. Igazán úttörő.'::text),
(403608,44846,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heute Morgen ... der leere Arbeitsplatz mit einer Regenbogenlampe und Büchern gefüllt.'::text,'wurde'::text,'wird'::text,'füllte'::text,'Heute Morgen wurde der leere Arbeitsplatz mit einer Regenbogenlampe und Büchern gefüllt.'::text),
(403612,44846,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні вранці порожнє робоче місце ... райдужною лампою та книжками.'::text,'було заповнене'::text,'заповнюється'::text,'заповнило'::text,'Сьогодні вранці порожнє робоче місце було заповнене райдужною лампою та книжками.'::text),
(403611,44846,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta mañana el espacio de trabajo vacío ... con una lámpara arcoíris y libros.'::text,'fue llenado'::text,'es llenado'::text,'llenó'::text,'Esta mañana el espacio de trabajo vacío fue llenado con una lámpara arcoíris y libros.'::text),
(403610,44846,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce matin, l''espace de travail vide ... d''une lampe arc-en-ciel et de livres.'::text,'a été rempli'::text,'est rempli'::text,'a rempli'::text,'Ce matin, l''espace de travail vide a été rempli d''une lampe arc-en-ciel et de livres.'::text),
(403613,44846,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sabah boş çalışma alanı gökkuşağı renkli bir lamba ve kitaplarla ...'::text,'dolduruldu'::text,'doldurulur'::text,'doldurdu'::text,'Bu sabah boş çalışma alanı gökkuşağı renkli bir lamba ve kitaplarla dolduruldu.'::text),
(403614,44846,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma reggel az üres munkasarkot ... egy szivárványos lámpával és könyvekkel.'::text,'megtöltötték'::text,'megtöltik'::text,'megtöltötte'::text,'Ma reggel az üres munkasarkot megtöltötték egy szivárványos lámpával és könyvekkel.'::text),
(403617,44847,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Arbeitsplatz ... mit 5 neuen Artikeln ausgestattet, voll im Rahmen des Budgets.'::text,'wurde'::text,'stattete'::text,'ausstattend'::text,'Ihr Arbeitsplatz wurde mit 5 neuen Artikeln ausgestattet, voll im Rahmen des Budgets.'::text),
(403621,44847,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її робоче місце ... 5 новими речами, повністю в межах бюджету.'::text,'було обладнане'::text,'обладнало'::text,'обладнуючи'::text,'Її робоче місце було обладнане 5 новими речами, повністю в межах бюджету.'::text),
(403620,44847,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su espacio de trabajo ... con 5 artículos nuevos, totalmente dentro del presupuesto.'::text,'fue equipado'::text,'equipó'::text,'equipando'::text,'Su espacio de trabajo fue equipado con 5 artículos nuevos, totalmente dentro del presupuesto.'::text),
(403619,44847,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son espace de travail ... de 5 nouveaux articles, parfaitement dans le budget.'::text,'a été équipé'::text,'a équipé'::text,'équipant'::text,'Son espace de travail a été équipé de 5 nouveaux articles, parfaitement dans le budget.'::text),
(403622,44847,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çalışma alanı bütçeye tamamen uygun olarak 5 yeni eşyayla ...'::text,'donatıldı'::text,'donattı'::text,'donatarak'::text,'Çalışma alanı bütçeye tamamen uygun olarak 5 yeni eşyayla donatıldı.'::text),
(403623,44847,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A munkasarkát 5 új tárggyal ..., teljesen a költségvetésen belül.'::text,'szerelték fel'::text,'szerelte fel'::text,'felszerelve'::text,'A munkasarkát 5 új tárggyal szerelték fel, teljesen a költségvetésen belül.'::text),
(403626,44848,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... heute Abend an diesem Arbeitsplatz arbeiten, aber sie hat sich noch nicht entschieden.'::text,'könnte'::text,'muss'::text,'kann nicht'::text,'Sie könnte heute Abend an diesem Arbeitsplatz arbeiten, aber sie hat sich noch nicht entschieden.'::text),
(403630,44848,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... попрацювати за цим робочим місцем сьогодні ввечері, але ще не вирішила.'::text,'може'::text,'мусить'::text,'не може'::text,'Вона може попрацювати за цим робочим місцем сьогодні ввечері, але ще не вирішила.'::text),
(403629,44848,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... trabajar en este espacio de trabajo esta noche, pero aún no lo ha decidido.'::text,'Podría'::text,'Debe'::text,'No puede'::text,'Podría trabajar en este espacio de trabajo esta noche, pero aún no lo ha decidido.'::text),
(403628,44848,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... travailler à cet espace de travail ce soir, mais elle n''a pas encore décidé.'::text,'pourrait'::text,'doit'::text,'ne peut pas'::text,'Elle pourrait travailler à cet espace de travail ce soir, mais elle n''a pas encore décidé.'::text),
(403631,44848,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşam bu çalışma alanında ..., ama henüz karar vermedi.'::text,'çalışabilir'::text,'çalışmalı'::text,'çalışamaz'::text,'Bu akşam bu çalışma alanında çalışabilir, ama henüz karar vermedi.'::text),
(403632,44848,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma este ... ezen a munkasarkon, de még nem döntött.'::text,'dolgozhat'::text,'dolgoznia kell'::text,'nem dolgozhat'::text,'Ma este dolgozhat ezen a munkasarkon, de még nem döntött.'::text),
(403635,44849,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Arbeitsplatz ist ein Bereich, ... eine Person typischerweise lernt oder arbeitet.'::text,'in dem'::text,'der'::text,'wer'::text,'Ein Arbeitsplatz ist ein Bereich, in dem eine Person typischerweise lernt oder arbeitet.'::text),
(403639,44849,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Робоче місце — це простір, ... людина зазвичай навчається або працює.'::text,'де'::text,'який'::text,'хто'::text,'Робоче місце — це простір, де людина зазвичай навчається або працює.'::text),
(403638,44849,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un espacio de trabajo es una zona ... una persona típicamente estudia o trabaja.'::text,'donde'::text,'que'::text,'quien'::text,'Un espacio de trabajo es una zona donde una persona típicamente estudia o trabaja.'::text),
(403637,44849,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un espace de travail est une zone ... une personne étudie ou travaille typiquement.'::text,'où'::text,'qui'::text,'qui'::text,'Un espace de travail est une zone où une personne étudie ou travaille typiquement.'::text),
(403640,44849,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çalışma alanı, ... bir kişinin tipik olarak ders çalıştığı ya da iş yaptığı bir alandır.'::text,''::text,NULL::text,NULL::text,'Çalışma alanı, bir kişinin tipik olarak ders çalıştığı ya da iş yaptığı bir alandır.'::text),
(403641,44849,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A munkaterület egy olyan hely, ... az ember jellemzően tanul vagy dolgozik.'::text,'ahol'::text,'amely'::text,'aki'::text,'A munkaterület egy olyan hely, ahol az ember jellemzően tanul vagy dolgozik.'::text),
(403644,44850,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast mir erzählt, dein Arbeitsplatz ... leer, und ehrlich, was für ein Glow-up.'::text,'war'::text,'ist'::text,'hat'::text,'Du hast mir erzählt, dein Arbeitsplatz war leer, und ehrlich, was für ein Glow-up.'::text),
(403648,44850,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти казала мені, що твоє робоче місце ... порожнім, і чесно, який глоу-ап.'::text,'було'::text,'є'::text,'має'::text,'Ти казала мені, що твоє робоче місце було порожнім, і чесно, який глоу-ап.'::text),
(403647,44850,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Me dijiste que tu espacio de trabajo ... vacío, y la verdad, menudo glow up.'::text,'estaba'::text,'está'::text,'tiene'::text,'Me dijiste que tu espacio de trabajo estaba vacío, y la verdad, menudo glow up.'::text),
(403646,44850,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu m''as dit que ton espace de travail ... vide, et franchement, quel glow up.'::text,'était'::text,'est'::text,'a'::text,'Tu m''as dit que ton espace de travail était vide, et franchement, quel glow up.'::text),
(403649,44850,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bana çalışma alanının boş ... söyledin, ve açıkçası, ne glow up ama.'::text,'olduğunu'::text,'olduğunu'::text,'sahip olduğunu'::text,'Bana çalışma alanının boş olduğunu söyledin, ve açıkçası, ne glow up ama.'::text),
(403650,44850,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondtad, hogy a munkasarkod ... üres, és őszintén, micsoda glow up.'::text,'volt'::text,NULL::text,'van'::text,'Azt mondtad, hogy a munkasarkod volt üres, és őszintén, micsoda glow up.'::text),
(403653,44851,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dein Arbeitsplatz ... ein leerer Schreibtisch; ich lüg nicht, du hast Style.'::text,'war früher'::text,'war'::text,'war gewohnt, zu sein'::text,'Dein Arbeitsplatz war früher ein leerer Schreibtisch; ich lüg nicht, du hast Style.'::text),
(403657,44851,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Твоє робоче місце ... голим столом; не брехатиму, у тебе є стиль.'::text,'було колись'::text,'бувало'::text,'звикло бути'::text,'Твоє робоче місце було колись голим столом; не брехатиму, у тебе є стиль.'::text),
(403656,44851,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu espacio de trabajo ... ser una mesa vacía; no voy a mentir, tienes estilo.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'Tu espacio de trabajo solía ser una mesa vacía; no voy a mentir, tienes estilo.'::text),
(403655,44851,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ton espace de travail ... un bureau tout nu ; je vais pas mentir, t''as du style.'::text,'était avant'::text,'était'::text,'était habitué à être'::text,'Ton espace de travail était avant un bureau tout nu ; je vais pas mentir, t''as du style.'::text),
(403658,44851,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çalışma alanın eskiden çıplak bir masa ...; yalan yok, tarzın var.'::text,'idi'::text,'olurdu'::text,'olmaya alışkındı'::text,'Çalışma alanın eskiden çıplak bir masa idi; yalan yok, tarzın var.'::text),
(403659,44851,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A munkasarkod régen egy csupasz asztal ...; nem fogok hazudni, van stílusod.'::text,'volt'::text,'volt'::text,'hozzá volt szokva, hogy legyen'::text,'A munkasarkod régen egy csupasz asztal volt; nem fogok hazudni, van stílusod.'::text),
(403662,44852,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du hast richtig Spaß daran, deinen Arbeitsplatz schön zu ...'::text,'machen'::text,'machen'::text,'machen'::text,'Ehrlich, du hast richtig Spaß daran, deinen Arbeitsplatz schön zu machen.'::text),
(403666,44852,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, тобі реально подобається ... своє робоче місце гарним.'::text,'робити'::text,'робити'::text,'робити'::text,'Чесно, тобі реально подобається робити своє робоче місце гарним.'::text),
(403665,44852,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, disfrutas de verdad ... que tu espacio de trabajo se vea bien.'::text,'haciendo'::text,'hacer'::text,'hacer'::text,'La verdad, disfrutas de verdad haciendo que tu espacio de trabajo se vea bien.'::text),
(403664,44852,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu adores vraiment ... ton espace de travail tout beau.'::text,'rendre'::text,'rendre'::text,'rendre'::text,'Franchement, tu adores vraiment rendre ton espace de travail tout beau.'::text),
(403667,44852,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, çalışma alanını ... gerçekten keyif alıyorsun.'::text,'güzelleştirmekten'::text,'güzelleştirmekten'::text,'güzelleştirmekten'::text,'Açıkçası, çalışma alanını güzelleştirmekten gerçekten keyif alıyorsun.'::text),
(403668,44852,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, tényleg élvezed ... a munkasarkodat.'::text,'szépíteni'::text,'szépíteni'::text,'szépíteni'::text,'Őszintén, tényleg élvezed szépíteni a munkasarkodat.'::text),
(403671,44853,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat jetzt ... Arbeitsplatz mit einer Regenbogenlampe. Sehr minimalistisch, natürlich.'::text,'einen einzigartigen'::text,'einen einzigartigen'::text,'den einzigartigen'::text,'Sie hat jetzt einen einzigartigen Arbeitsplatz mit einer Regenbogenlampe. Sehr minimalistisch, natürlich.'::text),
(403675,44853,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тепер у неї ... робоче місце з райдужною лампою. Дуже мінімалістично, звісно.'::text,'унікальне'::text,'унікальне'::text,'унікальне'::text,'Тепер у неї унікальне робоче місце з райдужною лампою. Дуже мінімалістично, звісно.'::text),
(403674,44853,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora tiene ... espacio de trabajo con una lámpara arcoíris. Muy minimalista, obviamente.'::text,'un singular'::text,'un singular'::text,'el singular'::text,'Ahora tiene un singular espacio de trabajo con una lámpara arcoíris. Muy minimalista, obviamente.'::text),
(403673,44853,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a maintenant ... avec une lampe arc-en-ciel. Très minimaliste, évidemment.'::text,'un espace de travail unique'::text,'un espace de travail unique'::text,'l''espace de travail unique'::text,'Elle a maintenant un espace de travail unique avec une lampe arc-en-ciel. Très minimaliste, évidemment.'::text),
(403676,44853,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Artık gökkuşağı lambalı ... çalışma alanı var. Çok minimalist, tabii ki.'::text,'eşsiz bir'::text,'eşsiz bir'::text,'eşsiz'::text,'Artık gökkuşağı lambalı eşsiz bir çalışma alanı var. Çok minimalist, tabii ki.'::text),
(403677,44853,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Most már ... munkasarka van szivárványos lámpával. Nagyon minimalista, nyilván.'::text,'egy egyedi'::text,'egy egyedi'::text,'az egyedi'::text,'Most már egy egyedi munkasarka van szivárványos lámpával. Nagyon minimalista, nyilván.'::text),
(403689,44855,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor sie die Lampe hinstellte, ... ihr Arbeitsplatz komplett leer gewesen.'::text,'war'::text,'ist'::text,'ist'::text,'Bevor sie die Lampe hinstellte, war ihr Arbeitsplatz komplett leer gewesen.'::text),
(403693,44855,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До того як вона поставила лампу, її робоче місце ... абсолютно голим.'::text,'було'::text,'було'::text,'є'::text,'До того як вона поставила лампу, її робоче місце було абсолютно голим.'::text),
(403692,44855,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de que añadiera la lámpara, su espacio de trabajo ... completamente vacío.'::text,'había estado'::text,'ha estado'::text,'está'::text,'Antes de que añadiera la lámpara, su espacio de trabajo había estado completamente vacío.'::text),
(403691,44855,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant qu''elle ajoute la lampe, son espace de travail ... complètement vide.'::text,'avait été'::text,'a été'::text,'est'::text,'Avant qu''elle ajoute la lampe, son espace de travail avait été complètement vide.'::text),
(403694,44855,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lambayı eklemeden önce çalışma alanı tamamen boş ...'::text,'idi'::text,'idi'::text,NULL::text,'Lambayı eklemeden önce çalışma alanı tamamen boş idi.'::text),
(403695,44855,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt odatette a lámpát, a munkasarka teljesen üres ...'::text,'volt'::text,'volt'::text,NULL::text,'Mielőtt odatette a lámpát, a munkasarka teljesen üres volt.'::text),
(346917,38547,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Motorhaube ... geöffnet, weil er sie aufgemacht hat. Deshalb sieht er so verzweifelt aus.'::text,'wurde'::text,'öffnete'::text,'öffnet'::text,'Die Motorhaube wurde geöffnet, weil er sie aufgemacht hat. Deshalb sieht er so verzweifelt aus.'::text),
(346921,38547,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Капот ..., бо він його відчинив. Тому він і виглядає таким розпачливим.'::text,'було відчинено'::text,'відчинив'::text,'відчиняє'::text,'Капот було відчинено, бо він його відчинив. Тому він і виглядає таким розпачливим.'::text),
(346920,38547,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El capó ... porque él lo abrió. Por eso parece tan desesperado.'::text,'fue abierto'::text,'abrió'::text,'está abriendo'::text,'El capó fue abierto porque él lo abrió. Por eso parece tan desesperado.'::text),
(346919,38547,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le capot ... parce qu''il l''a ouvert. C''est pour ça qu''il a l''air si désespéré.'::text,'a été ouvert'::text,'a ouvert'::text,'ouvre'::text,'Le capot a été ouvert parce qu''il l''a ouvert. C''est pour ça qu''il a l''air si désespéré.'::text),
(346922,38547,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaput ... çünkü onu o açtı. Bu yüzden bu kadar çaresiz görünüyor.'::text,'açıldı'::text,'açtı'::text,'açıyor'::text,'Kaput açıldı çünkü onu o açtı. Bu yüzden bu kadar çaresiz görünüyor.'::text),
(346923,38547,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A motorháztetőt ..., mert ő nyitotta ki. Ezért néz ki olyan kétségbeesettnek.'::text,'kinyitották'::text,'kinyitotta'::text,'nyitja'::text,'A motorháztetőt kinyitották, mert ő nyitotta ki. Ezért néz ki olyan kétségbeesettnek.'::text),
(346926,38548,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der verzweifelte Fahrer ... die Batteriepole, aber es entsteht kein Funke.'::text,'untersucht'::text,'wird untersucht'::text,'untersuchend'::text,'Der verzweifelte Fahrer untersucht die Batteriepole, aber es entsteht kein Funke.'::text),
(346930,38548,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Розпачливий водій ... клеми акумулятора, але іскри не виникає.'::text,'оглядає'::text,'оглядається'::text,'оглядаючи'::text,'Розпачливий водій оглядає клеми акумулятора, але іскри не виникає.'::text),
(346929,38548,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El conductor desesperado ... los bornes de la batería, pero no se produce ninguna chispa.'::text,'examina'::text,'es examinado'::text,'examinando'::text,'El conductor desesperado examina los bornes de la batería, pero no se produce ninguna chispa.'::text),
(346928,38548,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le conducteur désespéré ... les bornes de la batterie, mais aucune étincelle ne se produit.'::text,'examine'::text,'est examiné'::text,'examinant'::text,'Le conducteur désespéré examine les bornes de la batterie, mais aucune étincelle ne se produit.'::text),
(346931,38548,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çaresiz sürücü akü kutup başlarını ..., ama hiç kıvılcım oluşmuyor.'::text,'inceliyor'::text,'inceleniyor'::text,'inceleyerek'::text,'Çaresiz sürücü akü kutup başlarını inceliyor, ama hiç kıvılcım oluşmuyor.'::text),
(346932,38548,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kétségbeesett sofőr ... az akkumulátor sarujait, de nem keletkezik szikra.'::text,'megvizsgálja'::text,'meg van vizsgálva'::text,'vizsgálva'::text,'A kétségbeesett sofőr megvizsgálja az akkumulátor sarujait, de nem keletkezik szikra.'::text),
(346935,38549,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Regen mit einem toten Auto festzustecken – du ... verzweifelt sein. Trotzdem Respekt.'::text,'musst'::text,'könntest'::text,'kannst nicht'::text,'Im Regen mit einem toten Auto festzustecken – du musst verzweifelt sein. Trotzdem Respekt.'::text),
(346939,38549,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Застрягши під дощем із мертвою машиною, ти ... у розпачі. Все одно респект.'::text,'напевно'::text,'можливо'::text,'точно не'::text,'Застрягши під дощем із мертвою машиною, ти напевно у розпачі. Все одно респект.'::text),
(346938,38549,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Atrapado bajo la lluvia con un coche muerto, ... estar desesperado. Aun así, respeto.'::text,'debes de'::text,'podrías'::text,'no puedes'::text,'Atrapado bajo la lluvia con un coche muerto, debes de estar desesperado. Aun así, respeto.'::text),
(346937,38549,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Coincé sous la pluie avec une voiture en rade, tu ... être désespéré. Respect quand même.'::text,'dois'::text,'pourrais'::text,'ne peux pas'::text,'Coincé sous la pluie avec une voiture en rade, tu dois être désespéré. Respect quand même.'::text),
(346940,38549,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yağmurda bozuk bir arabayla mahsur kalmışsın, çaresiz ...; yine de saygılar.'::text,'olmalısın'::text,'olabilirsin'::text,'olamazsın'::text,'Yağmurda bozuk bir arabayla mahsur kalmışsın, çaresiz olmalısın; yine de saygılar.'::text),
(346941,38549,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beragadva az esőben egy lerobbant autóval ... kétségbe vagy esve. Azért respekt.'::text,'biztosan'::text,'talán'::text,'nem lehet, hogy'::text,'Beragadva az esőben egy lerobbant autóval biztosan kétségbe vagy esve. Azért respekt.'::text),
(346944,38550,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du bist der Typ Mensch, ... selbst verzweifelt noch die Motorhaube aufmacht. Respekt.'::text,'der'::text,'das'::text,'dessen'::text,'Du bist der Typ Mensch, der selbst verzweifelt noch die Motorhaube aufmacht. Respekt.'::text),
(346948,38550,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти з тих людей, ... відкривають капот, навіть коли в розпачі. Респект.'::text,'які'::text,'що'::text,'чиї'::text,'Ти з тих людей, які відкривають капот, навіть коли в розпачі. Респект.'::text),
(346947,38550,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eres el tipo de persona ... abre el capó incluso cuando está desesperada. Respeto.'::text,'que'::text,'el cual'::text,'cuya'::text,'Eres el tipo de persona que abre el capó incluso cuando está desesperada. Respeto.'::text),
(346946,38550,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'T''es le genre de personne ... ouvre le capot même quand elle est désespérée. Respect.'::text,'qui'::text,'lequel'::text,'dont'::text,'T''es le genre de personne qui ouvre le capot même quand elle est désespérée. Respect.'::text),
(346949,38550,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen ... çaresizken bile kaputu açan türden birisin. Saygılar.'::text,''::text,NULL::text,NULL::text,'Sen çaresizken bile kaputu açan türden birisin. Saygılar.'::text),
(346950,38550,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te az a fajta ember vagy, ... kétségbeesetten is kinyitja a motorháztetőt. Respekt.'::text,'aki'::text,'ami'::text,'akinek a'::text,'Te az a fajta ember vagy, aki kétségbeesetten is kinyitja a motorháztetőt. Respekt.'::text),
(346953,38551,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast gesagt, du ... nicht verzweifelt, aber du hast die Batterie wie ein Profi gecheckt. Respekt.'::text,'wärst'::text,'bist'::text,'warst'::text,'Du hast gesagt, du wärst nicht verzweifelt, aber du hast die Batterie wie ein Profi gecheckt. Respekt.'::text),
(346957,38551,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти сказав, що ... у розпачі, але перевірив той акумулятор як профі. Респект.'::text,'не був'::text,'не'::text,'не був'::text,'Ти сказав, що не був у розпачі, але перевірив той акумулятор як профі. Респект.'::text),
(346956,38551,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijiste que no ... desesperado, pero revisaste esa batería como un pro. Respeto.'::text,'estabas'::text,'estás'::text,'has estado'::text,'Dijiste que no estabas desesperado, pero revisaste esa batería como un pro. Respeto.'::text),
(346955,38551,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as dit que tu ... désespéré, mais tu as vérifié cette batterie comme un pro. Respect.'::text,'n''étais pas'::text,'n''es pas'::text,'n''as pas été'::text,'Tu as dit que tu n''étais pas désespéré, mais tu as vérifié cette batterie comme un pro. Respect.'::text),
(346958,38551,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çaresiz ... söyledin ama o aküyü bir profesyonel gibi kontrol ettin. Saygılar.'::text,'olmadığını'::text,'olmadığını'::text,'olmadığını'::text,'Çaresiz olmadığını söyledin ama o aküyü bir profesyonel gibi kontrol ettin. Saygılar.'::text),
(346959,38551,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondtad, hogy nem ... kétségbeesve, de úgy ellenőrizted azt az aksit, mint egy profi. Respekt.'::text,'voltál'::text,'vagy'::text,'voltál'::text,'Azt mondtad, hogy nem voltál kétségbeesve, de úgy ellenőrizted azt az aksit, mint egy profi. Respekt.'::text),
(346962,38552,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieses alte Auto ... früher zuverlässig. Jetzt ist er verzweifelt. Makellose Maschine, natürlich.'::text,'war'::text,'wäre'::text,'war gewohnt, zu sein'::text,'Dieses alte Auto war früher zuverlässig. Jetzt ist er verzweifelt. Makellose Maschine, natürlich.'::text),
(346966,38552,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ця стара машина ... надійною. Тепер він у розпачі. Бездоганний механізм, звісно.'::text,'колись була'::text,'була б'::text,'звикла бути'::text,'Ця стара машина колись була надійною. Тепер він у розпачі. Бездоганний механізм, звісно.'::text),
(346965,38552,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este coche viejo ... ser fiable. Ahora él está desesperado. Máquina impecable, obviamente.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'Este coche viejo solía ser fiable. Ahora él está desesperado. Máquina impecable, obviamente.'::text),
(346964,38552,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette vieille voiture ... fiable avant. Maintenant, il est désespéré. Machine parfaite, évidemment.'::text,'était'::text,'serait'::text,'avait l''habitude d''être'::text,'Cette vieille voiture était fiable avant. Maintenant, il est désespéré. Machine parfaite, évidemment.'::text),
(346967,38552,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu eski araba eskiden güvenilir ... – şimdi adam çaresiz. Kusursuz bir makine, tabii ki.'::text,'idi'::text,'olurdu'::text,'olmaya alışkındı'::text,'Bu eski araba eskiden güvenilir idi – şimdi adam çaresiz. Kusursuz bir makine, tabii ki.'::text),
(346968,38552,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a régi autó régen ... megbízható. Most kétségbe van esve. Hibátlan gép, nyilván.'::text,'volt'::text,'lett volna'::text,'hozzá volt szokva, hogy legyen'::text,'Ez a régi autó régen volt megbízható. Most kétségbe van esve. Hibátlan gép, nyilván.'::text),
(346971,38553,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er will verzweifelt vor Einbruch der Dunkelheit ... – ein entspannter Abend, eindeutig.'::text,'nach Hause kommen'::text,'nach Hause kommend'::text,'nach Hause kommen'::text,'Er will verzweifelt vor Einbruch der Dunkelheit nach Hause kommen – ein entspannter Abend, eindeutig.'::text),
(346975,38553,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він у розпачі хоче ... додому до темряви. Явно спокійний вечір.'::text,'дістатися'::text,'діставання'::text,'дістатися'::text,'Він у розпачі хоче дістатися додому до темряви. Явно спокійний вечір.'::text),
(346974,38553,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está desesperado por ... a casa antes de que oscurezca. Una tarde relajante, claramente.'::text,'llegar'::text,'llegando'::text,'llegar'::text,'Está desesperado por llegar a casa antes de que oscurezca. Una tarde relajante, claramente.'::text),
(346973,38553,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il veut désespérément ... chez lui avant la nuit. Une soirée détente, clairement.'::text,'rentrer'::text,'rentrant'::text,'rentrer'::text,'Il veut désespérément rentrer chez lui avant la nuit. Une soirée détente, clairement.'::text),
(346976,38553,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Karanlık çökmeden eve ... için can atıyor. Rahatlatıcı bir akşam, belli ki.'::text,'varmak'::text,'varmak'::text,'varmak'::text,'Karanlık çökmeden eve varmak için can atıyor. Rahatlatıcı bir akşam, belli ki.'::text),
(346977,38553,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kétségbeesetten igyekszik ... sötétedés előtt. Pihentető este, nyilván.'::text,'hazaérni'::text,'hazaérve'::text,'hazaér'::text,'Kétségbeesetten igyekszik hazaérni sötétedés előtt. Pihentető este, nyilván.'::text),
(346980,38554,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ist nicht besonders verzweifelt, ...? Ruht sich nur auf dem Bordstein aus, klar.'::text,'oder'::text,'oder'::text,'oder'::text,'Er ist nicht besonders verzweifelt, oder? Ruht sich nur auf dem Bordstein aus, klar.'::text),
(346984,38554,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він не дуже в розпачі, ...? Просто відпочиває на бордюрі, звісно.'::text,'правда'::text,'правда'::text,'правда'::text,'Він не дуже в розпачі, правда? Просто відпочиває на бордюрі, звісно.'::text),
(346983,38554,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No está muy desesperado, ¿...? Solo descansa en el bordillo, obviamente.'::text,'verdad'::text,'verdad'::text,'verdad'::text,'No está muy desesperado, ¿verdad? Solo descansa en el bordillo, obviamente.'::text),
(346982,38554,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il n''est pas très désespéré, ... ? Il se repose juste sur le trottoir, évidemment.'::text,'hein'::text,'hein'::text,'hein'::text,'Il n''est pas très désespéré, hein ? Il se repose juste sur le trottoir, évidemment.'::text),
(346985,38554,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pek çaresiz değil, ...? Sadece kaldırımda dinleniyor, tabii ki.'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Pek çaresiz değil, değil mi? Sadece kaldırımda dinleniyor, tabii ki.'::text),
(346986,38554,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nincs túlságosan kétségbe esve, ...? Csak pihen a járdaszegélyen, nyilván.'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Nincs túlságosan kétségbe esve, ugye? Csak pihen a járdaszegélyen, nyilván.'::text),
(346989,38555,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wollte das Auto unbedingt starten, und ... sein Freund am Telefon.'::text,'genauso'::text,'genauso'::text,'genauso wenig'::text,'Er wollte das Auto unbedingt starten, und genauso sein Freund am Telefon.'::text),
(346993,38555,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він відчайдушно хотів завести машину, і ... його друг на телефоні.'::text,'так само'::text,'так само'::text,'так само ні'::text,'Він відчайдушно хотів завести машину, і так само його друг на телефоні.'::text),
(346992,38555,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estaba desesperado por arrancar el coche, y ... su amigo al teléfono.'::text,'también'::text,'también'::text,'tampoco'::text,'Estaba desesperado por arrancar el coche, y también su amigo al teléfono.'::text),
(346991,38555,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il voulait désespérément démarrer la voiture, ... son pote au téléphone.'::text,'tout comme'::text,'tout comme'::text,'contrairement à'::text,'Il voulait désespérément démarrer la voiture, tout comme son pote au téléphone.'::text),
(346994,38555,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arabayı çalıştırmak için çaresizdi, telefondaki arkadaşı ...'::text,'da öyleydi'::text,'da öyle yaptı'::text,'da öyle değildi'::text,'Arabayı çalıştırmak için çaresizdi, telefondaki arkadaşı da öyleydi.'::text),
(346995,38555,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kétségbeesetten akarta beindítani az autót, és ... a barátja a telefonban.'::text,'ugyanígy'::text,'ugyanígy'::text,'ugyanígy nem'::text,'Kétségbeesetten akarta beindítani az autót, és ugyanígy a barátja a telefonban.'::text),
(347025,38559,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonnenuntergang wird sie ihr Ziel ..., sonst ist die ganze Reise ruiniert!'::text,'erreicht haben'::text,'erreichen'::text,'am Erreichen sein'::text,'Bis Sonnenuntergang wird sie ihr Ziel erreicht haben, sonst ist die ganze Reise ruiniert!'::text),
(347029,38559,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця вона ... до місця призначення, інакше вся подорож зіпсована!'::text,'дістанеться'::text,'дістанеться'::text,'діставатиметься'::text,'До заходу сонця вона дістанеться до місця призначення, інакше вся подорож зіпсована!'::text),
(347028,38559,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para el atardecer ... su destino, o todo el viaje estará arruinado!'::text,'habrá alcanzado'::text,'alcanzará'::text,'estará alcanzando'::text,'¡Para el atardecer habrá alcanzado su destino, o todo el viaje estará arruinado!'::text),
(347027,38559,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, elle ... sa destination, sinon tout le voyage est fichu !'::text,'aura atteint'::text,'atteindra'::text,'sera en train d''atteindre'::text,'D''ici le coucher du soleil, elle aura atteint sa destination, sinon tout le voyage est fichu !'::text),
(347030,38559,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar varış noktasına ..., yoksa bütün yolculuk mahvolur!'::text,'ulaşmış olacak'::text,'ulaşacak'::text,'ulaşıyor olacak'::text,'Gün batımına kadar varış noktasına ulaşmış olacak, yoksa bütün yolculuk mahvolur!'::text),
(347031,38559,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napnyugtára már ... az úti célját, különben az egész utazás tönkremegy!'::text,'elérte'::text,'el fogja érni'::text,'éppen eléri'::text,'Napnyugtára már elérte az úti célját, különben az egész utazás tönkremegy!'::text),
(347034,38560,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pass auf: Anscheinend wird sie, bis sie ihr Ziel erreicht, sechs Stunden lang ...'::text,'unterwegs gewesen sein'::text,'unterwegs sein'::text,'gereist sein'::text,'Pass auf: Anscheinend wird sie, bis sie ihr Ziel erreicht, sechs Stunden lang unterwegs gewesen sein.'::text),
(347038,38560,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай: кажуть, поки вона дістанеться до місця призначення, то вже ... шість годин.'::text,'подорожуватиме'::text,'подорожуватиме'::text,'проподорожує'::text,'Слухай: кажуть, поки вона дістанеться до місця призначення, то вже подорожуватиме шість годин.'::text),
(347037,38560,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha esto: al parecer, para cuando llegue a su destino, ... seis horas viajando.'::text,'llevará'::text,'estará'::text,'habrá viajado'::text,'Escucha esto: al parecer, para cuando llegue a su destino, llevará seis horas viajando.'::text),
(347036,38560,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute ça : apparemment, d''ici à ce qu''elle arrive à destination, elle ... pendant six heures.'::text,'aura voyagé'::text,'voyagera'::text,'aura voyagé'::text,'Écoute ça : apparemment, d''ici à ce qu''elle arrive à destination, elle aura voyagé pendant six heures.'::text),
(347039,38560,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şunu dinle: duyduğuma göre varış noktasına ulaştığında altı saattir ... olacakmış.'::text,'yolculuk ediyor'::text,'yolculuk ediyor'::text,'yolculuk etmiş'::text,'Şunu dinle: duyduğuma göre varış noktasına ulaştığında altı saattir yolculuk ediyor olacakmış.'::text),
(347040,38560,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj: állítólag mire eléri az úti célját, már hat órája ...'::text,'utazik'::text,'fog utazni'::text,'utazott'::text,'Figyelj: állítólag mire eléri az úti célját, már hat órája utazik.'::text),
(347043,38561,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie den Leuchtturm nicht eingekreist hätte, ... sie dieses Ziel nicht gewählt.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn sie den Leuchtturm nicht eingekreist hätte, hätte sie dieses Ziel nicht gewählt.'::text),
(347047,38561,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не обвела маяк, то ... цього місця призначення.'::text,'не обрала б'::text,'не обере'::text,'не обрала'::text,'Якби вона не обвела маяк, то не обрала б цього місця призначення.'::text),
(347046,38561,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera rodeado el faro con un círculo, ... ese destino.'::text,'no habría elegido'::text,'no elegirá'::text,'no eligió'::text,'Si no hubiera rodeado el faro con un círculo, no habría elegido ese destino.'::text),
(347045,38561,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle n''avait pas entouré le phare, elle ... cette destination.'::text,'n''aurait pas choisi'::text,'ne choisira pas'::text,'n''a pas choisi'::text,'Si elle n''avait pas entouré le phare, elle n''aurait pas choisi cette destination.'::text),
(347048,38561,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deniz fenerini daire içine almasaydı o varış noktasını ...'::text,'seçmezdi'::text,'seçmeyecek'::text,'seçmedi'::text,'Deniz fenerini daire içine almasaydı o varış noktasını seçmezdi.'::text),
(347049,38561,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem karikázta volna be a világítótornyot, nem ... azt az úti célt.'::text,'választotta volna'::text,'fogja választani'::text,'választotta'::text,'Ha nem karikázta volna be a világítótornyot, nem választotta volna azt az úti célt.'::text),
(347052,38562,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, hätte sie den Zug nicht erwischt, ... sie jetzt nicht an ihrem Ziel, ohne Witz.'::text,'wäre'::text,'wäre gewesen'::text,'wird'::text,'Nee, hätte sie den Zug nicht erwischt, wäre sie jetzt nicht an ihrem Ziel, ohne Witz.'::text),
(347056,38562,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, якби вона не встигла на той потяг, то зараз ... у місці призначення, без брехні.'::text,'не була б'::text,'не була б'::text,'не буде'::text,'Не, якби вона не встигла на той потяг, то зараз не була б у місці призначення, без брехні.'::text),
(347055,38562,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, si no hubiera cogido ese tren, ahora no ... en su destino, sin mentir.'::text,'estaría'::text,'habría estado'::text,'estará'::text,'Qué va, si no hubiera cogido ese tren, ahora no estaría en su destino, sin mentir.'::text),
(347054,38562,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, si elle n''avait pas pris ce train, elle ... à destination maintenant, sans mentir.'::text,'ne serait pas'::text,'n''aurait pas été'::text,'ne sera pas'::text,'Nan, si elle n''avait pas pris ce train, elle ne serait pas à destination maintenant, sans mentir.'::text),
(347057,38562,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, o treni yakalamasaydı şimdi varış noktasında ..., yalan yok.'::text,'olmazdı'::text,'olmamış olurdu'::text,'olmayacak'::text,'Yok, o treni yakalamasaydı şimdi varış noktasında olmazdı, yalan yok.'::text),
(347058,38562,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, ha nem érte volna el azt a vonatot, most nem ... az úti céljánál, komolyan.'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Á, ha nem érte volna el azt a vonatot, most nem lenne az úti céljánál, komolyan.'::text),
(347070,38564,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie versprach, ihr Ziel bis zur Deadline um 19 Uhr zu ...'::text,'erreichen'::text,'erreichen'::text,'erreicht'::text,'Sie versprach, ihr Ziel bis zur Deadline um 19 Uhr zu erreichen.'::text),
